async function v592RefreshTestnetUniverse(force=false){
  const now=Date.now();
  if(!force&&v592TestnetUniverse.set&&now-v592TestnetUniverse.ts<V592_TESTNET_UNIVERSE_TTL_MS)return v592TestnetUniverse.set;
  if(v592TestnetUniverse.fetching)return v592TestnetUniverse.set;
  v592TestnetUniverse.fetching=true;
  try{
    const r=await fetch(`${BINANCE_EXECUTION_FAPI}/fapi/v1/exchangeInfo`,{signal:AbortSignal.timeout(15000)});
    if(!r.ok)throw new Error(`exchangeInfo HTTP ${r.status}`);
    const j=await r.json();
    const set=new Set();
    for(const sm of (Array.isArray(j?.symbols)?j.symbols:[])){
      if(String(sm?.status||'').toUpperCase()!=='TRADING')continue;
      if(String(sm?.contractType||'PERPETUAL').toUpperCase()!=='PERPETUAL')continue;
      if(String(sm?.quoteAsset||'').toUpperCase()!=='USDT')continue;
      set.add(String(sm.symbol).toUpperCase());
    }
    if(set.size>0){
      v592TestnetUniverse.set=set;v592TestnetUniverse.ts=now;v592TestnetUniverse.lastError=null;
      v592ParityStats.testnetUniverseSize=set.size;
      try{console.log(`[V592] testnet sembol evreni: ${set.size} PERPETUAL USDT`);}catch(_){}
    }
    return v592TestnetUniverse.set;
  }catch(e){
    v592TestnetUniverse.lastError=String(e?.message||e);v592TestnetUniverse.lastErrorAt=now;
    try{pushCritical('TESTNET_UNIVERSE',`exchangeInfo alinamadi: ${v592TestnetUniverse.lastError}`,{},'WARNING');}catch(_){}
    return v592TestnetUniverse.set;
  }finally{v592TestnetUniverse.fetching=false;}
}
