        const ageMs=Math.max(0,Date.now()-Number(lock.at||Date.now()));
        Object.assign(lock,{negativeProofs,lastCheckedAt:Date.now(),lastCheckResult:'FLAT_NO_OPEN_ENTRY_NO_ORDER_PROOF',lastError:null});
