// Amaç: tarama/pozisyon/SLTP çağrılarını tek sıraya alıp 429/418/-1003 riskini azaltmak.
// Kesin Binance limitine yaslanmak yerine güvenli alt eşik kullanılır; WS verisi analizde önceliklidir.
const binanceGov = {
  q: Promise.resolve(),
  priorityQ: Promise.resolve(),
  minuteStart: Date.now(),
  usedWeight: 0,
  usedOrders: 0,
  backoffUntil: 0,      // PUBLIC  = fapi.binance.com     (mainnet piyasa verisi)
  execBackoffUntil: 0,  // EXEC    = testnet.binancefuture.com (imzali emir/hesap)
  last429At: 0,
};
const sleep = (ms) => new Promise(r => setTimeout(r, Math.max(0, Number(ms)||0)));
function _resetGovWindowIfNeeded() {
  // ═══ V612 ═══ PENCERE DUVAR SAATINE HIZALANDI.
  // Binance'in x-mbx-used-weight-1m sayaci duvar saati dakikasinda sifirlanir.
  // Eski kod pencereyi "now"dan baslatiyordu; iki pencere hicbir zaman ortusmuyor,
  // r48638SyncGovHeaders'in Math.max'i eski tepe degeri bir dakikaya kadar
  // kilitli tutuyor ve HER public cagri dakika sonuna kadar uyutuluyordu
  // (AbortSignal.timeout(30000) once patliyor -> analiz timeout -> 16/16 atlama).
  const now = Date.now();
  const _w612 = Math.floor(now / 60000) * 60000;
  if (binanceGov.windowId !== _w612) {
    binanceGov.windowId = _w612;
    binanceGov.minuteStart = _w612;
    binanceGov.usedWeight = 0;
    binanceGov.usedOrders = 0;
  }
}
// R486.3.9: Binance'in gerçek kullanım başlıklarını governor'a geri besle.
// Böylece sabit süreyle kör frenlemek yerine mevcut REST yüküne göre adaptif reaksiyon verilir.
function r48638SyncGovHeaders(res) {
  try {
    if (!res?.headers) return;
    _resetGovWindowIfNeeded();
    const w = Number(res.headers.get('x-mbx-used-weight-1m') || res.headers.get('X-MBX-USED-WEIGHT-1M'));
    const o = Number(res.headers.get('x-mbx-order-count-1m') || res.headers.get('X-MBX-ORDER-COUNT-1M'));
    if (Number.isFinite(w) && w >= 0) binanceGov.usedWeight = Math.max(Number(binanceGov.usedWeight||0), w);
    if (Number.isFinite(o) && o >= 0) binanceGov.usedOrders = Math.max(Number(binanceGov.usedOrders||0), o);
  } catch(_) {}
}
const BINANCE_WEIGHT_LIMIT_1M = 2400;
const BINANCE_SIGNED_PRIORITY_CEILING = 2320;
// ═══ V611 ═══ Public arastirma tavani 900 idi; Binance'in gercek siniri 2400.
// Olculdu: usedWeight 1463 (imzali cagrilar ayni kovayi kullaniyor) > 900 ->
// HER public cagri dakika sonuna kadar uyutuluyordu -> 16/16 sembol timeout.
// 429/418 korumasi (registerHttpBackoffAndThrow) aynen yerinde.
// ═══ V612 ═══ TEK BUTCE MODELI.
// TESTNET'te public (fapi.binance.com) ve imzali (testnet.binancefuture.com) AYRI
// IP kovalariydi. CANLIDA IKISI DE fapi.binance.com -> TEK kova, tek 2400.
// Iki bagimsiz tavan yerine: toplam sinir eksi emir rezervi.
const V612_AGIRLIK_SINIR = Math.max(600, Math.min(2400, Number(process.env.V612_AGIRLIK_SINIR || 2400)));
const V612_EMIR_REZERV   = Math.max(100, Math.min(1200, Number(process.env.V612_EMIR_REZERV   || 500)));
const BINANCE_PUBLIC_RESEARCH_CEILING = (function(){
  const _ov = Number(process.env.V611_PUBLIC_CEILING || 0);
  if (_ov > 0) return Math.max(300, Math.min(2300, _ov));            // eski kacis kapisi
  return Math.max(300, Math.min(2300, V612_AGIRLIK_SINIR - V612_EMIR_REZERV));
})();
// ═══ V611 ═══ Public cagrilar arasi yapay gecikme. 180ms idi; tek sirali kuyrukta
// 16 cagri = 2,9sn/sembol, 24 sembol = 69sn sirf bekleme.
const V611_PUBLIC_DELAY_MS = Math.max(0, Math.min(500, Number(process.env.V611_PUBLIC_DELAY_MS || 60)));
function r48638GovLoadRatio() {
  _resetGovWindowIfNeeded();
  return Math.max(0, Math.min(1.25, Number(binanceGov.usedWeight||0) / BINANCE_WEIGHT_LIMIT_1M));
}
async function binanceThrottle(scope='REST', weight=1, orderWeight=0) {
  const s=String(scope||'');
  const positionTruthScope=/(positionRisk|POSITION_TRUTH)/i.test(s);
  const executionCritical=positionTruthScope||/(EMERGENCY|R495_EXACT|SIGNED:.*\/fapi\/v[123]\/(order|leverage|marginType|balance|account|positionRisk))/i.test(s);
  const job = async () => {
    _resetGovWindowIfNeeded();
    const started=Date.now(),now=Date.now();
    // ═══ V620 ═══ PUBLIC FRENI ARTIK EMIR YOLUNU KILITLEMIYOR.
    // backoffUntil PUBLIC kovasidir (satir ~1005 kendi yorumu). Eski satir onu
    // imzali/emir cagrilarina da uyguluyordu; V508_BACKOFF_MAX_SEC=3600 oldugu icin
    // tek public 418, /fapi/v2/account cagrisini BIR SAAT uyutuyordu.
    // Olculdu: positionRisk 3827sn asili · BIO/HYPE/ARB/EDGE emirleri gonderilemedi.
    if (String(process.env.V620_FREN_AYRIMI ?? '1') !== '0') {
      const _v620Kova = executionCritical ? Number(binanceGov.execBackoffUntil||0) : Number(binanceGov.backoffUntil||0);
      if (_v620Kova > now && !s.includes('EMERGENCY')) {
        const _v620Bek = _v620Kova - now + 50;
        if (_v620Bek > V620_FREN_TAVAN_MS) {
          const _e = new Error(`V620_FREN_TAVANI:${Math.round(_v620Bek/1000)}sn kova=${executionCritical?'EXEC':'PUBLIC'} kapsam=${s.slice(0,50)}`);
          _e.code = 'V620_BACKOFF_DEADLINE';
          throw _e;   // paylasilan kuyrugu tikamak yerine hizli hata
        }
        await sleep(_v620Bek);
      }
    } else {
      if (binanceGov.backoffUntil > now && !s.includes('EMERGENCY')) await sleep(binanceGov.backoffUntil - now + 50);
    }
    _resetGovWindowIfNeeded();
    const weightLimit = executionCritical ? BINANCE_SIGNED_PRIORITY_CEILING : BINANCE_PUBLIC_RESEARCH_CEILING;
    if (binanceGov.usedWeight + weight > weightLimit || binanceGov.usedOrders + orderWeight > 70) {
      const wait = 60_000 - (Date.now() - binanceGov.minuteStart) + 250;
      if(positionTruthScope){posRiskCache.phase='GOVERNOR_WAIT';posRiskCache.lastGovernorWaitMs=Math.max(0,wait);}
      await sleep(wait);
      _resetGovWindowIfNeeded();
    }
    binanceGov.usedWeight += weight;
    binanceGov.usedOrders += orderWeight;
    const baseDelay = orderWeight ? 50 : (executionCritical ? 15 : (s.includes('PUBLIC') ? V611_PUBLIC_DELAY_MS : 100));  // V611
    await sleep(baseDelay);
    if(positionTruthScope)posRiskCache.lastGovernorWaitMs=Math.max(0,Date.now()-started-baseDelay);
  };
  const key=executionCritical?'priorityQ':'q';
  const prev = binanceGov[key].catch(()=>{});
  binanceGov[key] = prev.then(job, job);
  return binanceGov[key];
}
// V4.7.4.11-L: fapi.binance.com (PUBLIC/mainnet) ve testnet.binancefuture.com (EXEC)
// AYRI hostlardir, AYRI rate-limit kovalaridir. Tek global fren yuzunden testnet
// tarafindaki 418, mainnet taramasini da donduruyordu -> bot hic tarama yapamiyordu.
// ══ V5.0.8 — BACKOFF KALICILIGI ═════════════════════════════════════
// binanceGov.execBackoffUntil YALNIZ BELLEKTEYDI. Restart onu sifirliyordu;
// bot yasak ortasinda acilip hemen cagri yapiyor ve yasagi uzatiyordu.
// Bu, daha once katalogladigim "restart'ta olen state" hata sinifidir (BF).
// ══ V5.0.9 — BACKTEST SL SOZLESMESI (1461/1461 DOGRULANDI) ══════════
// B1/B6 KAPANDI. Uc sozlesme gercek Binance verisine karsi olculdu:
//   1) entry = candidateTs+180000 anindaki 1m mumun close'u   1461/1461, fark 0
//   2) ATR   = TR'nin 14 periyot BASIT ortalamasi (Wilder DEGIL) 1461/1461
//   3) SL    = asagidaki formul                                 1461/1461, fark 0
