//        recentLow = min(low[-7:])
//        rawStop   = min(recentLow, close - 1.45*atr)
//        slPct     = clamp((close-rawStop)/close*100, 1.2, 8.0)
//        sl        = close * (1 - slPct/100)
// Formul r495Exact.candidateMetaFromCompact5m icinde ZATEN vardi; kimse
// backtest verisine karsi sinamamisti. "Kayip uretici" kayip degilmis.
// Bu sabitler acilis kapisinda denetlenir ki bir daha sessizce degismesin.
// ══ V5.1.1 — ZAMAN ASIMI SABITLERI ═════════════════════════════════
// Node fetch'in VARSAYILAN TIMEOUT'U YOKTUR. Timeout verilmeyen her fetch
// ust kaynak takilirsa SONSUZA DEK bekler. Tarama dongusunde bu, botun
// tamamen olmesi demek (olculdu: 8+ dakika, 0 tarama, log yok).
const V511_SCAN_WATCHDOG_MS   = Math.max(120000, Math.min(1800000, Number(process.env.V511_SCAN_WATCHDOG_MS||360000)));
const V511_MOOD_FETCH_MS      = Math.max(1500, Math.min(15000, Number(process.env.V511_MOOD_FETCH_MS||4000)));
const V511_ORDER_FETCH_MS     = Math.max(10000, Math.min(120000, Number(process.env.V511_ORDER_FETCH_MS||45000)));
const V509_SL_ATR_CARPANI   = 1.45;
const V509_SL_ATR_PERIYOT   = 14;
const V509_SL_LOW_PENCERE   = 7;
const V509_SL_PCT_MIN       = 1.2;
const V509_SL_PCT_MAX       = 8.0;
const V509_PLAN_TARGET_R    = 2.4;    // runner degilse
const V509_PLAN_TARGET_CAP  = 1.12;   // entry * 1.12 tavani
const V508_BACKOFF_MAX_SEC = Math.max(60, Math.min(7200, Number(process.env.V508_BACKOFF_MAX_SEC || 3600)));
const V508_BACKOFF_PATH = path.join(String(process.env.TESTNET_STATE_DIR||'/data').trim()||'/data','lazarus_binance_backoff.json');
function v508SaveBackoff(){
  try{
    const tmp=V508_BACKOFF_PATH+'.tmp';
    fs.writeFileSync(tmp,JSON.stringify({v:1,
      execBackoffUntil:Number(binanceGov.execBackoffUntil||0),
      backoffUntil:Number(binanceGov.backoffUntil||0),
      savedAt:Date.now()}));
    fs.renameSync(tmp,V508_BACKOFF_PATH);   // atomik
  }catch(_){}
}
function v508LoadBackoff(){
  try{
    const j=JSON.parse(fs.readFileSync(V508_BACKOFF_PATH,'utf8'));
    const now=Date.now();
    const e=Number(j.execBackoffUntil||0), p2=Number(j.backoffUntil||0);
    if(e>now) binanceGov.execBackoffUntil=Math.max(binanceGov.execBackoffUntil||0,e);
    if(p2>now) binanceGov.backoffUntil=Math.max(binanceGov.backoffUntil||0,p2);
    if(e>now||p2>now) try{console.log(`[V508] onceki yasak surdurulyor: EXEC ${Math.max(0,Math.ceil((e-now)/1000))}sn · PUBLIC ${Math.max(0,Math.ceil((p2-now)/1000))}sn`);}catch(_){}
  }catch(_){}
}
try{ v508LoadBackoff(); }catch(_){}   // V5.0.8: acilista onceki yasagi surdur
function registerBinanceBackoff(reason='rate-limit', seconds=45, domain='PUBLIC') {
  // V5.0.8: ikinci tavan da kaldirildi. Binance'in verdigi sureye uyulur.
  const sec = Math.max(5, Math.min(V508_BACKOFF_MAX_SEC, Number(seconds)||45));
  const dom = String(domain||'PUBLIC').toUpperCase();
  const until = Date.now() + sec*1000;
  if (dom==='EXEC'   || dom==='BOTH') binanceGov.execBackoffUntil = Math.max(binanceGov.execBackoffUntil || 0, until);
  if (dom==='PUBLIC' || dom==='BOTH') binanceGov.backoffUntil     = Math.max(binanceGov.backoffUntil     || 0, until);
  binanceGov.last429At = Date.now();
  v508SaveBackoff();   // V5.0.8: restart yasagi sifirlamasin
  try { pushCritical('BINANCE_BACKOFF', `${reason}: ${sec}sn istek bekleme [${dom}]`, {seconds:sec, reason, domain:dom}, 'WARNING'); } catch(_) {}
}
// R95: Binance 418/429 geldiğinde istek bekleyip taramayı kilitleme; merkezi frenle güvenli dur.
function isBinanceBackoffActive() {
  return Date.now() < Number(binanceGov.backoffUntil || 0);
}
function getBinanceBackoffMs() {
  return Math.max(0, Number(binanceGov.backoffUntil || 0) - Date.now());
}
// V4.7.4.11-L: imzali testnet yolu icin ayri fren.
function isExecBackoffActive() {
  // V5.1.0 DUZELTME: V5.0.8'de sayac BU FONKSIYONUN ICINDEYDI. Fonksiyonu
  // status endpoint'i de cagiriyor (execBackoffActive: isExecBackoffActive()),
  // yani JSON'a her bakista sayi artiyordu. Engellenen cagriyi degil GOZLEMCIYI
  // olcuyordu -> devir belgesindeki AS3 sinifi. Sayac artik gercek engelleme
  // noktalarina tasindi ve HANGI kapinin kestigi ayri ayri yaziliyor.
  return Date.now() < Number(binanceGov.execBackoffUntil || 0);
}
// V5.1.0: gercek engelleme noktasi. AS2 (sayacsiz erken return/throw) icin:
// her erken cikisin kendi sayaci var ve nerede kesildigi kayitli.
function noteExecBackoffBlock(nerede) {
  try{
    v592ParityStats.execBackoffBlocked=(v592ParityStats.execBackoffBlocked||0)+1;
    v592ParityStats.execBackoffBlockedBy=v592ParityStats.execBackoffBlockedBy||{};
    v592ParityStats.execBackoffBlockedBy[nerede]=(v592ParityStats.execBackoffBlockedBy[nerede]||0)+1;
  }catch(_){}
}
function getExecBackoffMs() {
  return Math.max(0, Number(binanceGov.execBackoffUntil || 0) - Date.now());
}
function makeBinanceBackoffError(reason='Binance istek freni', seconds=45, status=null) {
  const e = new Error(`${reason}: ${Math.ceil(Number(seconds)||0)}sn merkezi istek freni`);
  e.code = 'BINANCE_BACKOFF_ACTIVE';
  e.status = status;
  e.retryAfter = Number(seconds)||0;
  return e;
}
function registerHttpBackoffAndThrow(scope, status, retryHeader, domain='PUBLIC') {
  // V5.0.7: 418/429 olaylari funnel'a. Kendi trafigimiz olculdu (0,16 imzali
  // cagri/dk); 418 disaridan geliyorsa bu kayitlar zaman icinde bunu gosterir.
  try{ if(typeof r501EvidenceFunnel==='function') r501EvidenceFunnel({
    type:'BINANCE_RATE_LIMIT',action:'RATE_LIMIT',authority:domain==='EXEC'?'TESTNET_EXECUTION':'PUBLIC_MARKET',
    symbol:null,decisionImpact:true,orderBlocking:domain==='EXEC',
    httpStatus:status,scope:String(scope||'').slice(0,120),domain,retryAfter:retryHeader||null,
    reason:`HTTP ${status} ${domain} ${String(scope||'').slice(0,80)}`}); }catch(_){}
  // R154: 418 global backoff 180sn→60sn. positionRisk kendi cooldown'unda ayrıca 90sn bekler.
  // 180sn tüm sistemi durduruyordu; 60sn yeterli — positionRisk zaten kendi TTL/cooldown ile korunur.
  // ══ V5.0.8 — YASAK SURESINE GERCEKTEN UYULUYOR ════════════════════
  // OLCULDU 12.08 (V507_72H_TEMIZ_1): 4,9 saatte 29 adet 418. 28 olayin 25'i
  // ONCEKI YASAK BITMEDEN yapilan cagriydi. Ornek:
  //   14:43:38  retryAfter 3441 sn (57 dk)
  //   14:45:45  -> 127 sn sonra tekrar arandi (tam 120sn tavani)
  // Zincirin nasil buyudugu:
  //   18:31:46 yasak   69 sn -> 33 sn erken cagri  -> yasak  879 sn
  //   18:44:38 yasak 1760 sn -> 142 sn erken cagri -> yasak 2077 sn
  // Binance tekrarlanan ihlalde yasagi UZATIR. Birlesik gercek yasak suresi
  // olcum penceresinin %45'i oldu (2,2 saat / 4,9 saat).
  //
  // KOK SEBEP: Math.min(120, retry). Binance 3441 dedi, kod 120'ye kirpti.
  // Eski yorum "180sn tum sistemi durduruyordu; 60sn yeterli" diyordu — ama
  // erken cagri sistemi durdurmuyor, YASAGI BUYUTUYOR. Beklemek daha ucuz.
  const retry = parseInt(retryHeader || (Number(status) === 418 ? '60' : '60'), 10);
  const sec = Math.max(Number(status) === 418 ? 60 : 30, Math.min(V508_BACKOFF_MAX_SEC, Number(retry)||60));
  registerBinanceBackoff(`HTTP ${status} ${scope}`, sec, domain);
  throw makeBinanceBackoffError(`HTTP ${status} ${scope}`, sec, status);
}

// ── RATE LIMIT ────────────────────────────────────────────────────────────────
let reqCount=0, reqWindow=Date.now();
// ── ALGO ORDER (yeni coinler için: OPG, PENDLE, HUSDT vb.) ──────────────────
// Signature query string'de, body JSON — Binance algo endpoint zorunluluğu
async function bAlgo(apiKey, apiSecret, params, _retry=false) {
  ({apiKey,apiSecret}=r486391BinanceCreds());   // CANLI-C3
  if(!apiKey||!apiSecret) throw new Error(`${BINANCE_EXECUTION_ENV} API key/secret eksik (${r486391BinanceCreds().envVars.join('/')})`);
  // Binance SIGNED endpoint kuralı: imza, gönderilen TÜM parametrelerin
  // query string hali üzerinden üretilmelidir. Önceki sürüm sadece
  // timestamp/recvWindow imzalayıp algo parametrelerini JSON body'de yolluyordu;
  // bu da /fapi/v1/algoOrder üzerinde -1022 INVALID_SIGNATURE üretebiliyordu.
  await binanceThrottle('ALGO_ORDER', 2, 1);
  if (!lastTimeSync) await syncBinanceTime(false);
  const ts = Date.now() + binanceTimeOffset;
  const obj = { ...params, timestamp: ts, recvWindow: 10000 };
  const fullQs = signedQueryString(obj, apiSecret);
  const url = `${BINANCE_EXECUTION_FAPI}/fapi/v1/algoOrder?${fullQs}`;
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'X-MBX-APIKEY': String(apiKey || '').trim() },
    signal: AbortSignal.timeout(10000),
  });
  r48638SyncGovHeaders(res);
  if (res.status === 429 || res.status === 418) {
    registerHttpBackoffAndThrow('algoOrder', res.status, res.headers.get('Retry-After'), 'EXEC');
  }
  const text = await res.text();
  let data;
  try { data = JSON.parse(text); }
  catch(e) { throw new Error(`Algo JSON hatası: ${text.substring(0,100)}`); }
  if (data.code && data.code < 0) {
    if (Number(data.code) === -1021 && !_retry) {
      await syncBinanceTime(true);
      return bAlgo(apiKey, apiSecret, params, true);
    }
    if (Number(data.code) === -1003) registerBinanceBackoff('Binance -1003 algoOrder', 60, 'EXEC');
    throw new Error(formatBinanceError('/fapi/v1/algoOrder', data));
  }
  return data;
}

// ── ALGO CANCEL — tüm algo emirlerini iptal et (2025-12-09 sonrası zorunlu) ──
async function cancelAlgoOrders(apiKey, apiSecret, symbol, emergency=false) {
  // 1. Normal emirleri iptal et (MARKET vs.)
  const em = emergency ? {__emergency:true} : {};
  try { await bReq(apiKey, apiSecret, 'DELETE', '/fapi/v1/allOpenOrders', {symbol, ...em}); } catch(e) {}
  // 2. Algo emirlerini de iptal et (STOP_MARKET, TP artık algo)
  try { await bReq(apiKey, apiSecret, 'DELETE', '/fapi/v1/algoOpenOrders', {symbol, ...em}); } catch(e) {}
}

// ── ALGO SL/TP — Lazarus V8.10.72 kanıtlanmış format ───────────────────────
// DOĞRU: algoType=CONDITIONAL + type=STOP_MARKET/TAKE_PROFIT_MARKET
//        + triggerPrice (stopPrice DEĞİL) + closePosition=true
//        quantity ve reduceOnly GÖNDERİLMEZ — Lazarus V8.10.72 notunda açıkça belirtilmiş
// YANLIŞ olan: orderType=STOP, stopPrice, quantity, reduceOnly (bizim eski kod)
// V6.4.3: Binance algo client kimliği yalnız ASCII ve en fazla 36 karakter kabul
// eder. Parite adını kimliğe doğrudan yazmak Latin-dışı sembollerde SL/TP'yi
// reddettiriyor; korumasız kalan pozisyon da failsafe tarafından hemen kapanıyordu.
// Sembol yalnız hash girdisidir: borsaya her zaman yasal, kısa ve çakışmaya dayanıklı
// bir kimlik gider. buildAlgoCloseParams içindeki son normalizasyon çağıran bütün
// yolları (ilk koruma, yeniden yazım ve manuel SL güncelleme) birlikte korur.
function v643AlgoClientId(prefix, symbol, seed=Date.now()) {
  const p=String(prefix||'SL').toUpperCase()==='TP'?'TP':'SL';
  const raw=`${TESTNET_SESSION_RESET_ID}|${String(symbol||'').toUpperCase()}|${p}|${String(seed)}`;
  const h=crypto.createHash('sha256').update(raw,'utf8').digest('hex').slice(0,28);
  return `${p}_${h}`; // 31 ASCII karakter; Binance sınırı <=36
}
function v643NormalizeAlgoClientId(clientAlgoId, symbol, orderType) {
  const raw=String(clientAlgoId||'');
  if(/^[.A-Z:/a-z0-9_-]{1,36}$/.test(raw)) return raw;
  const prefix=String(orderType||'').toUpperCase().includes('TAKE_PROFIT')?'TP':'SL';
  return v643AlgoClientId(prefix,symbol,raw||Date.now());
}
async function buildAlgoCloseParams(symbol, closeSide, orderType, triggerPrice, clientAlgoId) {
  return {
    algoType: 'CONDITIONAL',
    symbol,
    side: closeSide,
    type: orderType,           // "STOP_MARKET" veya "TAKE_PROFIT_MARKET"
    triggerPrice: triggerPrice.toString(),
    closePosition: 'true',     // quantity/reduceOnly YOK — tüm pozisyonu kapatır
    workingType: 'MARK_PRICE',
    priceProtect: 'false',
    clientAlgoId: v643NormalizeAlgoClientId(clientAlgoId, symbol, orderType),
  };
}

async function placeAlgoSL(apiKey, apiSecret, symbol, closeSide, triggerPrice, _unused) {
  const params = await buildAlgoCloseParams(symbol, closeSide, 'STOP_MARKET', triggerPrice, v643AlgoClientId('SL',symbol));
  return bAlgo(apiKey, apiSecret, params);
}

async function placeAlgoTP(apiKey, apiSecret, symbol, closeSide, triggerPrice, _unused) {
  const params = await buildAlgoCloseParams(symbol, closeSide, 'TAKE_PROFIT_MARKET', triggerPrice, v643AlgoClientId('TP',symbol));
  return bAlgo(apiKey, apiSecret, params);
}

// ── SLTP PROOF — Lazarus verify_live_sltp_visible mantığı ────────────────────
// SL/TP yazıldıktan sonra Binance'te gerçekten görünüyor mu diye kontrol et
const bracketOrdersCache = new Map();
function bracketCacheKey(symbol) { return normalizeSymbol(symbol || '').toUpperCase(); }
function getBracketOrdersCached(symbol, ttlMs=45_000) {
  const k = bracketCacheKey(symbol);
  const c = bracketOrdersCache.get(k);
  if (c && Date.now() - Number(c.ts || 0) <= ttlMs) return Array.isArray(c.orders) ? c.orders : [];
  return null;
}
function setBracketOrdersCached(symbol, orders) {
  bracketOrdersCache.set(bracketCacheKey(symbol), { ts: Date.now(), orders: Array.isArray(orders) ? orders : [] });
}

async function liveOpenAlgoOrders(apiKey, apiSecret, symbol) {
  try {
    const rows = await bReq(apiKey, apiSecret, 'GET', '/fapi/v1/openAlgoOrders', {symbol});
    // V4.7.4.1-F03: `params` tanimsizdi -> her cagri ReferenceError firlatip catch'e dusuyor,
    // fonksiyon HER ZAMAN [] donuyordu. Sonuc: algo SL/TP emirleri hicbir zaman gorulmuyor,
    // SL/TP proof basarisiz oluyor ve pozisyon acilir acilmaz acil kapatiliyordu.
    const out = filterPositionRiskRows(Array.isArray(rows) ? rows : [], {symbol});
    try{ v592ParityStats.algoOrderReadOk++; }catch(_){}
    return out;
  } catch(e) {
    console.log(`${symbol} openAlgoOrders okunamadı: ${e.message}`);
    return [];
  }
}

async function liveOpenStandardOrders(apiKey, apiSecret, symbol) {
  try {
    const rows = await bReq(apiKey, apiSecret, 'GET', '/fapi/v1/openOrders', {symbol});
    return Array.isArray(rows) ? rows : [];
  } catch(e) {
    console.log(`${symbol} openOrders okunamadı: ${e.message}`);
    return [];
  }
}

async function liveOpenBracketOrders(apiKey, apiSecret, symbol, opts={}) {
  const ttlMs = Number(opts.ttlMs ?? 45_000);
  const force = !!opts.force;
  if (!force) {
    const cachedOrders = getBracketOrdersCached(symbol, ttlMs);
    if (cachedOrders) return cachedOrders;
    // R145: Binance 418/429 backoff aktifken açık emir sorgusu yeni 418 zinciri başlatmasın.
    // Cache yoksa boş döner; state.currentSL/targetTP zaten panel/manager için kaynak olur.
    // V4.7.4.6-G4: backoff sirasinda bos dizi donmek SL/TP proof'unu sahte basarisiz yapar.
    // Cache yoksa kisa bekleyip bir kez daha dene; yine yoksa cagirana belirsizligi bildir.
    if (isExecBackoffActive()) {
      await sleep(1500);
      const retry = getBracketOrdersCached(symbol, ttlMs*2);
      if (retry) return retry;
      if (isExecBackoffActive()) return [];
    }
  }
  const algo = await liveOpenAlgoOrders(apiKey, apiSecret, symbol);
  await sleep(120);
  const standard = await liveOpenStandardOrders(apiKey, apiSecret, symbol);
  const all = [...algo, ...standard];
  setBracketOrdersCached(symbol, all);
  return all;
}

function orderKind(o) {
  const typ = String(o.orderType || o.type || '').toUpperCase();
  const cid = String(o.clientAlgoId || o.clientOrderId || o.origClientOrderId || '').toUpperCase();
  if (typ.includes('TAKE_PROFIT') || cid.startsWith('TP_') || cid.startsWith('TPSTD_')) return 'TP';
  if (typ.includes('STOP') && !typ.includes('TAKE')) return 'SL';
  return '';
}

function orderTriggerPrice(o) {
  for (const k of ['triggerPrice','stopPrice','activatePrice','price']) {
    const v = parseFloat(o?.[k]);
    if (Number.isFinite(v) && v > 0) return v;
  }
  return 0;
}

function priceCloseEnough(expected, actual) {
  expected = parseFloat(expected); actual = parseFloat(actual);
  if (!Number.isFinite(expected) || !Number.isFinite(actual) || expected <= 0 || actual <= 0) return false;
  return Math.abs(expected - actual) / expected < 0.005; // %0.5 tolerans, tick farklarını absorbe eder
}

// ── SLTP PROOF — Lazarus verify_live_sltp_visible mantığı ────────────────────
// SL/TP yazıldıktan sonra Binance'te gerçekten görünüyor mu diye kontrol et.
// Kritik düzeltme: sadece openAlgoOrders değil, standart openOrders da kontrol edilir.
async function verifyAlgoSLTPVisible(apiKey, apiSecret, symbol, expectedSL, expectedTP) {
  try {
    const orders = await liveOpenBracketOrders(apiKey, apiSecret, symbol, {force:true, ttlMs:0});
    let foundSL = false, foundTP = false;
    const preview = [];
    for (const o of orders) {
      const kind = orderKind(o);
      const trig = orderTriggerPrice(o);
      preview.push({kind, type:o.orderType||o.type, trigger:trig, client:o.clientAlgoId||o.clientOrderId||o.origClientOrderId});
      if (kind === 'SL' && priceCloseEnough(expectedSL, trig)) foundSL = true;
      if (kind === 'TP' && priceCloseEnough(expectedTP, trig)) foundTP = true;
    }
    return { ok: foundSL && foundTP, foundSL, foundTP, orderCount: orders.length, ordersPreview: preview.slice(0,8) };
  } catch(e) {
    return { ok: false, error: e.message };
  }
}

// ── PRICE TICK NORMALIZER — SL/TP precision (-1111) koruması ────────────────
// Binance bazı coinlerde BEAT gibi 4 decimal, bazı coinlerde 5/6 decimal kabul eder.
// SL/TP kurtarma veya trailing tarafında .toFixed(8) ile ham fiyat gönderilirse
// "Precision is over the maximum defined for this asset (-1111)" hatası alınır.
const symbolFilterCache = new Map();
function decimalPlacesFromStep(step) {
  const raw = String(step || '').trim();
  if (!raw || raw === '0') return 8;
  if (raw.includes('e-')) return parseInt(raw.split('e-')[1], 10) || 8;
  const dot = raw.indexOf('.');
  if (dot < 0) return 0;
  return raw.slice(dot + 1).replace(/0+$/, '').length;
}
function roundToStepValue(value, step) {
  value = Number(value); step = Number(step);
  if (!Number.isFinite(value) || value <= 0 || !Number.isFinite(step) || step <= 0) return value;
  const dec = decimalPlacesFromStep(step);
  const rounded = Math.round(value / step) * step;
  return Number(rounded.toFixed(Math.min(12, Math.max(0, dec))));
}
function formatStepValue(value, step) {
  const dec = decimalPlacesFromStep(step);
  const n = roundToStepValue(value, step);
  return Number(n).toFixed(Math.max(0, dec));
}
async function getSymbolFilters(symbol) {
  const sym = normalizeSymbol ? normalizeSymbol(symbol) : String(symbol || '').toUpperCase();
  const cached = symbolFilterCache.get(sym);
  if (cached && Date.now() - cached.ts < 6 * 60 * 60 * 1000) return cached.val;
  let val = { tickSize: 0.00000001, stepSize: 0.001, pricePrecision: 8, qtyPrecision: 3 };
  try {
    const si = await bPub('/fapi/v1/exchangeInfo', 'symbol=' + encodeURIComponent(sym));
    const info = Array.isArray(si.symbols) ? si.symbols.find(x => x.symbol === sym) : null;
    if (info) {
      const pf = info.filters?.find(f => f.filterType === 'PRICE_FILTER');
      const lf = info.filters?.find(f => f.filterType === 'LOT_SIZE');
      if (pf && Number(pf.tickSize) > 0) val.tickSize = Number(pf.tickSize);
      if (lf && Number(lf.stepSize) > 0) val.stepSize = Number(lf.stepSize);
      if (Number.isFinite(Number(info.pricePrecision))) val.pricePrecision = Number(info.pricePrecision);
      if (Number.isFinite(Number(info.quantityPrecision))) val.qtyPrecision = Number(info.quantityPrecision);
    }
  } catch(e) {
    pushCritical('EXCHANGE_INFO_FILTER', `${sym}: ${e.message}`, {}, 'WARN');
  }
  symbolFilterCache.set(sym, { ts: Date.now(), val });
  return val;
}

// ── R88: Binance izinli kaldıraç okuma ───────────────────────────────────────
// GET /fapi/v1/leverageBracket USER_DATA cevabındaki initialLeverage alanını kullanır.
// Hata olursa emri bozmaz; panel kaldıracıyla devam edilir.
const leverageBracketCache = new Map();
async function getSymbolMaxInitialLeverage(apiKey, apiSecret, symbol, targetNotional=0) {
  const sym = normalizeSymbol(symbol);
  const key = `${keyFingerprint(apiKey)}:${sym}:${Math.round(Number(targetNotional||0)/50)*50}`;
  const now = Date.now();
  const cached = leverageBracketCache.get(key);
  if (cached && now - cached.ts < 10 * 60 * 1000) return cached.value;
  try {
    const raw = await bReq(apiKey, apiSecret, 'GET', '/fapi/v1/leverageBracket', { symbol:sym }, 10000);
    const row = Array.isArray(raw) ? (raw.find(x => String(x.symbol).toUpperCase() === sym) || raw[0]) : raw;
    const brackets = Array.isArray(row?.brackets) ? row.brackets : [];
    let best = 0;
    const want = Math.max(0, Number(targetNotional || 0));
    for (const b of brackets) {
      const lev = Number(b.initialLeverage || b.initialLeverageCap || b.maxLeverage || 0);
      const cap = Number(b.notionalCap || b.qtyCap || Infinity);
      const floor = Number(b.notionalFloor || 0);
      if (!Number.isFinite(lev) || lev <= 0) continue;
      if (want > 0 && Number.isFinite(cap) && (want < floor || want > cap)) continue;
      best = Math.max(best, lev);
    }
    if (!best && brackets.length) best = Math.max(...brackets.map(b=>Number(b.initialLeverage||0)).filter(n=>n>0));
    const value = Number.isFinite(best) && best > 0 ? Math.floor(best) : null;
    leverageBracketCache.set(key, {ts:now, value});
    return value;
  } catch(e) {
    return null;
  }
}

// ── R137: Binance sembol kaldıraç sınırı / -4028 fallback ───────────────────
function normalizeRequestedLeverage(v, fallback=1) {
  const n = Math.floor(Number(v || fallback));
  return Math.max(R486_MIN_LEVERAGE, Math.min(125, Number.isFinite(n) ? n : Math.max(R486_MIN_LEVERAGE, fallback)));
}

async function setSymbolLeverageSafe(apiKey, apiSecret, symbol, requestedLeverage, targetNotional=0) {
  const sym = normalizeSymbol(symbol);
  const requested = normalizeRequestedLeverage(requestedLeverage, 1);
  const maxLev = await getSymbolMaxInitialLeverage(apiKey, apiSecret, sym, targetNotional).catch(()=>null);
  if (maxLev && Number(maxLev) < R486_MIN_LEVERAGE) {
    const e = new Error(`${sym}: Binance izinli maksimum ${maxLev}x; R486 minimum ${R486_MIN_LEVERAGE}x altında — işlem açılmadı`);
    e.code = 'R486_MIN_LEVERAGE_UNAVAILABLE';
    throw e;
  }
  const first = maxLev ? Math.min(requested, normalizeRequestedLeverage(maxLev, requested)) : requested;
  const ladder = [125,100,75,50,40,30,25,20,15,12,10];
  const candidates = [];
  const add = (x) => {
    const n = normalizeRequestedLeverage(x, 1);
    if (maxLev && n > maxLev) return;
    if (n > requested && !maxLev) return;
    if (!candidates.includes(n)) candidates.push(n);
  };
  add(first);
  for (const x of ladder) add(Math.min(x, first));

  let lastErr = null;
  for (const lev of candidates) {
    try {
      await bReq(apiKey, apiSecret, 'POST', '/fapi/v1/leverage', {symbol:sym, leverage:lev});
      return {
        ok:true,
        leverage:lev,
        requested,
        maxLeverage:maxLev || null,
        adjusted:lev !== requested,
        reason: lev !== requested
          ? `Binance ${sym} için ${requested}x kabul etmedi/izin vermedi; ${lev}x ile devam edildi${maxLev ? ` (izinli max ${maxLev}x)` : ''}`
          : ''
      };
    } catch(e) {
      lastErr = e;
      const msg = String(e?.message || '');
      if (!(msg.includes('-4028') || msg.toLowerCase().includes('leverage') || msg.toLowerCase().includes('not valid'))) {
        throw e;
      }
    }
  }
  throw lastErr || new Error(`${sym}: kaldıraç ayarlanamadı`);
}

async function normalizeSLTPToTick(symbol, slPrice, tpPrice) {
  const filters = await getSymbolFilters(symbol);
  const tickSize = Number(filters.tickSize) || 0.00000001;
  const sl = formatStepValue(slPrice, tickSize);
  const tp = formatStepValue(tpPrice, tickSize);
  return { sl, tp, slNum: Number(sl), tpNum: Number(tp), tickSize };
}

// R24: kapanmış pozisyona SL/TP rescue yazma koruması.
function isNoOpenPositionAlgoError(e) {
  const msg = String(e && (e.message || e) || '');
  return msg.includes('-4509') ||
    msg.includes('GTE can only be used with open positions') ||
    msg.includes('Please ensure that positions are available');
}
// V4.7.4.10-K2: maxAgeMs parametresi. Varsayilan yonetici butcesi (8sn).
// Emir-kritik cagrilar POS_FRESH_ORDER_MS (3sn) verir.
// ══ V4.7.4.24-AN2: YETIM KORUMA TEMIZLIGI ARTIK KORUMAYI SILMIYOR ═══════
// 07.08 HEIUSDT vakasi: MARKET emri ACK aldi (exchangeStatus NEW), fill
// SADECE TAHMIN edildi (fillConfirmed:false, executedQty:null,
// fillSource:MARK_PRICE_ESTIMATE). SL/TP yazildi ve borsada goruldu.
// 1,7 sn sonra freshOpenPositionForSymbol "pozisyon yok" dedi -> koruma
// IPTAL edildi -> POSITION_ALREADY_CLOSED -> defterde KAPANDI yazildi.
// Gercekte pozisyon ACIKTI ve KORUMASIZ kaldi (Binance TP/SL: -- / --).
// Kok neden: positionRisk 15-20 sn gecikiyor (POSITION_RISK_SLOW_INFLIGHT);
// yeni dolan pozisyon 1,7 sn sonra henuz gorunmuyor.
// Kural: SUPHEDE KORUMAYI BIRAK. Yanlis koruma birakmak zararsizdir;
// yanlis koruma silmek korumasiz canli pozisyon demektir.
const v592PossibleOrphans = new Set();
async function freshOpenPositionForSymbol(apiKey, apiSecret, symbol, attempts=3, maxAgeMs=POS_FRESH_MANAGER_MS) {
  const sym = String(symbol||'').toUpperCase();
  for (let i=0; i<attempts; i++) {
    try {
      // V4.7.4.6-G1: GERCEK force-fresh. Eskiden TTL cache'ten bayat cevap geliyordu.
      const rows = await getPositionRiskCached(apiKey, apiSecret, {symbol:sym, __forceFresh:true, __maxAgeMs:maxAgeMs});
      const p = Array.isArray(rows) ? rows.find(x=>String(x.symbol||'').toUpperCase()===sym) : null;
      if (p && Math.abs(parseFloat(p.positionAmt || 0)) > 0) return { open:true, pos:p };
    } catch(e) {
      // API geçici patladıysa SL/TP yazmayı tamamen kesme; sadece fresh kontrol başarısız say.
      if (i === attempts-1) return { open:null, error:e };
    }
    if (i < attempts-1) await new Promise(r=>setTimeout(r, i===0 ? 450 : 850));
  }
  return { open:false, pos:null };
}
// V4.7.4.22-AJ2: kapanis POZITIF KANITLA dogrulanir.
// Taze account snapshot BASARILI olmali; aksi halde kapanis kaydi yazilmaz.
async function v592CloseProof(symbol){
  const S=String(symbol||'').toUpperCase();
  try{
    const rows=await getPositionRiskCached(autoConfig?.apiKey,autoConfig?.apiSecret,
      {symbol:S,__forceFresh:true,__maxAgeMs:10000});
    const arr=Array.isArray(rows)?rows:[];
    const acik=arr.some(x=>Math.abs(parseFloat(x.positionAmt||0))>0);
    const age=posRiskCache?.lastSuccessAt?Date.now()-Number(posRiskCache.lastSuccessAt):Infinity;
    if(!Number.isFinite(age)||age>15000) return {proven:false,reason:'SNAPSHOT_STALE',ageMs:age};
    if(acik) return {proven:false,reason:'STILL_OPEN'};
    return {proven:true,reason:'FRESH_FLAT',ageMs:age};
  }catch(e){ return {proven:false,reason:'SNAPSHOT_FAILED',error:String(e?.message||e).slice(0,100)}; }
}
async function cleanupClosedPositionState(symbol, reason='POSITION_ALREADY_CLOSED', state={}) {
  // V4.7.4.24-AN1: AJ2'de kanit yalnizca SYNC_* ve POSITION_ALREADY_CLOSED icin
  // isteniyordu. 07.08 HEIUSDT 'POSITION_GONE_AFTER_PROTECT' sebebiyle geldi ve
  // kanit kapisini KOMPLE ATLADI -> acik pozisyon "kapandi" diye kaydedildi.
  // Bu, AC dersinin tekrari: guard bir cagri yoluna baglanip digeri unutulmus.
  // Artik beyaz liste YOK: kanit VARSAYILAN, muafiyet acik yazilir.
  const V592_CLOSE_PROOF_EXEMPT = ['EXCHANGE_CONFIRMED_FILL','MANUAL_OPERATOR_FORCE'];
  if(!V592_CLOSE_PROOF_EXEMPT.includes(String(reason||''))){
    v592ParityStats.closeProofRequired++;
    v592ParityStats.closeProofRequiredAll++;
    const _cp=await v592CloseProof(symbol);
    if(!_cp.proven){
      v592ParityStats.closeProofFailed++;
      try{r501OrderLifeMark(symbol,'CLOSE_ABORTED_NO_PROOF',{reason,proof:_cp});}catch(_){}
      try{logAuto(`[${symbol}] KAPANIS IPTAL — kanit yok (${_cp.reason}); pozisyon ACIK sayiliyor`);}catch(_){}
      return {aborted:true,proof:_cp};
    }
  }
  const sym = String(symbol||'').toUpperCase();
  const st = state || (typeof trailingState !== 'undefined' ? trailingState.get(sym) : null) || (lastKnownPositions && lastKnownPositions[sym]) || {};
  try { trailingState.delete(sym); } catch(_) {}
  try { invalidatePositionRiskCache(reason); } catch(_) {}
  try {
    // R377 (EDGE dersi 08.07 10:45: bot koruma SL'i Binance'te doldu ama panel "Kullanıcı kapattı" yazdı —
    // kullanıcı kapatmamıştı). Kör damga yerine önce zengin sınıflandırıcıya sor (income+fiyat+emir bilgisi).
    let cls = null;
    try {
      if (typeof classifyClosedPosition === 'function' && autoConfig?.apiKey && autoConfig?.apiSecret) {
        cls = await classifyClosedPosition(autoConfig.apiKey, autoConfig.apiSecret, sym, st);
      }
    } catch(_) { cls = null; }
    if (!cls) cls = { code:'UNATTRIBUTED_EXCHANGE_CLOSE', label:'Kaynağı doğrulanamayan Binance/API kapanışı', emoji:'👁️', closePrice:null, realizedPnl:null, side:st?.side };
    const cdMs = setCloseCooldown(sym, cls, st);
    cls.cooldownMs = cdMs;
    try { recordTradeClose(sym, st, cls); } catch(_) {}
    try { forgetKnownPosition(sym); saveLastKnownPositions(); } catch(_) {}
    logAuto(`👁️ ${sym.replace('USDT','')} pozisyon zaten kapalı göründü; koruma emri yazılmadı. Aynı yön ${Math.ceil(cdMs/60000)}dk beklemede, temiz ters yön açık.`);
  } catch(e) {
    try { setCooldown(sym, CD_MANUAL_MS, 'Pozisyon kapalı algılandı; aynı yön bekleme'); } catch(_) {}
    try { logAuto(`⚠️ ${sym.replace('USDT','')} pozisyon kapanmış — koruma emri atlandı (${reason})`); } catch(_) {}
  }
}

// ── SL/TP ÇİFTİ YAZ + İSPAT AL — install_live_sltp_pair_with_proof ──────────
// Lazarus'un en önemli pattern'i: yaz, 250ms bekle, Binance'te gözle
// V4.7.4.13-Q: KORUMA ONCE, DOGRULAMA SONRA.
// 05.08 TUT vakasi: ENTRY_FILL_OBSERVED 13:33:10.378 -> PROTECTION_FAILED 13:33:37.054.
// Arada 26,6 saniye TEK BIR SL/TP EMRI YAZILMADI. Sebep: yazmadan once iki imzali cagri:
//   1) verifyAlgoSLTPVisible  (J1'de eklendi)  -> /fapi/v1/openOrders
//   2) freshOpenPositionForSymbol x3           -> /fapi/v2/account, her deneme 14sn'e kadar bekler
// Testnet imzali cagri 19-26sn suruyordu; pozisyon o pencerede korumasiz kapandi.
// firstInstall=true (emir yolu): MAIN_ORDER_ACK + ENTRY_FILL_OBSERVED zaten pozisyon kanitidir.
// Once SL/TP yazilir, dogrulama SONRA yapilir. Yonetici yolu (firstInstall=false) degismez.
async function installSLTPWithProof(apiKey, apiSecret, symbol, closeSide, slPrice, tpPrice, sym, opts={}) {
  const firstInstall = !!(opts && opts.firstInstall);
  // Çalışan Python çekirdeği kuralı:
  // cancel-first → SL+TP çiftini ALGO endpoint'e yaz → Binance'te görünür proof al → proof yoksa başarılı sayma.
  // R11: Her SL/TP çağrısı burada tek merkezden tickSize'a yuvarlanır.
  // R13 kritik düzeltme: STOP_MARKET / TAKE_PROFIT_MARKET için /fapi/v1/order fallback'i KALDIRILDI.
  // Binance yeni sembollerde -4120 ile açıkça "Algo Order API kullan" diyor; bu yüzden standart endpoint'e düşmek
  // sahte kritik hata üretir ve bazı hesaplarda koruma yazımını gereksiz bozabilir.
  // V4.7.4.9-J1: KOK NEDEN. installSLTPWithProof ilk is olarak cancelAlgoOrders cagirir.
  // 05.08 CYS/1000RATS: calisan SL+TP iptal edildi, yeniden koyma kismen basarisiz oldu,
  // SL kayboldu ve pozisyon 18-43 saniyede korumasiz sekilde disaridan kapandi.
  // Artik once BORSADA gecerli SL+TP var mi diye bakilir; varsa hicbir sey iptal edilmez.
  // V4.7.4.13-Q2: J1 on-kontrolu YALNIZ yonetici yolunda. Yeni acilan pozisyonda
  // borsada zaten koruma OLAMAZ; o cagri saf gecikmeydi ve pozisyonu oldurdu.
  if(V592_PROTECT_KEEP_EXISTING && !firstInstall){
    try{
      const _pre=await verifyAlgoSLTPVisible(apiKey,apiSecret,symbol,slPrice,tpPrice);
      if(_pre&&_pre.ok){
        v592ParityStats.protectionKeptExisting++;
        try{r501OrderLifeMark(symbol,'PROTECTION_KEPT_EXISTING',{foundSL:_pre.foundSL,foundTP:_pre.foundTP,orderCount:_pre.orderCount});}catch(_){}
        console.log(`${symbol} J1: Binance'te gecerli SL+TP zaten var; iptal/yeniden kurma YAPILMADI.`);
        return {ok:true,proof:_pre,slPrice,tpPrice,keptExisting:true,endpoint:'algoOrder'};
      }
    }catch(_){}
  }
  // V4.7.4.13-Q3: ilk kurulumda pozisyon on-dogrulamasi YAPILMAZ.
  // ACK + FILL kanittir; dogrulama SL/TP yazildiktan sonra Q5'te yapilir.
  let freshStart = firstInstall
    ? { open:null, pos:null, skippedPreCheck:true }
    : await freshOpenPositionForSymbol(apiKey, apiSecret, symbol, 3, POS_FRESH_ORDER_MS);
  if (firstInstall) {
    v592ParityStats.protectFirstInstalls++;
    try{r501OrderLifeMark(symbol,'PROTECT_FIRST_NO_PRECHECK',{note:'ACK+FILL kaniti yeterli; SL/TP derhal yaziliyor'});}catch(_){}
  }
  if (freshStart.open === false) {
    // V4.7.4.6-G2: tek positionRisk okumasi 'pozisyon kapandi' demeye YETMEZ.
    // 05.08 olayi: emir doldu, positionRisk 3.8sn bayatti, kod pozisyonu goremedi,
    // SL/TP yazilmadi ve pozisyon 7 dakika KORUMASIZ kaldi.
    let _proofOpen=false, _via='NONE';
    try{
      const _rows=await fetchPositionRiskRaw(apiKey,apiSecret);
      const _p=Array.isArray(_rows)?_rows.find(x=>String(x.symbol||'').toUpperCase()===String(symbol).toUpperCase()):null;
      if(_p&&Math.abs(Number(_p.positionAmt||0))>0){_proofOpen=true;_via='POSITION_TRUTH';freshStart={open:true,pos:_p};}
    }catch(_){}
    if(!_proofOpen){
      try{
        const _tr=await bReq(apiKey,apiSecret,'GET','/fapi/v1/userTrades',{symbol:String(symbol).toUpperCase(),limit:10},8000);
        if(Array.isArray(_tr)&&_tr.length){
          let net=0; for(const x of _tr){const q=Number(x.qty||0); net += (x.buyer? q : -q);}
          if(Math.abs(net)>0){_proofOpen=true;_via='USER_TRADES_NET';}
        }
      }catch(_){}
    }
    try{r501OrderLifeMark(symbol,'POST_FILL_POSITION_PROOF',{proofOpen:_proofOpen,via:_via,firstCheck:'ZERO'});}catch(_){}
    if(!_proofOpen){
      await cleanupClosedPositionState(symbol, 'FRESH_POSITION_ZERO_BEFORE_SLTP');
      return { ok:false, skipped:true, skippedClosed:true, error:'POSITION_ALREADY_CLOSED', endpoint:'algoOrder', proofVia:_via };
    }
    try{v592ParityStats.postFillProofRescues++;}catch(_){}
    console.log(`${symbol} G2: ilk positionRisk sifir dedi ama ${_via} pozisyonu dogruladi; SL/TP yazimi devam ediyor.`);
  }
  if (freshStart.open === null) {
    console.log(`${symbol} fresh positionRisk kontrolü yapılamadı; SL/TP yazımı deneniyor: ${freshStart.error?.message || freshStart.error}`);
  }

  const normalized = await normalizeSLTPToTick(symbol, slPrice, tpPrice);
  slPrice = normalized.sl;
  tpPrice = normalized.tp;

  // ── R279c -2021 FIX: İLK açılışta da mark-bazlı güvenlik mesafesi clamp'i ──────
  // CHIP -2021 "Order would immediately trigger" dersi: R277 clamp'i sadece SL/TP
  // GÜNCELLEMESİNDE vardı, ilk açılışta YOKtu. Mikro-fiyatlı/oynak coinde ilk SL veya TP
  // mark'a çok yakın hesaplanınca Binance reddediyor → bot panik kapatıyor → küçük kâr/erken çıkış.
  // Burada SADECE emir trigger fiyatını mark'tan min mesafede tutuyoruz; karar/skor/OTE'ye dokunmaz.
  try {
    // Mark fiyatı: freshStart'tan gelen pozisyon objesinde zaten var (yeni Binance isteği YOK).
    // freshStart.pos.markPrice yoksa, ticker/price ile çek (fallback).
    let _mark = positionMarkPrice(freshStart && freshStart.pos ? freshStart.pos : {}) || 0;
    if (!(_mark > 0)) {
      try { const _pr = await bPub('/fapi/v1/ticker/price', 'symbol=' + symbol); _mark = Number(_pr && _pr.price) || 0; } catch(_) {}
    }
    if (_mark > 0) {
      const _tick = Number((normalized && normalized.tickSize) || 0) || 0;
      const _minGap = Math.max(_tick > 0 ? _tick * 3 : 0, _mark * 0.0004); // R277 ile aynı: max(3 tick, %0.04)
      const _isLong = String(closeSide).toUpperCase() === 'SELL'; // long pozisyonun kapanış emri SELL
      const _sl = Number(slPrice), _tp = Number(tpPrice);
      if (_isLong) {
        // LONG: SL mark'ın ALTINDA, TP mark'ın ÜSTÜNDE olmalı, min mesafe korunur
        if (_sl > 0 && _sl > _mark - _minGap) slPrice = (_mark - _minGap);
        if (_tp > 0 && _tp < _mark + _minGap) tpPrice = (_mark + _minGap);
      } else {
        // SHORT: SL mark'ın ÜSTÜNDE, TP mark'ın ALTINDA olmalı
        if (_sl > 0 && _sl < _mark + _minGap) slPrice = (_mark + _minGap);
        if (_tp > 0 && _tp > _mark - _minGap) tpPrice = (_mark - _minGap);
      }
      // clamp sonrası tekrar tick'e yuvarla (Binance tam tick ister)
      const _renorm = await normalizeSLTPToTick(symbol, slPrice, tpPrice);
      slPrice = _renorm.sl; tpPrice = _renorm.tp;
    }
  } catch(_) { /* mark çekilemezse normalize edilmiş değerlerle devam (fail-safe) */ }

  let lastErr = null;
  let lastProof = null;

  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      // V4.7.4.18-AA1: 06.08 ACT olcumu -> fillToProtectionMs = 192.789 ms (3dk 13sn).
      // POSITION_RISK_SLOW_INFLIGHT 20-60sn; governor=0sn, yani cagrinin KENDISI yavas.
      // Koruma yolu 5 imzali cagri yapiyordu: cancel + SL + TP + 2x proof.
      // (a) YENI acilan pozisyonda iptal edilecek algo emri OLAMAZ -> ilk denemede cancel ATLANIR.
      // (b) SL ve TP birbirinden bagimsiz -> SIRAYLA degil PARALEL yazilir.
      // Boylece 5 yavas cagri -> 3'e iner (ilk denemede).
      // V4.7.4.24-AN2: daha once yetim suphesi birakilmis sembolde iptali ATLAMA;
      // eski koruma emirleri yeni pozisyona yanlis fiyatla yapismasin.
      const _orphanSuspect = (()=>{ try{ return v592PossibleOrphans.has(String(symbol||'').toUpperCase()); }catch(_){ return false; } })();
      const _skipCancel = (firstInstall && attempt === 1 && !_orphanSuspect);
      if (_skipCancel) {
        v592ParityStats.cancelSkippedFirstInstall++;
        try{r501OrderLifeMark(symbol,'CANCEL_SKIPPED_FIRST_INSTALL',{note:'sembol emirden once flat kanitiyla orphan algo temizliginden gecti; koruma gecikmesin diye post-fill cancel atlandi'});}catch(_){}
      } else {
        await cancelAlgoOrders(apiKey, apiSecret, symbol);
      }

      v592ParityStats.protectParallelWrites++;
      const [slOrder, tpOrder] = await Promise.all([
        placeAlgoSL(apiKey, apiSecret, symbol, closeSide, slPrice, null),
        placeAlgoTP(apiKey, apiSecret, symbol, closeSide, tpPrice, null),
      ]);

      // Binance algo emirleri açık emir listesine bazen 300ms'den geç düşüyor.
      // Önce kısa, sonra biraz daha uzun proof kontrolü yap; proof gecikmesini hata sanma.
      for (const waitMs of [450, 900]) {
        await new Promise(r => setTimeout(r, waitMs));
        const proof = await verifyAlgoSLTPVisible(apiKey, apiSecret, symbol, normalized.slNum, normalized.tpNum);
        lastProof = proof;
        if (proof.ok) {
          try{ v592PossibleOrphans.delete(String(symbol||'').toUpperCase()); }catch(_){}
          // V4.7.4.13-Q4: koruma YAZILDI ve borsada GORULDU. Pozisyon dogrulamasi ARTIK burada,
          // yani koruma zaten yerdeyken yapilir. Pozisyon yoksa yetim koruma temizlenir.
          if (firstInstall) {
            try {
              const _post = await freshOpenPositionForSymbol(apiKey, apiSecret, symbol, 1, POS_FRESH_MANAGER_MS);
              if (_post && _post.open === false) {
                // V4.7.4.24-AN2: ARTIK IPTAL YOK. Bu okuma dolumdan saniyeler sonra
                // yapiliyor ve positionRisk 15-20 sn gecikebiliyor -> "yok" yanlis olabilir.
                // Koruma YERINDE BIRAKILIR; sembol supheli yetim listesine yazilir.
                // Sonraki girisde ilk-kurulum iptal atlamasi devre disi kalir ve
                // varsa gercek yetim emirler orada temizlenir.
                v592ParityStats.orphanCheckDeferred++;
                v592ParityStats.orphanCancelSuppressed++;
                try{ v592PossibleOrphans.add(String(symbol||'').toUpperCase()); }catch(_){}
                try{r501OrderLifeMark(symbol,'ORPHAN_CHECK_DEFERRED',{note:'pozisyon okumasi bos dondu ama dolum tahminiydi; KORUMA BIRAKILDI',postRead:_post?.open??null});}catch(_){}
                try{logAuto(`[${symbol}] yetim kontrolu ertelendi — koruma silinmedi (positionRisk gecikmesi olabilir)`);}catch(_){}
              }
              if (_post && _post.open === null) v592ParityStats.postWriteProofFail++;
            } catch(_) { v592ParityStats.postWriteProofFail++; }
          }
          return {
            ok: true, slOrder, tpOrder, proof,
            slPrice: normalized.slNum, tpPrice: normalized.tpNum, tickSize: normalized.tickSize,
            endpoint: 'algoOrder', attempt, protectFirst: firstInstall
          };
        }
      }

      lastErr = new Error(`Algo SL/TP proof başarısız (deneme ${attempt}); SL:${lastProof?.foundSL || false} TP:${lastProof?.foundTP || false} emir:${lastProof?.orderCount || 0}`);
    } catch(e) {
      lastErr = e;
      if (isNoOpenPositionAlgoError(e)) {
        await cleanupClosedPositionState(symbol, 'ALGO_-4509_POSITION_ALREADY_CLOSED');
        return { ok:false, skipped:true, skippedClosed:true, error:'POSITION_ALREADY_CLOSED', endpoint:'algoOrder' };
      }
      // İlk denemede geçici API/propagation olabilir; ikinci denemeye izin ver.
      if (attempt === 1) await new Promise(r => setTimeout(r, 700));
    }
  }

  const msg = lastErr?.message || 'Algo SL/TP proof başarısız';
  if (isNoOpenPositionAlgoError(lastErr)) {
    await cleanupClosedPositionState(symbol, 'ALGO_-4509_POSITION_ALREADY_CLOSED');
    return { ok:false, skipped:true, skippedClosed:true, error:'POSITION_ALREADY_CLOSED', endpoint:'algoOrder' };
  }
  pushCritical('SLTP_ALGO_PROOF_FAIL', `${symbol}: ${msg}`, {
    tickSize: normalized?.tickSize, slPrice, tpPrice, proof: lastProof, endpoint: 'algoOrder'
  });
  return {
    ok: false, error: msg, proof: lastProof,
    slPrice: normalized?.slNum, tpPrice: normalized?.tpNum, tickSize: normalized?.tickSize,
    endpoint: 'algoOrder'
  };
}

// ═══ V610 ═══ MUM RITMINE KILITLI PUBLIC ONBELLEK ("nehir")
// Kapali mum verisi bir sonraki mum kapanana kadar degismez; o yuzden TTL'i
// sabit saniye degil, BIR SONRAKI MUM KAPANISI belirler. Alt zaman dilimleri
// hizli, ust zaman dilimleri yavas tazelenir. Emir defteri hic onbellege alinmaz.
const _v610Cache = new Map();      // key -> {t, exp, val}
const _v610Inflight = new Map();   // key -> Promise   (ayni istek iki kez ucmaz)
const _v610IvMs = {'1m':60000,'3m':180000,'5m':300000,'15m':900000,'30m':1800000,'1h':3600000,'2h':7200000,'4h':14400000,'6h':21600000,'12h':43200000,'1d':86400000};
const _v610IvCap = {'1m':30000,'3m':60000,'5m':90000,'15m':240000,'30m':480000,'1h':900000,'2h':1200000,'4h':1800000,'6h':2400000,'12h':3000000,'1d':3600000};
function _v610Ttl(path, qs){
  const p = String(path||''), q = String(qs||'');
  if (/\/depth/i.test(p)) return 0;                                  // emir defteri: ASLA
  if (/\/ticker\/24hr/i.test(p)) return 20000;                        // tum piyasa dokumu
  if (/\/openInterest$|\/premiumIndex/i.test(p)) return 15000;
  if (/futures\/data/i.test(p)) return 60000;
  if (/\/klines/i.test(p)) {
    const m = /interval=([0-9a-zA-Z]+)/.exec(q);
    const iv = m ? m[1] : '';
    const ms = _v610IvMs[iv]; const cap = _v610IvCap[iv];
    if (!ms || !cap) return 0;
    const now = Date.now();
    const nextClose = Math.ceil(now/ms)*ms;                            // bir sonraki mum kapanisi
    return Math.max(3000, Math.min(cap, (nextClose - now) + 2000));    // +2sn Binance yayin payi
  }
  return 0;
}
// ═══ V612 ═══ "NEHIR" — WEBSOCKET MUM AKISI
// Mum verisi Binance'te WS uzerinden AGIRLIKSIZ akar. Kodda aggTrade/depth/forceOrder
// akislari zaten vardi; mum akisi hic yoktu ve tum mumlar REST'ten cekiliyordu
// (analiz basina 29 agirlik, TOP24 taramasinda ~700 agirlik yalniz mumlar icin).
// Depo ILK REST cevabindan tohumlanir (ekstra istek YOK), sonra WS ile akar.
const V612_NEHIR        = String(process.env.V612_NEHIR ?? '1') !== '0';
const V612_NEHIR_MAX    = Math.max(20,  Math.min(900,  Number(process.env.V612_NEHIR_MAX_AKIS || 240)));
const V612_NEHIR_SHARD  = Math.max(10,  Math.min(200,  Number(process.env.V612_NEHIR_SHARD    || 60)));
const V612_NEHIR_BOSTA_DK = Math.max(3, Math.min(120,  Number(process.env.V612_NEHIR_BOSTA_DK || 25)));
const V612_DENETIM_DK   = Math.max(2,   Math.min(240,  Number(process.env.V612_DENETIM_DK     || 10)));
const V612_MUM_TUT      = 260;   // depoda tutulan azami kapali mum sayisi
const _v612IvMs = {'1m':60000,'3m':180000,'5m':300000,'15m':900000,'30m':1800000,'1h':3600000,'2h':7200000,'4h':14400000,'6h':21600000,'8h':28800000,'12h':43200000,'1d':86400000};
const _v612Store = new Map();    // "BTCUSDT|15m" -> kayit
const _v612Baglantilar = [];     // {ws, akislar:Set, kapaliMi}
let   _v612SonKurulum = 0, _v612SonDenetim = 0, _v612Kuruluyor = false;
const _v612Sayac = {wsOlay:0, wsDusme:0, depodan:0, restten:0, uyusmazlik:0, kapatilan:0, tohum:0};

function _v612Kayit(sym, iv){
  const key = sym + '|' + iv;
  let rec = _v612Store.get(key);
  if (!rec) {
    rec = {symbol:sym, interval:iv, ivMs:_v612IvMs[iv]||0, rows:[], forming:null,
           restFormingVar:null, seededAt:0, lastWsAt:0, lastReqAt:0, bosluk:false,
           kapali:false, kapatmaSebebi:null, wsOlay:0, depodan:0, restten:0,
           denetimSira:false, denetimBekleyen:null};
    _v612Store.set(key, rec);
  }
  return rec;
}

// path+qs -> {symbol, interval, limit} | null   (startTime/endTime iceren istekler HARIC)
function _v612Coz(path, qs){
  if (!V612_NEHIR) return null;
  const p = String(path||'');
  if (!p.includes('/klines')) return null;
  const q = String(qs||'');
  if (/startTime=|endTime=|fromId=/i.test(q)) return null;          // tam tarihli istek -> daima REST
  const ms = /(?:^|&)symbol=([A-Za-z0-9]+)/.exec(q);
  const mi = /(?:^|&)interval=([0-9a-zA-Z]+)/.exec(q);
  if (!ms || !mi) return null;
  const iv = mi[1];
  if (!_v612IvMs[iv]) return null;
  const ml = /(?:^|&)limit=(\d+)/.exec(q);
  const limit = ml ? Math.max(1, Number(ml[1])) : 500;
  if (limit > V612_MUM_TUT) return null;                            // depo bu kadar tutmuyor
  return {symbol: String(ms[1]).toUpperCase(), interval: iv, limit};
}

function _v612Satir(k){
  return [Number(k.t), String(k.o), String(k.h), String(k.l), String(k.c), String(k.v),
          Number(k.T), String(k.q), Number(k.n), String(k.V), String(k.Q), String(k.B ?? '0')];
}

function _v612WsOlay(d){
  try{
    const k = d && d.k; if (!k || !k.i) return;
    const sym = String(d.s || k.s || '').toUpperCase(); if (!sym) return;
    const rec = _v612Store.get(sym + '|' + k.i); if (!rec || rec.kapali) return;
    const row = _v612Satir(k);
    if (!Number.isFinite(row[0]) || !(row[0] > 0)) return;
    rec.lastWsAt = Date.now(); rec.wsOlay++; _v612Sayac.wsOlay++;
    if (k.x === true) {
      const son = rec.rows[rec.rows.length-1];
      if (son && Number(son[0]) === row[0]) { rec.rows[rec.rows.length-1] = row; }
      else if (!son || row[0] > Number(son[0])) {
        if (son && row[0] !== Number(son[0]) + rec.ivMs) rec.bosluk = true;   // atlanan mum -> REST'e dus
        rec.rows.push(row);
        if (rec.rows.length > V612_MUM_TUT) rec.rows.splice(0, rec.rows.length - V612_MUM_TUT);
      }
      if (rec.forming && Number(rec.forming[0]) <= row[0]) rec.forming = null;
    } else {
      rec.forming = row;
    }
  }catch(_){}
}

// Depodan cevap. SARTLARIN HEPSI saglanmazsa null -> cagri REST'e duser.
function _v612Sun(sym, iv, limit){
  if (!V612_NEHIR) return null;
  const rec = _v612Store.get(sym + '|' + iv);
  if (!rec || rec.kapali || rec.bosluk || !rec.seededAt || !rec.ivMs) return null;
  if (rec.denetimSira) return null;                                  // mutabakat turu: zorla REST
  const now = Date.now();
  const bayatSinir = Math.max(20000, Math.min(rec.ivMs, 120000));
  if (!rec.lastWsAt || (now - rec.lastWsAt) > bayatSinir) return null;   // akis bayat
  const barBasi   = Math.floor(now / rec.ivMs) * rec.ivMs;
  const sonKapali = barBasi - rec.ivMs;
  const son = rec.rows[rec.rows.length-1];
  if (!son || Number(son[0]) !== sonKapali) return null;              // geride kalmis
  const n = Math.min(rec.rows.length, 12);
  for (let i = rec.rows.length - n + 1; i < rec.rows.length; i++) {
    if (Number(rec.rows[i][0]) !== Number(rec.rows[i-1][0]) + rec.ivMs) return null;  // bosluk
  }
  if (rec.restFormingVar === true) {
    const f = (rec.forming && Number(rec.forming[0]) === barBasi) ? rec.forming : null;
    if (!f) return null;
    if (rec.rows.length < (limit - 1)) return null;
    const out = rec.rows.slice(-(limit-1)).map(r=>r.slice()); out.push(f.slice());
    return out;
  }
  if (rec.restFormingVar === false) {
    if (rec.rows.length < limit) return null;
    return rec.rows.slice(-limit).map(r=>r.slice());
  }
  return null;                                                        // sozlesme henuz gozlemlenmedi
}

// REST cevabindan tohumla + (denetim turuysa) mutabakat yap.
function _v612Tohumla(sym, iv, rows){
  try{
    if (!V612_NEHIR || !Array.isArray(rows) || rows.length < 3) return;
    const ivMs = _v612IvMs[iv]; if (!ivMs) return;
    const rec = _v612Kayit(sym, iv); if (rec.kapali) return;
    const now = Date.now();
    const son = rows[rows.length-1];
    if (!Array.isArray(son) || !Number.isFinite(Number(son[0]))) return;
    // GOZLEM: REST olusan (kapanmamis) mumu da donduruyor mu?
    const olusanVar = Number(son[6]) > now;
    const kapaliDizi = olusanVar ? rows.slice(0,-1) : rows.slice();
    if (kapaliDizi.length < 2) return;
    // tazelik: eski onbellekten gelen cevapla depoyu geri sarma
    const sonKapaliBeklenen = Math.floor(now/ivMs)*ivMs - ivMs;
    const sonKapaliGelen = Number(kapaliDizi[kapaliDizi.length-1][0]);
    if (!(sonKapaliGelen >= sonKapaliBeklenen - ivMs)) return;

    // ── MUTABAKAT ──
    if (rec.denetimSira) {
      rec.denetimSira = false;
      const bekl = rec.denetimBekleyen; rec.denetimBekleyen = null;
      if (Array.isArray(bekl) && bekl.length >= 3) {
        const a = bekl.slice(-3), b = kapaliDizi.slice(-3);
        let ayni = a.length === b.length;
        if (ayni) for (let i=0;i<a.length;i++){
          if (Number(a[i][0])!==Number(b[i][0]) || String(a[i][1])!==String(b[i][1]) ||
              String(a[i][2])!==String(b[i][2]) || String(a[i][3])!==String(b[i][3]) ||
              String(a[i][4])!==String(b[i][4])) { ayni = false; break; }
        }
        if (!ayni) {
          rec.kapali = true; rec.kapatmaSebebi = 'MUTABAKAT_UYUSMAZLIGI';
          _v612Sayac.uyusmazlik++; _v612Sayac.kapatilan++;
          try{ logAuto(`\u26a0\ufe0f [V612] ${sym} ${iv} NEHIR KAPATILDI \u2014 REST ile mutabakat tutmadi, bu anahtar REST'e dondu`); }catch(_){}
          return;
        }
      }
    }

    rec.ivMs = ivMs;
    rec.restFormingVar = olusanVar;
    rec.rows = kapaliDizi.slice(-V612_MUM_TUT).map(r=>r.slice());
    rec.forming = olusanVar ? son.slice() : null;
    rec.bosluk = false;
    if (!rec.seededAt) _v612Sayac.tohum++;
    rec.seededAt = now;
  }catch(_){}
}

function _v612Not(m){
  if (!V612_NEHIR) return;
  const rec = _v612Kayit(m.symbol, m.interval);
  rec.lastReqAt = Date.now();
  rec.ivMs = rec.ivMs || _v612IvMs[m.interval] || 0;
}

// ── WS baglanti yonetimi: istenen (sembol,zaman dilimi) kumesi degisince yeniden kur ──
function _v612IstenenAkislar(){
  const now = Date.now(), bosta = V612_NEHIR_BOSTA_DK*60000;
  const aday = [];
  for (const rec of _v612Store.values()){
    if (rec.kapali) continue;
    if (!rec.lastReqAt || (now - rec.lastReqAt) > bosta) continue;
    aday.push(rec);
  }
  aday.sort((a,b)=> b.lastReqAt - a.lastReqAt);
  return aday.slice(0, V612_NEHIR_MAX)
             .map(r => `${r.symbol.toLowerCase()}@kline_${r.interval}`);
}

function _v612BaglantiKur(akislar, idx){
  const url = `${FAPI_WS_MARKET}/stream?streams=${akislar.join('/')}`;
  const slot = {ws:null, akislar:new Set(akislar), idx, acikMi:false, hata:0};
  try{
    const ws = new WebSocket(url);
    slot.ws = ws;
    ws.on('open', ()=>{ slot.acikMi = true; });
    ws.on('message', (raw)=>{
      try{
        const j = JSON.parse(raw.toString());
        const d = j && (j.data || j);
        if (d && d.e === 'kline') _v612WsOlay(d);
      }catch(_){}
    });
    ws.on('error', ()=>{ slot.hata++; });
    ws.on('close', ()=>{ slot.acikMi = false; _v612Sayac.wsDusme++; slot.akislar = new Set(); });
    try{ ws.on('ping', ()=>{ try{ ws.pong(); }catch(_){}} ); }catch(_){}
  }catch(_){ slot.akislar = new Set(); }
  _v612Baglantilar[idx] = slot;
}

function _v612NehirKur(){
  if (!V612_NEHIR || _v612Kuruluyor) return;
  _v612Kuruluyor = true;
  try{
    const istenen = _v612IstenenAkislar();
    const parca = [];
    for (let i=0;i<istenen.length;i+=V612_NEHIR_SHARD) parca.push(istenen.slice(i, i+V612_NEHIR_SHARD));
    for (let i=0;i<parca.length;i++){
      const mevcut = _v612Baglantilar[i];
      const ayni = mevcut && mevcut.acikMi && mevcut.akislar.size === parca[i].length &&
                   parca[i].every(s=>mevcut.akislar.has(s));
      if (ayni) continue;
      try{ mevcut?.ws?.close?.(); }catch(_){}
      _v612BaglantiKur(parca[i], i);
    }
    for (let i=parca.length;i<_v612Baglantilar.length;i++){
      try{ _v612Baglantilar[i]?.ws?.close?.(); }catch(_){}
      _v612Baglantilar[i] = null;
    }
    _v612SonKurulum = Date.now();
  }catch(_){}
  finally{ _v612Kuruluyor = false; }
}

// mutabakat sirasi: her turda EN ESKI denetlenmis bir anahtari zorla REST'e dusur
function _v612DenetimSec(){
  try{
    const now = Date.now();
    if (now - _v612SonDenetim < V612_DENETIM_DK*60000) return;
    _v612SonDenetim = now;
    let hedef = null;
    for (const rec of _v612Store.values()){
      if (rec.kapali || !rec.seededAt || rec.denetimSira) continue;
      if (!rec.depodan) continue;                       // hic depodan sunmadiysa denetlemeye gerek yok
      if (!hedef || (rec.sonDenetim||0) < (hedef.sonDenetim||0)) hedef = rec;
    }
    if (!hedef) return;
    hedef.sonDenetim = now;
    hedef.denetimBekleyen = hedef.rows.slice(-3).map(r=>r.slice());
    hedef.denetimSira = true;                            // bir sonraki cagri REST'e duser ve karsilastirilir
  }catch(_){}
}

