function formatBinanceError(path, data) {
  const code = data && data.code != null ? data.code : 'NO_CODE';
  const msg  = data && data.msg ? data.msg : JSON.stringify(data).slice(0,120);
  return `${path}: ${msg} (${code})`;
}

