    const ats=cnt(x)>0?v(x)/cnt(x):0; const atsR=(sn&&sa>0)?ats/(sa/sn):1; const vR=va>0?v(x)/(va/12):1;
    const body=Math.abs(c(x)-o(x))/o(x)*100; const er=vR/Math.max(0.15,body);
