  const _v626=v626SinifHukmu(_v626Metin);
  const proofMin=Math.max(1, Math.min(3, (top10?1:2) + Number(_v626.delta||0)));
  const firstRR=Number(truth?.firstObstacleRR??f.firstObstacleRR);
