    const chase=!!(isL?(rangePos>=0.82 && c5.p3>=1.45 && !fvgRetest && !oteOk && !sweepReclaim):(rangePos<=0.18 && c5.p3<=-1.45 && !fvgRetest && !oteOk && !sweepReclaim));
