    const chase=!!(isL ? (rangePos>=0.84 && c5.p3>=1.35 && !fvgRetest && !oteOk && !sweepReclaim) : (rangePos<=0.16 && c5.p3<=-1.35 && !fvgRetest && !oteOk && !sweepReclaim));
