    let capacity = 18 + Number(r290.capacity||0)*0.38 + Number(r289.quality||0)*0.12 + smcProofs*8.5 + liqProofs*7.5 + (setup!=='NONE'?12:0) + (tfAlign*3.5) + (room>1.4?5:0) - riskCount*12;
