function r442PusuKur(symbolFull, ai, kaynak) {
  try {
    if(v644PositionFocusActive())return;
    const base = String(symbolFull||'').replace('USDT','').toUpperCase();
    let entry = Number(ai?.entry || 0);
    if (!(entry > 0) || String(ai?.side||'').toUpperCase() === 'SHORT') return;
    // ═══ V652 ═══ PUSU SEVIYESI BOGAZDA CEKILIR.
    // V649 entryTruth.plannedEntry'yi cekiyordu; R486.3.9 anatomi yolu onu OKUMUYOR.
    // CLO 11:15:28: '0.14103 -> 0.13886' loglandi, pusu yine 0.14103'e kuruldu.
    // Burasi pusu seviyesinin gectigi TEK kapi — uretici hangisi olursa olsun calisir.
    if (V649_BOLGEDEN_GIRIS) {
      try {
        const _hf = v644CandidateMemoryContext(symbolFull, entry, {});
        const _tepe = Number(_hf?.available ? _hf?.entryZone?.high : 0) || 0;
        const _planSl = Number(ai?.sl || 0);
        // bolge tavani plan SL'inin ustunde degilse cekme (plan bozulmasin)
        if (_tepe > 0 && (!(_planSl > 0) || _tepe > _planSl)) {
          const _sap = (entry - _tepe) / _tepe * 100;
          if (_sap > V649_BOLGE_TOLERANS && _sap <= V649_BOLGE_MAX_SAPMA) {
            logAuto(`🎯 ${base} V652 pusu BÖLGEYE kuruldu: ${entry} → ${_tepe} · bölge ${_hf.entryZone.low}-${_hf.entryZone.high} (${_hf.entryZone.type}) · sapma %${_sap.toFixed(2)}`);
            entry = _tepe;
          } else if (_sap > V649_BOLGE_MAX_SAPMA) {
            logAuto(`⚠️ ${base} V652 pusu: hafıza bölgesi %${_sap.toFixed(2)} uzak (> %${V649_BOLGE_MAX_SAPMA}) — bayat, dokunulmadı`);
          }
        }
      } catch(_) {}
    }
    r442PusuPlanlar.set(base, {
      entry, sl: Number(ai?.sl||0) || null, tp: Number(ai?.tp||0) || null,
      conf: Number(ai?.confidence||0), ts: Date.now(),
      expiresAt: Date.now() + 75*60*1000, kaynak: String(kaynak||'')
    });
    logAuto(`🪤 ${base} R442 PUSU kuruldu (${kaynak}): fiyat ${entry} bölgesine (±%0.25) gelirse ${r451Merci()} frensiz uyandırılır (75dk geçerli, SL ${ai?.sl||'—'} altında iptal)`);
  } catch(_e) {}
}
async function r442PusuKontrol() {
  try {
    if(v644PauseCandidateWorker('R442'))return;
    const now = Date.now();
    for (const [base, p] of r442PusuPlanlar) {
      if(v644PositionFocusActive())return;
      if (now > p.expiresAt) { r442PusuPlanlar.delete(base); logAuto(`🪤 ${base} R442 pusu süresi doldu (75dk) — kaldırıldı`); continue; }
      const full = base + 'USDT';
      let mark = 0;
      try { const t = await bPub('/fapi/v1/ticker/price', `symbol=${full}`); mark = Number(t?.price || 0); } catch(_e) { continue; }
      // Fiyat isteği beklerken pozisyon açılmış olabilir. Wake yazmadan hemen önce
      // odağı yeniden doğrula; böylece yarış durumunda ikinci aday tetiklenmez.
      if(v644PositionFocusActive())return;
      if (!(mark > 0)) continue;
      if (p.sl && mark <= p.sl) { r442PusuPlanlar.delete(base); logAuto(`🪤 ${base} R442 pusu İPTAL: fiyat ${mark} plan SL'inin (${p.sl}) altına indi — plan geçersizleşti, körlemesine işletilmez`); continue; }
      const sapma = Math.abs(mark - p.entry) / p.entry * 100;
      if (sapma <= 0.25) {
        r442PusuPlanlar.delete(base);
        r442ForceAi.set(base, now);
        try { r125RegisterPriorityWake(full, 'R442_PUSU_TETIK', 95); } catch(_e) {}
        logAuto(`🎯 ${base} R442 PUSU TETİKLENDİ: fiyat ${mark} pusu planına (${p.entry}) ulaştı — ${r451Merci()} frensiz + öncelikli değerlendirmeye çağrılıyor (taze veriyle son kararı karar motoru verir)`);
      }
    }
  } catch(_e) {}
}
