  add('C20_L20_RSI_RATIO_FVG', r274EntryOk && (liveFlowOk || priority >= 58 || r274Score >= 34), r126PlaybookBase('C20_L20_RSI_RATIO_FVG', 76));
  candidates.sort((a,b)=>b.base-a.base);
