  const adaptiveFloor = Math.max(40, adaptiveFloorBase - (d.r190Edge?.earlyContinuation ? 6 : (d.r190Edge?.momentumWindow ? 3 : 0)));
  const needsPremiumProof = ['TREND_CONTINUATION','MOMENTUM_SCALP','FLOW_SCALP'].includes(primaryMode);
