  d.r191UnifiedEntryBlock = r191UnifiedEntryBlock;
  d.r191UnifiedBlockReason = r191UnifiedBlockReason;
  d.r193WeakZeroCandleDirtyFuel = r193WeakZeroCandleDirtyFuel;
  d.r193OiAnomalyNoFuel = r193OiAnomalyNoFuel;
