        // Sadece gerçekten ölü hacim (<0.20x) otomatik köprüyü kilitler; 0.20-0.70 arası ceza/uyarı olarak kalır.
        const rvolVeryLow = !!(rvol1h && Number(rvol1h.rvol || 0) < 0.20);
        const _slPctEval = parseFloat(autoConfig?.slPct || 2);
