async function emergencyCloseIfBracketMissing(apiKey, apiSecret, pos, reason='SLTP_PROOF_FAIL') {
  // J2: backtest tabani dolmadan acil kapatma yok. Gercek koruma acigi varsa once
  // yeniden kurma denenir; 60sn dolmadan pozisyon kapatilmaz.
  {const _g=v592MinHoldGuard(pos?.symbol||pos?.sym,'EMERGENCY_BRACKET');
   if(_g.blocked){console.log(`${pos?.symbol} J2: ${_g.ageMs}ms < ${V592_MIN_HOLD_MS}ms — acil kapatma ERTELENDI.`);
    return {closed:false,deferred:true,minHoldGuard:true,ageMs:_g.ageMs};}}
  const sym = pos.symbol;
  const snap = await bracketProtectionSnapshot(apiKey, apiSecret, sym);
  if (snap.hasSL && snap.hasTP) return { closed:false, protected:true, snap };
  try {
    // R288: -2022 ReduceOnly reddinde kör panik yapma. Önce gerçek pozisyonu tazele,
    // açık değilse kapandı kabul et; açıksa merkezi safeMarketClosePosition fallback'i kullan.
    const close = await safeMarketClosePosition(apiKey, apiSecret, sym, { reason:`${reason}_BRACKET_MISSING` });
    if (close.ok) {
      // V4.7.4.28-AS2: eskiden burada SADECE trailingState.delete vardi.
      // SKYAI tam bu daldan gecti ve defterde sonsuza kadar "acik" kaldi.
      const _st = (()=>{ try{ return trailingState.get(sym)||null; }catch(_){ return null; } })();
      if (close.alreadyClosed) {
        await v592FinalizeClose(sym,_st,null,`${reason}_BRACKET_MISSING_ALREADY_CLOSED`);
        pushCritical('SLTP_UPDATE_FAILSAFE_ALREADY_CLOSED', `${sym}: ${reason}; SL/TP proof yoktu ama pozisyon zaten kapanmış`, snap, 'WARNING');
        return { closed:false, alreadyClosed:true, protected:false, snap, close };
      }
      await v592FinalizeClose(sym,_st,{code:'EMERGENCY_BRACKET_MISSING',label:'Koruma yok, acil kapatildi',
        emoji:'🛑',closePrice:null,realizedPnl:null,side:_st?.side},`${reason}_BRACKET_MISSING`);
      setCooldown(sym, COOLDOWN_CLOSE_MS, `${reason} korumasız pozisyon acil kapatıldı`);
      pushCritical('SLTP_UPDATE_FAILSAFE_CLOSE', `${sym}: ${reason}; SL/TP eksikti, safe market close kapattı${close.fallback?' (reduceOnly fallback)':''}`, snap, 'WARNING');
      return { closed:true, protected:false, snap, order:close.order, close };
    }
    pushCritical('SLTP_UPDATE_FAILSAFE_CLOSE_FAIL', `${sym}: ${reason}; safe close başarısız ${close.error||'bilinmeyen'}`, snap, 'CRITICAL');
    return { closed:false, protected:false, snap, error:close.error || 'safe close failed', close };
  } catch(e) {
    pushCritical('SLTP_UPDATE_FAILSAFE_CLOSE_FAIL', `${sym}: ${reason}; acil safe close hata ${e.message}`, snap, 'CRITICAL');
    return { closed:false, protected:false, snap, error:e.message };
  }
}

async function updateStopLossWithProofJS(apiKey, apiSecret, pos, newSL, reason) {
  const sym = pos.symbol;
  const isLong = pos.side === 'LONG';
  const closeSide = isLong ? 'SELL' : 'BUY';
  const cfg = autoConfig || {};
  const state = trailingState.get(sym) || {};
  const mark = parseFloat(pos.markPrice || pos.entryPrice || 0);
  const entry = parseFloat(pos.entryPrice || mark || 0);
  // R277: tick-tabanlı güvenli SL. Mikro-fiyatlı coinlerde (HMSTR tickSize 1e-7) yüzdesel
  // clamp (0.9997) yeterli tick uzaklığı vermiyordu → SL mark'a 0-1 tick yapışıp Binance
  // "Order would immediately trigger (-2021)" reddediyordu. Min 3 tick VEYA %0.04 mesafe,
  // hangisi büyükse onu uygula; SL'i her zaman mark'ın DOĞRU tarafına it.
  let r277Tick = 0;
  try { const f = await getSymbolFilters(sym); r277Tick = Number(f?.tickSize) || 0; } catch (_) {}
  const r277MinGap = Math.max((r277Tick > 0 ? r277Tick * 3 : 0), mark * 0.0004);
  const requestedSL = Number(newSL);
  const requestedTooClose = !Number.isFinite(requestedSL) || requestedSL <= 0 ||
    (isLong ? requestedSL >= mark - r277MinGap : requestedSL <= mark + r277MinGap);
  const rewriteMeta = {
    reason:String(reason||'UNKNOWN'), side:pos.side, entry, mark,
    requestedSL:Number.isFinite(requestedSL)?requestedSL:null,
    currentSL:Number(state.currentSL||0)||null,
    currentSLAlgoId:state.currentSLAlgoId||null,
    minGap:r277MinGap, tickSize:r277Tick||null,
    openAgeMs:Number(state.openedAt||state.openTs||0)>0 ? Date.now()-Number(state.openedAt||state.openTs) : null
  };
  try{r501OrderLifeMark(sym,'PROTECTION_REWRITE_REQUEST',rewriteMeta);}catch(_){ }
  // SKYAI dersi: kazanılmamış BE/kâr-kilidi isteğini markın 3 tick altına
  // yapıştırmak hair-trigger SL üretir. Mevcut doğru bracket korunur.
  if (requestedTooClose) {
    try{r501OrderLifeMark(sym,'PROTECTION_REWRITE_DEFERRED',{...rewriteMeta,code:'REQUESTED_SL_NOT_EARNED'});}catch(_){ }
    logAuto(`🛡️ ${sym} ${reason} SL değişimi ertelendi: istek ${Number.isFinite(requestedSL)?requestedSL:'geçersiz'}, mark ${mark}; mevcut SL ${state.currentSL||'-'} korunuyor`);
    return {ok:false,deferred:true,keptExisting:true,reason:'REQUESTED_SL_NOT_EARNED',requestedSL,mark,minGap:r277MinGap};
  }
  const safeSL = requestedSL;
  let tpPrice = await currentBracketTP(apiKey, apiSecret, sym, isLong, entry, cfg.tpPct, state);
  // TP mark'a yanlış tarafta kalmışsa emri anında tetikletmemek için panel TP'sinden yeniden hesapla.
  if (isLong && tpPrice <= mark) tpPrice = calcFallbackTP(entry, true, cfg.tpPct);
  if (!isLong && tpPrice >= mark) tpPrice = calcFallbackTP(entry, false, cfg.tpPct);

  const proof = await installSLTPWithProof(apiKey, apiSecret, sym, closeSide, safeSL, tpPrice, sym);
  if (!proof.ok) {
    // R277: Proof başarısız olduğunda ÖNCE mevcut korumayı kontrol et, panik kapatma SON çare.
    // Binance'te hâlâ geçerli bir SL/TP varsa pozisyonu açık tut (kazananı erken öldürme).
    const existingSL = Number(state.currentSL || 0);
    const slStillValid = existingSL > 0 && (isLong ? existingSL < mark : existingSL > mark);
    if (slStillValid) {
      logAuto(`🛡️ ${sym} ${reason} yeni SL reddedildi ama mevcut SL ${existingSL} hâlâ geçerli (${isLong?'<':'>'} mark ${mark}); pozisyon AÇIK tutuldu, BE atlandı`);
      return { ok:false, proof, safeSL, tpPrice, keptExisting:true };
    }
    logAuto(`❌ ${sym} ${reason} SL/TP çifti doğrulanamadı ve mevcut geçerli SL yok; failsafe kontrol`);
    const failsafe = await emergencyCloseIfBracketMissing(apiKey, apiSecret, pos, `${reason}_SLTP_PROOF_FAIL`);
    if (failsafe.closed) logAuto(`🛡️ ${sym} korumasız kalmasın diye acil reduce-only kapatıldı`);
    else if (failsafe.protected) logAuto(`🛡️ ${sym} proof eşleşmedi ama Binance'te SL+TP mevcut; pozisyon açık bırakıldı`);
    else logAuto(`🚨 ${sym} SL/TP proof yok ve failsafe kapatma da başarısız: ${failsafe.error||'bilinmeyen'}`);
    return { ok:false, proof, safeSL, tpPrice, failsafe };
  }
  state.currentSL = proof.slPrice || safeSL;
  state.targetTP = proof.tpPrice || tpPrice;
  state.currentSLAlgoId = proof.slOrder?.algoId || proof.slOrder?.clientAlgoId || proof.slOrder?.orderId || null;
  state.tpAlgoId = proof.tpOrder?.algoId || proof.tpOrder?.clientAlgoId || proof.tpOrder?.orderId || null;
  state.sltpVerified = true;
  state.lastSltpUpdate = Date.now();
  trailingState.set(sym, state);
  try{r501OrderLifeMark(sym,'PROTECTION_REWRITE_ACK',{...rewriteMeta,safeSL:state.currentSL,tpPrice:state.targetTP,newSLAlgoId:state.currentSLAlgoId||null,newTPAlgoId:state.tpAlgoId||null});}catch(_){ }
  logAuto(`✅ ${sym} ${reason}: SL ${state.currentSL} + TP ${state.targetTP} Binance doğrulandı (tick:${proof.tickSize || '-'})`);
  return { ok:true, proof, safeSL: state.currentSL, tpPrice: state.targetTP };
}

// CVD + Tick delta flip tespiti — en kritik çıkış sinyali
async function updateBracketWithProofJS(apiKey, apiSecret, pos, newSL, newTP, reason) {
  const sym = pos.symbol;
  const isLong = pos.side === 'LONG';
  const closeSide = isLong ? 'SELL' : 'BUY';
  const mark = parseFloat(pos.markPrice || pos.entryPrice || 0);
  const state = trailingState.get(sym) || {};
  // R277: tick-tabanlı min mesafe (mikro-fiyat -2021 fix), updateStopLossWithProofJS ile aynı mantık.
  let r277Tick2 = 0;
  try { const f2 = await getSymbolFilters(sym); r277Tick2 = Number(f2?.tickSize) || 0; } catch (_) {}
  const r277Gap2 = Math.max((r277Tick2 > 0 ? r277Tick2 * 3 : 0), mark * 0.0004);
  const requestedSL = Number(newSL);
  const requestedTooClose = !Number.isFinite(requestedSL) || requestedSL <= 0 ||
    (isLong ? requestedSL >= mark - r277Gap2 : requestedSL <= mark + r277Gap2);
  if (requestedTooClose) {
    const meta={reason:String(reason||'EXTEND_TP'),side:pos.side,mark,requestedSL:Number.isFinite(requestedSL)?requestedSL:null,requestedTP:Number(newTP)||null,currentSL:Number(state.currentSL||0)||null,minGap:r277Gap2};
    try{r501OrderLifeMark(sym,'PROTECTION_REWRITE_DEFERRED',{...meta,code:'REQUESTED_SL_NOT_EARNED'});}catch(_){ }
    logAuto(`🛡️ ${sym} ${reason} bracket değişimi ertelendi: SL ${Number.isFinite(requestedSL)?requestedSL:'geçersiz'} mark ${mark} için henüz güvenli değil; mevcut bracket korunuyor`);
    return {ok:false,deferred:true,keptExisting:true,reason:'REQUESTED_SL_NOT_EARNED',requestedSL,mark,minGap:r277Gap2};
  }
  const safeSL = requestedSL;
  const proof = await installSLTPWithProof(apiKey, apiSecret, sym, closeSide, safeSL, newTP, sym);
  if (!proof.ok) {
    logAuto(`❌ ${sym} ${reason} bracket proof başarısız; failsafe kontrol`);
    const failsafe = await emergencyCloseIfBracketMissing(apiKey, apiSecret, pos, `${reason}_BRACKET_PROOF_FAIL`);
    return { ok:false, proof, failsafe, safeSL, newTP };
  }
  state.currentSL = proof.slPrice || safeSL;
  state.targetTP = proof.tpPrice || newTP;
  state.sltpVerified = true;
  state.lastSltpUpdate = Date.now();
  trailingState.set(sym, state);
  logAuto(`✅ ${sym} ${reason}: SL ${state.currentSL} + TP ${state.targetTP} Binance doğrulandı`);
  return { ok:true, proof, safeSL:state.currentSL, tpPrice:state.targetTP };
}

function detectCVDFlip(symbol, side) {
  const cvd = getCVD(symbol);
  if (!cvd || cvd.historyLen < 2) return { flip:false, reason:'Yeterli veri yok' };

  const isLong = side === 'LONG';
  const store  = cvdStore.get(symbol);
  if (!store || store.history.length < 3) return { flip:false };

  // Son 3 periyot delta
  const hist = store.history.slice(-3);
  const deltas = hist.map(h => h.delta);

  // Flip: pozitif deltalar negatife döndü (LONG için tehlike)
  const prevPositive = deltas.slice(0,-1).every(d => d > 0);
  const lastNegative = deltas[deltas.length-1] < -Math.abs(deltas[0]) * 0.5;

  if (isLong && prevPositive && lastNegative) {
    return { flip:true, reason:`CVD flip: Alım baskısı satışa döndü (${cvd.ratio.toFixed(0)}%)`, urgency:'HIGH' };
  }

  const prevNegative = deltas.slice(0,-1).every(d => d < 0);
  const lastPositive = deltas[deltas.length-1] > Math.abs(deltas[0]) * 0.5;

  if (!isLong && prevNegative && lastPositive) {
    return { flip:true, reason:`CVD flip: Satış baskısı alıma döndü (${cvd.ratio.toFixed(0)}%)`, urgency:'HIGH' };
  }

  return { flip:false };
}

// Delta divergence — fiyat gidiyor ama CVD desteklemiyor
function detectDeltaDivergence(symbol, side, entryPrice, currentPrice) {
  const cvd = getCVD(symbol);
  if (!cvd) return { divergence:false };

  const isLong = side === 'LONG';
  const priceMoved = isLong
    ? (currentPrice - entryPrice) / entryPrice * 100
    : (entryPrice - currentPrice) / entryPrice * 100;

  if (priceMoved < 0.3) return { divergence:false }; // Henüz hareket yok

  // Fiyat lehimize gitti ama CVD desteklemiyor
  const cvdSupports = isLong ? cvd.ratio > 45 : cvd.ratio < 55;
  const momentumWeak = cvd.momentum === 'NEGATIVE' || cvd.momentum === 'ACCELERATING_BEAR';
  const momentumWeakShort = cvd.momentum === 'POSITIVE' || cvd.momentum === 'ACCELERATING_BULL';

  if (isLong && priceMoved > 1 && !cvdSupports && momentumWeak) {
    return { divergence:true, reason:`Fiyat ↑ %${priceMoved.toFixed(1)} ama CVD zayıf (${cvd.ratio.toFixed(0)}%) — sahte hareket`, urgency:'MEDIUM' };
  }
  if (!isLong && priceMoved > 1 && cvdSupports && momentumWeakShort) {
    return { divergence:true, reason:`Fiyat ↓ %${priceMoved.toFixed(1)} ama CVD güçlü (${cvd.ratio.toFixed(0)}%) — sahte hareket`, urgency:'MEDIUM' };
  }

  return { divergence:false };
}

// Likidasyon cascade — ani büyük likidasyon ters yönde
function detectAdverseCascade(symbol, side) {
  const liq = getLiqData(symbol);
  if (!liq?.cascade) return { adverse:false };

  const isLong = side === 'LONG';
  const isAdverse = isLong
    ? liq.cascade.direction === 'LONG_CASCADE'   // Long pozisyonlar patladı
    : liq.cascade.direction === 'SHORT_CASCADE';  // Short pozisyonlar patladı

  if (isAdverse && liq.cascade.amount > 300000) { // $300K+
    return { adverse:true, reason:`Ters cascade: $${(liq.cascade.amount/1000).toFixed(0)}K ${liq.cascade.direction}`, urgency:'HIGH' };
  }
  return { adverse:false };
}

// ── R486 OTONOM KÂR HASADI ───────────────────────────────────────────────────
function r486N(v,d=0){ const n=Number(v); return Number.isFinite(n)?n:d; }
function r486Clamp(v,a,b){ return Math.max(a,Math.min(b,v)); }
function r486AutonomousProfitBrain({sym,side,pnlPct,realProfitPct,entryPrice,curPrice,leverage,state,tickSnap,r91Brain}) {
  try {
    const isLong=String(side).toUpperCase()==='LONG';
    const snap=state?.aiSnapshot||{}, story=snap?.chartStory||{}, cvd=getCVD(sym)||{}, ice=getIceberg(sym)||{};
    const peakRoi=Math.max(r486N(state?.peakPnl),r486N(pnlPct));
    const peakReal=Math.max(r486N(state?.peakRealPct),r486N(realProfitPct));
    const giveback=Math.max(0,peakRoi-r486N(pnlPct));
    const confidence=r486N(snap.aiConfidence,state?.aiBrain?.confidence||70);
    const storyQuality=r486N(story.quality,50);
    const funding=r486N(snap.funding,0), oi1h=r486N(snap.oiChange1h,0);
    const deltaRatio=r486N(tickSnap?.deltaRatio,50), recentDelta=r486N(tickSnap?.recent30s?.delta,0);
    const recentTotal=Math.max(1,r486N(tickSnap?.recent30s?.total,1));
    const aggDeltaPct=recentDelta/recentTotal*100;
    const cvdRatio=r486N(cvd.ratio,50), cvdMom=String(cvd.momentum||'UNKNOWN');
    const micro=tickSnap?.microstructure||{}, vpin=tickSnap?.vpin||{};
    const hiddenSell=r486N(ice.hiddenSell), hiddenBuy=r486N(ice.hiddenBuy);
    const icebergBear=/SELL/i.test(String(ice.signal||'')) && hiddenSell>hiddenBuy*1.15;
    const icebergBull=/BUY/i.test(String(ice.signal||'')) && hiddenBuy>hiddenSell*1.15;
    const flowAgainst=isLong ? (deltaRatio<45 || aggDeltaPct<-12 || cvdRatio<46 || tickSnap?.deltaFlip==='BULL_TO_BEAR')
                             : (deltaRatio>55 || aggDeltaPct>12 || cvdRatio>54 || tickSnap?.deltaFlip==='BEAR_TO_BULL');
    const flowWith=isLong ? (deltaRatio>55 || aggDeltaPct>12 || cvdRatio>56 || /BULL|POSITIVE/i.test(cvdMom))
                          : (deltaRatio<45 || aggDeltaPct<-12 || cvdRatio<44 || /BEAR|NEGATIVE/i.test(cvdMom));
    let continuation=0, pressure=0;
    if(flowWith) continuation+=1.25; if(!flowAgainst) continuation+=.35;
    if(tickSnap?.deltaTrend===(isLong?'BULL':'BEAR')) continuation+=.55;
    if(isLong?icebergBull:icebergBear) continuation+=.70;
    if(r486N(tickSnap?.whaleValid)&&tickSnap?.whaleBias===(isLong?'WHALE_BUY':'WHALE_SELL')) continuation+=.65;
    if(r486N(r91Brain?.exitScore)<2.3 && r91Brain?.devamGucu) continuation+=.75;
    if(flowAgainst) pressure+=1.35;
    if(micro.exhaustion && micro.exhaustionDir===(isLong?'BULL_EXHAUST':'BEAR_EXHAUST')) pressure+=.95;
    if(micro.trapped) pressure+=.85;
    if(isLong?icebergBear:icebergBull) pressure+=.85;
    if(vpin.toxicity==='EXTREME') pressure+=.55;
    if(r486N(r91Brain?.exitScore)>=3) pressure+=.85;
    if(isLong && funding > .08) pressure+=.45;
    if(funding<-.08 && !isLong) pressure+=.45;
    if(isLong && oi1h>1.5 && realProfitPct<peakReal*.55 && flowAgainst) pressure+=.75;
    if(!isLong && oi1h>1.5 && realProfitPct<peakReal*.55 && flowAgainst) pressure+=.75;
    const targets=[];
    const add=x=>{ const n=Number(x); if(n>0 && ((isLong&&n>entryPrice)||(!isLong&&n<entryPrice))) targets.push(n); };
    add(story.targetLiquidity); add(story.resistance); add(story.support);
    for(const x of (snap?.liqLevels?.ust||[])) if(isLong)add(x); for(const x of (snap?.liqLevels?.alt||[])) if(!isLong)add(x);
    const target=targets.length ? (isLong?Math.min(...targets):Math.max(...targets)) : 0;
    const targetProgress=target>0 ? r486Clamp(isLong?(curPrice-entryPrice)/(target-entryPrice):(entryPrice-curPrice)/(entryPrice-target),0,1.5) : 0;
    const targetHit=target>0 && targetProgress>=.96;
    if(targetHit) pressure+=1.10;
    const opp=r486Clamp(.42*confidence+.38*storyQuality+8*continuation-7*pressure,0,100);
    const matureRoi=r486Clamp(R486_HARVEST_MATURE_ROI+.16*(opp-60),7,32);
    const maturity=r486Clamp((Math.max(0,pnlPct)/Math.max(1,matureRoi))*1.25 + targetProgress + (targetHit ? .45 : 0),0,4);
    const runnerMode=!!(state?.aiRunner||state?.r281ProMap?.runner||state?.r283Recipe?.runner||String(state?.r283Recipe?.mode||'').toUpperCase()==='RUNNER'||String(state?.r282TradePlan?.mode||'').toUpperCase()==='RUNNER'||state?.r190Edge?.r192FuelOk||state?.r190Edge?.squeeze||state?.r190Edge?.earlyContinuation||String(snap?.aiKarKosma||snap?.karKosma||snap?.tradeMode||'').toUpperCase()==='RUNNER');
    const reversalSignals=[flowAgainst,!!(micro.exhaustion&&micro.exhaustionDir===(isLong?'BULL_EXHAUST':'BEAR_EXHAUST')),!!micro.trapped,!!(isLong?icebergBear:icebergBull),tickSnap?.deltaFlip===(isLong?'BULL_TO_BEAR':'BEAR_TO_BULL'),r486N(r91Brain?.exitScore)>=3].filter(Boolean).length;
    const reversalConfirmed=flowAgainst&&reversalSignals>=2;
    let close=false, reason='';
    if(pnlPct>=matureRoi && maturity>=2 && pressure>=R486_HARVEST_PRESSURE && continuation<2.7 && (!runnerMode||reversalConfirmed)){ close=true; reason='MATURE_PRESSURE'; }
    else if(pnlPct>=Math.max(6,matureRoi*.65) && targetHit && pressure>=2 && continuation<2.8 && (!runnerMode||reversalConfirmed||pressure>=3.4)){ close=true; reason='TARGET_REJECTION'; }
    else if(peakRoi>=matureRoi*1.25 && giveback>=Math.max(4,peakRoi*.24) && pressure>=1.7 && continuation<2.8){ close=true; reason='PEAK_GIVEBACK'; }
    else if(!runnerMode && pnlPct>=matureRoi*1.55 && continuation<2.95){ close=true; reason='SATISFYING_PROFIT'; }
    else if(runnerMode && R486_RUNNER_ROI_CAP_EXIT && pnlPct>=matureRoi*1.55 && continuation<2.95){ close=true; reason='RUNNER_ROI_CAP'; }
    const retain = continuation>=2.7 && pressure<1.8 ? .28 : pressure>=3.4 ? .72 : pressure>=2.2 ? .60 : .48;
    const lockRoi=peakRoi>=5?Math.max(1.8,peakRoi*retain):0;
    const lockRealPct=lockRoi/Math.max(R486_MIN_LEVERAGE,r486N(leverage,R486_MIN_LEVERAGE));
    return {active:R486_HARVEST_ACTIVE,shadow:R486_HARVEST_SHADOW,close,reason,runnerMode,roiCapExitEnabled:R486_RUNNER_ROI_CAP_EXIT,reversalConfirmed,reversalSignals,continuation:+continuation.toFixed(2),pressure:+pressure.toFixed(2),maturity:+maturity.toFixed(2),opportunity:+opp.toFixed(1),matureRoi:+matureRoi.toFixed(1),target:target||null,targetProgress:+targetProgress.toFixed(2),peakRoi:+peakRoi.toFixed(1),giveback:+giveback.toFixed(1),lockRoi:+lockRoi.toFixed(1),lockRealPct:+lockRealPct.toFixed(3),funding,oi1h,flowAgainst,flowWith,iceberg:String(ice.signal||'NEUTRAL')};
  } catch(e) { return {active:R486_HARVEST_ACTIVE,shadow:R486_HARVEST_SHADOW,close:false,error:String(e?.message||e).slice(0,100)}; }
}

// Ana pozisyon yöneticisi
async function managePosition(apiKey, apiSecret, pos) {
  // ═══ V607 ═══ KAR KILIDI / TRAILING SL KAPISI
  // 108 gunluk olcumde be_lock ve trailing OLU idi (carpan x0 == x3, ort. tutus 1,1s).
  // Backtest cikis kumesi: INITIAL_SL / TARGET / DYNAMIC_STOP / MAX_TIME_NO_PROGRESS / MAX_24H.
  // Kar kilidi bu kumede YOK; canlida acik kalinca kazananlar erken kesiliyor
  // (MUBARAK: TP +26 USDT idi, kar kilidi ~+4,4 USDT'de kapatti) ve kodun kendisi bunu
  // 'NON_BACKTEST_EXIT' diye isaretliyor. Kaybedenler tam SL'i yediginden PF cokuyor.
  // Borsadaki ILK SL/TP emirlerine DOKUNULMAZ; yalnizca SL'i ilerletme kapatilir.
  // Geri acmak icin: V607_KAR_KILIDI=1
  const _v607KarKilidi = String(process.env.V607_KAR_KILIDI || '0') === '1';
  // ═══ V625 ═══ V607 artik YALNIZ KILITLERI kapatir. Kar TASIMA ayri anahtarda.
  // Eskiden bu blok trailingPct/trailStep/breakEvenPct'i sifirliyordu; V625 acikken
  // sifirlamak trail mesafesini 0 yapar ve SL zirveye yapisir (ilk asagi tikte stop).
  if (!_v607KarKilidi && !V625_KAR_TASIMA) {
    try {
      if (autoConfig) {
        autoConfig.trailingPct = 0;
        autoConfig.trailStep = 0;
        autoConfig.breakEvenPct = 0;
      }
      const _v607St = trailingState.get(pos.symbol);
      if (_v607St) {
        if (_v607St.config) { _v607St.config.trailing = false; _v607St.config.trailingPct = 0; _v607St.config.trailStep = 0; _v607St.config.breakEvenPct = 0; }
        _v607St.breakEvenSet = true;          // BE kurulmus say -> tekrar kurmaya calismaz
        _v607St.profitLockLevel = 99;         // merdiven en ustte say -> yeni kademe tetiklenmez
      }
    } catch (_v607e) {}
  }
  const sym = pos.symbol;
  const side = pos.side;
  const isLong = side === 'LONG';
  const curPrice = pos.markPrice;
  const entryPrice = pos.entryPrice;
  const pnlPct = pos.pnlPct; // Kaldıraçlı PnL %

  // Kaldıraçsız gerçek fiyat hareketi — break-even için bunu kullan
  const priorState = trailingState.get(sym) || {};
  const leverage = Number(pos.leverage) > 1 ? Number(pos.leverage) : (Number(priorState.leverage) || Number(autoConfig?.leverage) || R486_MIN_LEVERAGE);  // R486: state TDZ hatası yok; 1x placeholder gerçek state leverage ile tamamlanır
  const realPricePct = entryPrice > 0
    ? Math.abs(curPrice - entryPrice) / entryPrice * 100
    : 0;
  const inProfit = pos.side === 'LONG'
    ? curPrice > entryPrice
    : curPrice < entryPrice;
  const realProfitPct = inProfit ? realPricePct : -realPricePct;

  // State al veya oluştur
  if (!trailingState.has(sym)) {
    trailingState.set(sym, {
      entryPrice, highWater:curPrice, currentSL:null, currentSLAlgoId:null,
      breakEvenSet:false, tpExtended:false, trendHoldCount:0,
      step1Set:false, step2Set:false, step3Set:false,
      peakPnl:0, peakRealPct:0, lastCheck:Date.now()
    });
  }
  const state = trailingState.get(sym);
  state.side = side;
  state.entryPrice = state.entryPrice || entryPrice;
  state.leverage = state.leverage || leverage;
  state.peakPnl    = Math.max(Number(state.peakPnl || 0), Number(pnlPct || 0));
  state.dipPnl     = Math.min(Number(state.dipPnl ?? 0), Number(pnlPct || 0)); // R389: MAE — işlem en kötü nereyi gördü
  state.lastManageTs = Date.now(); // R390: yönetici kalp atışı — kör pencere teşhisi için
  state.peakRealPct= Math.max(Number(state.peakRealPct || 0), Number(realProfitPct || 0));
  // R94: vur-kaç çıkış motoru yüksek kârı takip eder; küçük kârda ücret/kayma yememek için acele kilitlemez.
  // LONG için en yüksek fiyat, SHORT için en düşük fiyat pozisyon açıldığı andan itibaren izlenir.
  state.highWater = isLong
    ? Math.max(Number(state.highWater || curPrice), curPrice)
    : Math.min(Number(state.highWater || curPrice), curPrice);
  // R37: canlı yönetim timestamp'i her hızlı döngüde güncellensin.
  // Önceki sürümde action yoksa lastCheck/managerStatus eski kalıyor, panel 'kontrol 15dk önce' gösteriyordu.
  const stampManager = (type='İZLEME', reason=null, urgency='LOW') => {
    state.lastCheck = Date.now();
    state.managerStatus = {
      type, urgency,
      reason: reason || `${sym} ${side} canlı izleniyor • PnL %${Number(pnlPct||0).toFixed(2)} • BE:${state.breakEvenSet?'AKTİF':'bekliyor'} • SL/TP:${state.sltpVerified?'doğrulandı':'kontrol'}`,
      pnlPct:Number(pnlPct||0), peakPnl:Number(state.peakPnl||0), peakRealPct:Number(state.peakRealPct||0),
      currentSL:state.currentSL||null, targetTP:state.targetTP||null, lastCheck:state.lastCheck,
      r91Exit: state.r91Exit || null,
      exitMode: state.exitMode || null,
      profitLockLevel: state.profitLockLevel || null,
      r486Harvest: state.r486Harvest || null
    };
    trailingState.set(sym, state);
  };

  const cfg = autoConfig || {};
  // parseFloat + fallback — NaN koruması
  const safe = (v, def) => { const n=parseFloat(v); return isNaN(n)?def:n; };
  let   trailPct      = safe(cfg.trailingPct,  2); // R390: aşağıda ATR ile ölçeklenir
  // ═══ V622 ═══ SIFIR-MESAFE TRAIL TUZAGI. safe() sifiri gecerli sayar; V607=0 modu
  // autoConfig.trailingPct/trailStep'i 0 yazar. V607 sonradan 1 yapilir da config
  // sifir kalirsa trailPctEff=0 olur ve SL zirveye yapisir -> ilk asagi tikte stop.
  const _v622KarTasima = String(process.env.V622_KAR_TASIMA ?? '1') !== '0';
  if (_v622KarTasima && !(trailPct > 0)) trailPct = 2;
  const trailStep     = safe(cfg.trailStep,    0.25);
  // R310H: KÂR TAŞIMA PANELDEN BAĞIMSIZ — kullanıcı isteği: panel değerlerini EZ, kod karar versin.
  // Panel "1/2/3.5" gibi erken kilit yazsa bile YOK SAYILIR. Kâr koşsun diye geç kademe sabit.
  // R342: sabitler artık AI tarafından ayarlanabilir taban (aiBE/aiKT1-3); yoksa eski sabitler.
  // ═══ R390 ATR NORMALİZASYONU (TSLA 10.07 dersi, -3.44$: ATR %0.49'luk hisse-token'da BE tetiği
  // %0.8 = 1.6 ATR, ilk adım 3 ATR, trailing 4 ATR uzaktaydı — motor FİZİKSEL olarak erişilmezdi;
  // zirve +1 ATR yaptı, hiçbir kilit devreye giremedi, tam stop yedi. Koklama hisse-token'ları
  // (10x düşük ATR) havuza sokunca mutlak eşikler sessizce kırıldı. Çözüm: kâr eşikleri coinin
  // ATR'siyle ölçeklenir. ATR>=%3 (kripto koşucuları) → k=1, HİÇBİR ŞEY DEĞİŞMEZ. ATR bilinmiyorsa
  // k=1. SADECE KÂR TARAFI — kayıp kesişi R378 dersi gereği dokunulmaz. ChatGPT'nin "BE yok" teşhisi
  // yanlıştı; BE vardı ama düşük-ATR'de erişilmezdi. Anatomi satırı (🫀) bu deliği ifşa etti. ═══
  const r390Atr = Number(state.atrPct || 0);
  const r390K = r390Atr > 0 ? Math.min(1, Math.max(0.3, r390Atr / 3.0)) : 1;
  // ═══ V646 ═══ BACKTEST FORMULU: be_thr = max(.8*r390, .65) * geo,  geo = clamp(slPct/1.7, 1, 3)
  // Canlida geo yoktu -> BE 3 kat erken kuruluyordu (MAGMA %1,28 · ROBO BREAK_EVEN_SL +0,71$).
  // DIKKAT: state.slPct bu kodda HIC yazilmiyor; gercek stop mesafesi entry/currentSL'den turetilir.
  const _v646BeTaban = (Number(cfg.aiBE) > 0 ? Number(cfg.aiBE) : 0.8) * r390K;
  let _v646Sl = 0, _v646Kaynak = 'YOK';
  {
    const _e = Number(state?.entryPrice) || Number(state?.config?.entryPrice) || 0;
    // ═══ V648 ═══ backtestte `slpct` islem boyunca SABIT (plan stopu). Canlida currentSL
    // okunuyordu; stop BE'den once daralirsa geo kuculur ve BE ERKEN kurulur.
    // KOMAUSDT: %2,391 -> %1,903 daraldi, geo 1,4065 yerine 1,1196, BE %20,4 erken.
    const _s0 = V648_GEO_DONDUR ? (Number(state?.initialSL) || 0) : 0;
    const _s = _s0 > 0 ? _s0 : (Number(state?.currentSL) || 0);
    if (_e > 0 && _s > 0 && _s < _e) { _v646Sl = (_e - _s) / _e * 100; _v646Kaynak = (_s0 > 0 ? 'initialSL' : 'currentSL'); }
    else if (Number(cfg.slPct) > 0)  { _v646Sl = Number(cfg.slPct);    _v646Kaynak = 'cfg.slPct'; }
  }
  const _v646Geo = _v646Sl > 0 ? Math.max(1, Math.min(3, _v646Sl / 1.7)) : 1;
  // ═══ V649 ═══ V646/V648-D GERI ALINDI — CIFT GEO HATASI.
  // Bu degisken OPERATIF esik degil, TABAN: 23002 -> r192BreakEvenAt -> 23323 r283DynamicBE,
  // ve geo (r339GeoScale) ORADA zaten uygulaniyor. Buraya da eklendiginde geo IKI KEZ
  // carpildi ve non-runner'da basa-bas 3 kata kadar GEC kuruldu (slPct %5,5: %2,40 -> %7,20).
  // Operatif zincir V646 ONCESINDE ZATEN backtest paritesindeydi:
  //   non-runner: max(.8*r390, .65) * geo             == backtest
  //   runner    : max(.8*r390*geo, 2*geo, slPct*.75)  == backtest
  const breakEvenAt = _v646BeTaban;
  // Sessiz no-op olmasin: geo=1 ve kaynak YOK ise yama fiilen calismiyordur, logda gorunur.
  if (V646_BE_GEO && Number(state?._v646Log || 0) !== 1) {
    try { state._v646Log = 1; logAuto(`📐 ${sym} V646 BE esigi: %${_v646BeTaban.toFixed(2)} → %${breakEvenAt.toFixed(2)} · SL %${_v646Sl.toFixed(2)} (${_v646Kaynak}) · geo ${_v646Geo.toFixed(2)}`); } catch(_) {}
  }
  const karTasima1    = (Number(cfg.aiKT1) > 0 ? Number(cfg.aiKT1) : 1.5) * r390K;
  const karTasima2    = (Number(cfg.aiKT2) > 0 ? Number(cfg.aiKT2) : 3.0) * r390K;
  const karTasima3    = (Number(cfg.aiKT3) > 0 ? Number(cfg.aiKT3) : 5.5) * r390K;
  // ═══ R426 AKE DERSİ (15.07: +28% ROI'de çıktı, coin 45dk'da +112% daha yaptı = ~+500% ROI çöpe): ═══
  // r390K Math.min(1,...) ile 1'de TAVANLI — sadece düşük-ATR'de daraltıyor, dikey pompada trailing'i
  // GENİŞLETMİYORDU. ATR %15 coinde %2.5 trail = ilk nefeste çıkış. Düzeltme: SADECE trailing için
  // yukarı-ölçeklenen çarpan (tavan 2.5x, mutlak trail tavanı %8 = AI aralığıyla uyumlu).
  // Kâr-kilit merdiveni (BE/KT1-3) DOKUNULMAZ — r390K(≤1) ile kalır; gevşetme iki kez backtest'te çürüdü.
  // Kanıt: AKE bugün, YFI(+%39'da BE), EDGE(5 erken çıkış), DEXE merdiveni; 1m-gerçek-çıkış bt: trail5>2.5 (PF2.2v1.9).
  const r426KTrail = r390Atr > 0 ? Math.min(2.5, Math.max(0.3, r390Atr / 3.0)) : 1;
  trailPct = Math.min(8, trailPct * r426KTrail); // R426: dikey-faz nefes payı (ATR 3%→değişmez, 7.5%→2.5x, 15%→2.5x tavan)
  const minRR         = safe(cfg.minRR,        1.0); // Min R/R oranı
  // ═══ R457 KRİTİK DÜZELTME (canlı kanıt LA 21.07) ═══
  // slPct PANEL değerinden okunuyordu (%1.7) — oysa pozisyonun GERÇEK SL'i %5.66'ydı.
  // Sonuç: acil hasar koruması eşiği -%1.95'e düştü ve pozisyon -%2.23'te kesildi;
  // planlanan SL'e (-%5.66) hiç gidilmedi. LA o kesimden sonra 0.0577→0.0591'e geri döndü,
  // yani gerçek SL ile pozisyon HAYATTA KALIRDI. Aynı hata her işlemde tekrar ediyordu.
  // Öncelik: state.slPct (emir anında yazılan gerçek SL) → fiyattan hesap → panel (son çare).
  const r457SlFromPrice = (() => {
    try {
      const e = Number(state.entryPrice || entryPrice || 0), sl0 = Number(state.currentSL || state.stopLoss || 0);
      return (e > 0 && sl0 > 0) ? Math.abs(e - sl0) / e * 100 : 0;
    } catch(_e) { return 0; }
  })();
  const slPct = Math.max(0.1,
    Number(state.slPct) || Number(state.entrySLPct) || r457SlFromPrice || safe(cfg.slPct, 2));
  const tpPct         = safe(cfg.tpPct,        10);
  // BE emri sadece entry'ye değil, taker fee + olası stop-market kayması için
  // küçük kâr bölgesine taşınır. INJ örneğinde entry üstü kapanışa rağmen
  // komisyon/slippage nedeniyle eksi yazmıştı. Varsayılan %0.22 coin hareketi.
  const beFeeSafePct = Math.max(0.08, safe(cfg.beLockPct ?? cfg.breakEvenLockPct ?? cfg.beProfitLockPct, 0.22) * r390K); // R390
  const r281ProtectMode = !!(state.r281ProMap?.protect && !state.r281ProMap?.runner);
  const r281RunnerMode  = !!(state.r281ProMap?.runner);
  const r282Plan = state.r282TradePlan || {};
  const r283State = state.r283Recipe || {};
  // R310W: TREND-TAKİPLİ RUNNER — kullanıcı: "trend devam ediyorsa onunla devam et" (HOME/RESOLV kârı bırakma).
  // r310wTrendDevam aşağıda isCvdTrendHealthyForSide tanımından SONRA hesaplanır; burada placeholder.
  const r282RunnerModeBase = !!(state.aiRunner || r281RunnerMode || r283State.runner || r283State.mode === 'RUNNER' || r282Plan.mode === 'RUNNER' || state.r190Edge?.r192FuelOk || state.r190Edge?.squeeze || state.r190Edge?.earlyContinuation);
  let r282RunnerMode = r282RunnerModeBase; // R310W ile aşağıda trend-devam eklenir
  const r282ProtectMode = !!(!r282RunnerModeBase && (r281ProtectMode || r282Plan.mode === 'PROTECT' || r282Plan.mode === 'TACTICAL' || r283State.mode === 'TACTICAL'));

  // R39_TREND_HEALTH_TRAIL: trend sağlığı güçlüyse trailing'i hemen sıkıştırma.
  // Ama bu sadece SL sıkıştırmayı en fazla 3 kez erteler; BE, hard-loss, ters CVD/tick ve büyük geri çekilme hâlâ çalışır.
  const isCvdTrendHealthyForSide = () => {
    const cvd = getCVD(sym);
    const ratio = Number(cvd?.ratio ?? 50);
    const mom = String(cvd?.momentum || 'UNKNOWN');
    if (isLong) {
      return mom === 'ACCELERATING_BULL' || mom === 'POSITIVE' || ratio > 55; // R41B: cvdSideOk ile tutarlı
    }
    return mom === 'ACCELERATING_BEAR' || mom === 'NEGATIVE' || ratio < 45; // R41B: tutarlı
  };

  // R310W: TREND-TAKİPLİ RUNNER aktivasyonu (isCvdTrendHealthyForSide tanımlandıktan sonra).
  // SADECE KÂR bölgesinde (pnlPct > 1.5) + CVD trend sağlıklı → RUNNER gibi davran (kârı erken bırakma, trendle git).
  // Zararda ASLA tetiklenmez (pnlPct>1.5 şartı) → stop güvenliği korunur. HOME/RESOLV tipi trend kaçırmayı önler.
  if (!r282RunnerMode && Number(pnlPct||0) > 1.5 && isCvdTrendHealthyForSide()) {
    r282RunnerMode = true;
  }

  const calcPullbackFromHighWaterPct = (hw) => {
    const base = Number(hw || curPrice);
    if (!base || base <= 0) return 0;
    return isLong
      ? Math.max(0, (base - curPrice) / base * 100)
      : Math.max(0, (curPrice - base) / base * 100);
  };

  // R165: yüksek ROI kâr kilidi aşağıda, action/r91 helper hazırlandıktan sonra çalışır.

  // R94 AKTİF VUR-KAÇ ÇIKIŞ MOTORU — güvenli kâr bölgesinden önce küçük kâr kilidi yok
  // Amaç: Binance SL/TP emniyet kemeri olarak kalırken, kâr görüldüğünde TP'yi beklemeden
  // kâr kilidi / aktif çıkış kararı üretmek. EMA zorunlu kapı değildir; veri-terazi kullanılır.
  const calcR91ExitBrain = (extra={}) => {
    const cvd = getCVD(sym) || {};
    const tick = extra.tickSnap || null;
    const cascadeNow = extra.cascade || null;
    const div = detectDeltaDivergence(sym, side, entryPrice, curPrice) || {};
    const ratio = Number(cvd.ratio ?? 50);
    const mom = String(cvd.momentum || 'UNKNOWN');
    const cvdAgainst = isLong
      ? (ratio < 44 || mom === 'NEGATIVE' || mom === 'ACCELERATING_BEAR')
      : (ratio > 56 || mom === 'POSITIVE' || mom === 'ACCELERATING_BULL');
    const cvdSupport = isLong
      ? (ratio > 54 || mom === 'POSITIVE' || mom === 'ACCELERATING_BULL')
      : (ratio < 46 || mom === 'NEGATIVE' || mom === 'ACCELERATING_BEAR');
    const pullbackPct = calcPullbackFromHighWaterPct(state.highWater);
    const givebackRoi = Math.max(0, Number(state.peakPnl || 0) - Number(pnlPct || 0));
    const givebackReal = Math.max(0, Number(state.peakRealPct || 0) - Number(realProfitPct || 0));
    const adverseTick = !!(extra.tickFlip || extra.exhaustExit || extra.trappedExit);
    const adverseCascade = !!(cascadeNow && cascadeNow.adverse);
    let exitScore = 0;
    const reasons = [];
    // R305 KAZANANI BIRAK: kâr +%4 ROI üstündeyse, minik pullback/tek sinyalle kapatma.
    // Sadece GERÇEK ters dönüş (CVD flip + tick flip birlikte) veya büyük geri verme kapatır.
    // Bu, JTO +30% gibi kazananları 3-4dk'da kesmeyi durdurur — nefes verir.
    const inProfit = Number(pnlPct || 0) >= 4;  // ROI %4+ = kâr taşıma bölgesi
    const realReversal = !!((extra.cvdFlip?.flip && extra.tickFlip) || (extra.cvdFlip?.flip && extra.exhaustExit));
    if (extra.cvdFlip?.flip) { exitScore += inProfit ? 1 : 2; reasons.push('alım/satım baskısı ters döndü'); }
    if (cvdAgainst) { exitScore += inProfit ? 0.5 : 1.5; reasons.push('anlık baskı pozisyona karşı'); }
    if (extra.tickFlip) { exitScore += inProfit ? 1 : 2; reasons.push('işlem akışı ters döndü'); }
    if (extra.exhaustExit) { exitScore += inProfit ? 1 : 2; reasons.push('hareket yoruldu'); }
    if (extra.trappedExit) { exitScore += 2; reasons.push('tuzak izi var'); }
    if (adverseCascade) { exitScore += 2; reasons.push('ters likidasyon baskısı'); }
    if (div.divergence) { exitScore += inProfit ? 0.5 : 1.5; reasons.push('fiyat gidiyor ama veri desteklemiyor'); }
    // Kârdayken minik pullback (%0.25) kazananı ÖLDÜRMESİN — eşik yükseltildi
    if (!inProfit && pullbackPct >= 0.25) { exitScore += 1; reasons.push(`tepeden geri verme %${pullbackPct.toFixed(2)}`); }
    if (pullbackPct >= 0.45) { exitScore += 1; }
    // TRAILING: kârdayken sadece zirveden BÜYÜK geri verme (ROI %40) kapatsın — kâr taşı
    if (inProfit) {
      const givebackFromPeakRatio = Number(state.peakPnl || 0) > 0 ? givebackRoi / Number(state.peakPnl) : 0;
      // R309C AKILLI KÂR KORUMA (MITO dersi: +%6.57 zirve yaptı, kâr geri verildi).
      // R309Z: KÂR KOŞTURMA — geri-verme toleransı GEVŞETİLDİ (kullanıcı: "kâr sonuna kadar koşsun, max hedef").
      // Eski değerler kârı erken kapatıyordu (zirve %12+ → sadece %20 geri verince kilit). Artık daha geniş nefes:
      // kâr trendi sürdükçe koşar, sadece BÜYÜK geri dönüşte kilitlenir. Risk: kâr geri dönebilir (kullanıcı onayladı).
      // R372 BACKTEST KANITI (tam-eşit, 6 coin): bu SIKI giveback tablosu OPTIMAL. Gevşetmek denendi (%45-68'e)
      // ama kârı DÜŞÜRDÜ (+14.2$→+10.7$) — volatil TOP gainer'larda zirveden geri verme sert, geç kilitlersen kâr erir.
      // ERKEN KİLİTLEME BURADA DOĞRU. Bu tabloyu gevşetme (test edildi, kötüledi).
      const peak = Number(state.peakPnl || 0);
      let giveCap, minGive;
      if (peak >= 20)      { giveCap = 0.30; minGive = 5.0; }  // çok büyük kâr (%20+): zirveden %30 geri verince kilitle (eskiden %20)
      else if (peak >= 12) { giveCap = 0.35; minGive = 4.0; }  // büyük kâr: %35 nefes (eskiden %20) — koşmasına izin ver
      else if (peak >= 8)  { giveCap = 0.40; minGive = 3.0; }  // (eskiden %25)
      else if (peak >= 5)  { giveCap = 0.45; minGive = 2.5; }  // (eskiden %30)
      else                 { giveCap = 0.55; minGive = 3.5; }  // küçük kâr: en geniş nefes, erken kapanmasın
      if (givebackFromPeakRatio >= giveCap && givebackRoi >= minGive) {
        exitScore += 3;
        reasons.push(`zirveden %${(givebackFromPeakRatio*100).toFixed(0)} geri verildi (zirve %${peak.toFixed(1)} ROI) — akıllı kâr kilidi`);
      }
    } else {
      if (givebackRoi >= 5) { exitScore += 1; reasons.push(`kârdan geri verme ROI %${givebackRoi.toFixed(1)}`); }
      if (givebackRoi >= 10) { exitScore += 1.5; }
    }
    if (realProfitPct < 0 && openMinutes >= 3 && cvdAgainst && adverseTick) {
      exitScore += 2; reasons.push('işlem fikri erken bozuldu');
    }
    // R305 KAYBEDENİ ERKEN KES: zarardayken (ROI -%5 altı) fikir bozulduysa, SL'i bekleme.
    // Kayıpları -%13/-%23 ROI'ye kadar tutmayı durdurur — küçükken kes.
    if (Number(pnlPct||0) <= -5 && openMinutes >= 1.5 && (cvdAgainst || adverseTick || extra.cvdFlip?.flip)) {
      exitScore += 2.5; reasons.push(`zarar -%${Math.abs(Number(pnlPct)).toFixed(0)} ROI + akış karşı — küçükken kes`);
    }
    if (r281ProtectMode && openMinutes >= 0.8 && (cvdAgainst || adverseTick || pullbackPct >= 0.18)) {
      exitScore += 1.2; reasons.push('R281 PROTECT: grafik bölgesi hassas');
    }
    const devamGucu = cvdSupport && !extra.tickFlip && !extra.exhaustExit && !extra.trappedExit && pullbackPct < (r281ProtectMode ? 0.16 : 0.22);
    if (devamGucu && exitScore > 0) exitScore = Math.max(0, exitScore - 1.5);
    const mode = pnlPct >= 20 ? 'KÂR-KORU' : pnlPct >= 10 ? 'VUR-KAÇ' : pnlPct >= 4 ? 'KİLİT-HAZIR' : 'İZLE';
    return {
      active: true, mode, exitScore:+exitScore.toFixed(1), reasons: reasons.slice(0,5),
      pnlPct:+Number(pnlPct||0).toFixed(2), realProfitPct:+Number(realProfitPct||0).toFixed(3),
      peakPnl:+Number(state.peakPnl||0).toFixed(2), peakRealPct:+Number(state.peakRealPct||0).toFixed(3),
      pullbackPct:+pullbackPct.toFixed(3), givebackRoi:+givebackRoi.toFixed(2), givebackReal:+givebackReal.toFixed(3),
      cvdRatio:Number.isFinite(ratio)?+ratio.toFixed(1):null, cvdMomentum:mom, devamGucu
    };
  };

  const r91LockPriceFromPct = (lockPct) => {
    const pct = Math.max(0.04, Number(lockPct)||0);
    return isLong
      ? +(entryPrice * (1 + pct/100)).toFixed(8)
      : +(entryPrice * (1 - pct/100)).toFixed(8);
  };

  let action = null; // { type, reason, urgency }

  // R339: AI pozisyonu + GEOMETRİ ÖLÇEĞİ. Panel BE/kâr-taşıma/trailing yüzdeleri 5m-scalp (SL %1.7)
  // için ayarlıydı; AI 15m işlemi SL %3-9 ile açıyor. Eşikler işlemin KENDİ SL'ine oranla ölçeklenir —
  // M dersi (02.07): %0.9 harekette BE'ye alındı, BE avına takıldı, sonraki +%4'lük koşu kaçtı.
  const r339AiManaged = !!(state.aiBrain || state.brainMode === 'R308C_AI_LIVE');
  const r339GeoScale = r339AiManaged ? Math.min(3.0, Math.max(1.0, Number(state.slPct || slPct || 1.7) / 1.7)) : 1.0;

  // R24: 90dk+ açık kalan ve hâlâ BE bölgesine yaklaşmayan pozisyonu yormadan kapat.
  // R339: AI 15m işlemi zaman ister — AI pozisyonunda 150dk, RUNNER'da 240dk.
  const openedTs = Number(state.openedAt || state.entryAt || 0);
  const openMinutes = openedTs > 0 ? (Date.now() - openedTs) / 60000 : 0;
  const V600_MAXSURE_CARPAN = Math.max(0, Math.min(99, Number(process.env.V600_MAXSURE_CARPAN ?? 1)));
  const _v601MaxSureTaban = r339AiManaged ? (state.aiRunner ? 240 : 150) : 90;
  // V601: carpan 0 => Infinity (cikis DEVRE DISI). 0 ile CARPMAK olmaz —
  //       o zaman 'openMinutes > 0' olur ve cikis her pozisyonda ANINDA tetiklenir.
  const r339MaxSureDk = V600_MAXSURE_CARPAN <= 0 ? Infinity : _v601MaxSureTaban * V600_MAXSURE_CARPAN;
  // ═══ V649 ═══ backtest: `open_min > (240 runner : 150) and real < be_thr*.5`
  // be_thr = OPERATIF esik (r283DynamicBE ile ayni formul), HAM TABAN degil.
  // Canlida ham taban kullaniliyordu -> bu cikis backtestten cok daha erken tetikleniyordu.
  const _v649BeThr = r282RunnerMode
    ? Math.max(breakEvenAt * r339GeoScale, 2.0 * r339GeoScale, (r339AiManaged ? Number(state.slPct || slPct || 1.7) * 0.75 : 0))
    : ((r282ProtectMode ? Math.max(breakEvenAt, 0.55) : Math.max(breakEvenAt, 0.65)) * r339GeoScale);
  // Operatif esik pozisyon basina BIR KEZ loglanir — 'taban'i 'esik' sanmak bir daha mumkun olmasin.
  if (Number(state?._v649Log || 0) !== 1) {
    try { state._v649Log = 1; logAuto(`🎚️ ${sym} V649 BE OPERATIF esik %${_v649BeThr.toFixed(2)} · taban %${breakEvenAt.toFixed(2)} · geo ${Number(r339GeoScale).toFixed(2)} · slPct %${Number(state.slPct || slPct || 0).toFixed(2)} · ${r282RunnerMode ? 'RUNNER' : (r282ProtectMode ? 'PROTECT' : 'NORMAL')}`); } catch(_) {}
  }
  if (openMinutes > r339MaxSureDk && realProfitPct < _v649BeThr * 0.5) {
    action = {
      type:'MAX_SURE_KAPAT', urgency:'HIGH',
      reason:`${r339MaxSureDk}dk+ açık, kâr yok: hareket %${realProfitPct.toFixed(2)} < BE yarısı %${(_v649BeThr*0.5).toFixed(2)}`
    };
  }

  // ── 0. R14 ACİL ZARAR KORUMASI — SL çalışmaz/gecikirse kaçış ─────────────
  // Normalde Binance algo SL kapatmalı. Ama yeni sembol / aşırı hızlı fitil / proof gecikmesi
  // durumunda pozisyon SL seviyesinin ötesine sarkarsa 3 dakikalık taramayı beklemeden kapatılır.
  const hardLossReal = -Math.max(slPct + 0.25, slPct * 1.12); // SL %2 ise yaklaşık -%2.25 coin hareketi
  const hardLossRoi  = -Math.max((slPct * leverage) + 5, 30); // 15x %2 SL için yaklaşık -%35 ROI
  if (realProfitPct <= hardLossReal || pnlPct <= hardLossRoi) {
    if (V592_EXACT_BACKTEST_AUTHORITY) {
      v592ShadowNonBacktestExit(sym,'R14_HARD_LOSS',{realProfitPct,pnlPct,hardLossReal,hardLossRoi,slPct,leverage});
    } else {
    action = {
      type:'EMERGENCY_EXIT', urgency:'CRITICAL',
      reason:`Acil hasar koruması: fiyat hareketi %${realProfitPct.toFixed(2)}, ROI %${pnlPct.toFixed(1)}; SL gecikmesi/slippage riski`
    };
    }
  }

  // R42: Mutlak hasar sigortası. CVD sağlıklı görünse bile yüksek kaldıraçta
  // belirli ROI hasarından sonra Binance SL'yi bekleme; bu AIGENSYN -40%/-46% tipini keser.
  const r42AbsoluteDamageRoiCap = -Math.min(28, Math.max(18, slPct * leverage * 0.65));
  if (!action && !r339AiManaged && openMinutes <= 45 && pnlPct <= r42AbsoluteDamageRoiCap) {  // R339: AI pozisyonunda SL kararı AI'ın (R334 zaten SL×lev≤%40 boyutlar)
    action = {
      type:'EMERGENCY_EXIT', urgency:'CRITICAL',
      reason:`Mutlak hasar kes: ROI %${pnlPct.toFixed(1)} <= %${r42AbsoluteDamageRoiCap.toFixed(1)}; yüksek kaldıraçta SL sonunu bekleme`
    };
    if (V592_EXACT_BACKTEST_AUTHORITY) {
      v592ShadowNonBacktestExit(sym,'R42_ABSOLUTE_DAMAGE',{pnlPct,cap:r42AbsoluteDamageRoiCap,slPct,leverage,openMinutes});
      action = null;
    }
  }

  // R41: 20x/25 USDT gibi ayarlarda %2 coin SL = yaklaşık -%40 ROI demek.
  // AIGENSYN benzeri ters akışta tüm SL'yi beklemek yerine erken hasar kes.
  // Trend sağlığı hâlâ pozisyon yönündeyse dokunmaz; veri nötr/zayıfsa küçük SL'den önce kaçar.
  const r41EarlyDamageRoiCap = -Math.min(22, Math.max(14, slPct * leverage * 0.45));
  if (!action && !r339AiManaged && openMinutes <= 30 && pnlPct <= r41EarlyDamageRoiCap && !isCvdTrendHealthyForSide()) {  // R339: AI pozisyonunda çalışmaz
    action = {
      type:'EMERGENCY_EXIT', urgency:'HIGH',
      reason:`Erken hasar kes: ROI %${pnlPct.toFixed(1)} <= %${r41EarlyDamageRoiCap.toFixed(1)} ve CVD/tick trend sağlığı yok`
    };
    if (V592_EXACT_BACKTEST_AUTHORITY) {
      v592ShadowNonBacktestExit(sym,'R41_EARLY_DAMAGE',{pnlPct,cap:r41EarlyDamageRoiCap,slPct,leverage,openMinutes});
      action = null;
    }
  }

  // R283: Hasar tavanı erken küçük kâr için değil, yanlış yemeği erken çöpe atmak için.
  // Runner'a nefes verilir; taktik/normal işlemde fikir açıkça bozulursa SL sonu beklenmez.
  const r282MaxRoiRisk = Number(r282Plan.maxRoiRisk || (r282ProtectMode ? 11 : r282RunnerMode ? 24 : 15));
  if (!action && !r339AiManaged && openMinutes >= 0.8 && !r282RunnerMode && pnlPct <= -Math.abs(r282MaxRoiRisk)) {  // R339: AI pozisyonunda çalışmaz
    action = {
      type:'R282_ROI_HASAR_KAPAT', urgency:'HIGH',
      reason:`R283 hasar kes: ${r282Plan.mode||'NORMAL'} işlem ROI %${pnlPct.toFixed(1)} <= -%${Math.abs(r282MaxRoiRisk).toFixed(1)}; grafik fikri çalışmadı, SL sonu beklenmiyor`
    };
  }

  // ── 1. ACİL ÇIKIŞ — CVD Flip ────────────────────────────────────────────
  const cvdFlip   = detectCVDFlip(sym, side);
  const tickSnap  = getTickAnalysis(sym);

  // Tick delta flip — acil çıkış
  const tickFlip = tickSnap && (
    (isLong  && tickSnap.deltaFlip==='BULL_TO_BEAR') ||
    (!isLong && tickSnap.deltaFlip==='BEAR_TO_BULL')
  );

  // Exhaustion — kârdayken momentum bitti, çık
  const exhaustExit = tickSnap?.microstructure && (
    (isLong  && tickSnap.microstructure.exhaustion &&
     tickSnap.microstructure.exhaustionDir==='BULL_EXHAUST') ||
    (!isLong && tickSnap.microstructure.exhaustion &&
     tickSnap.microstructure.exhaustionDir==='BEAR_EXHAUST')
  );

  // Trapped trader — pozisyon yönünde trapped = çabuk çıkış olacak
  const trappedExit = tickSnap?.microstructure?.trapped && (
    (isLong  && tickSnap.microstructure.lastDelta < 0) ||
    (!isLong && tickSnap.microstructure.lastDelta > 0)
  );
  // CVD flip — kaldıraçsız fiyat hareketi > 0.2% kârdayken (çok hassas)
  // R164: CVD flip eşiği dinamik — yüksek ROI'da acil çıkış yerine SL koru
  // %80 ROI'da CVD flip → kapatma değil, SL sıkıştır
  // Düşük ROI'da (<5%) hızlı çıkış, yüksek ROI'da (>20%) sadece SL taşı
  const cvdFlipMinProfit = pnlPct >= 40 ? 2.0 : pnlPct >= 20 ? 1.0 : pnlPct >= 10 ? 0.5 : 0.2;
  const r341FlipMin = r339AiManaged ? Math.max(1.2, Number(state.slPct || slPct) * 0.6) : cvdFlipMinProfit;  // R341: AI işleminde flip gürültüsü +%0.2'de kesemez
  if ((cvdFlip.flip || tickFlip || exhaustExit || trappedExit) && realProfitPct > r341FlipMin) {
    if (tickFlip)    cvdFlip.reason = `Tick delta flip: ${tickSnap?.deltaFlip}`;
    if (exhaustExit) cvdFlip.reason = `Exhaustion: momentum bitti`;
    if (trappedExit) cvdFlip.reason = `Trapped trader: hızlı ters dönüş bekleniyor`;
    // R164: Yüksek ROI'da (>%30 kaldıraçlı) flip = acil çıkış değil, SL koru
    if (pnlPct >= 30) {
      // SL kilitleme işareti — aşağıdaki kar koruma bloğu devreye girecek
      state.cvdFlipHighProfit = true;
      trailingState.set(sym, state);
    } else if (V592_EXACT_BACKTEST_AUTHORITY) {
      v592ShadowNonBacktestExit(sym,'CVD_FLIP',{pnlPct,realProfitPct,reason:String(cvdFlip?.reason||'')});
    } else {
      action = { type:'EMERGENCY_EXIT', ...cvdFlip };
    }
  }

  // ── 2. ACİL ÇIKIŞ — Ters Cascade ────────────────────────────────────────
  let cascade = null;
  if (!action) {
    cascade = detectAdverseCascade(sym, side);
    if (cascade.adverse && realProfitPct > (r339AiManaged ? Math.max(0.8, Number(state.slPct || slPct) * 0.4) : 0)) { // Kârdayken cascade gelirse koru (R341: AI'da anlamlı kâr eşiği)
      if (V592_EXACT_BACKTEST_AUTHORITY) {
        v592ShadowNonBacktestExit(sym,'ADVERSE_CASCADE',{pnlPct,realProfitPct,reason:String(cascade?.reason||'')});
      } else {
      action = { type:'EMERGENCY_EXIT', ...cascade };
      }
    }
  }

  // R24: küçük kârda tek zayıf flip yüzünden çıkma. En az iki ters teyit yoksa BE/trailing yönetsin.
  if (action?.type === 'EMERGENCY_EXIT' && realProfitPct > 0 && realProfitPct < 3.0) {
    const reversalHits = [
      !!cvdFlip.flip, !!tickFlip, !!exhaustExit, !!trappedExit, !!(cascade && cascade.adverse)
    ].filter(Boolean).length;
    if (reversalHits < 2) {
      logAuto(`⏳ ${sym} erken çıkış engellendi: kaldıraçsız kâr %${realProfitPct.toFixed(2)}, ters teyit ${reversalHits}/2`);
      action = null;
    }
  }

  // ── R94 AKTİF VUR-KAÇ ÇIKIŞ — TP beklemeden ama net kâr güvenli bölgeye gelince çıkış ────────
  const r91VurKacAktif = cfg.vurKacEnabled !== false; // panelde kapatılırsa sadece klasik SL/TP+BE kalır
  const r91Brain = calcR91ExitBrain({ cvdFlip, tickSnap, tickFlip, exhaustExit, trappedExit, cascade });
  state.r91Exit = r91Brain;
  state.exitMode = r91Brain.mode;

  // R486: OI/funding/order-flow/order-book/aggTrade/absorption/iceberg + grafik hedeflerinden
  // otonom kâr olgunluğu çıkar. SHADOW modunda yalnız telemetri/SL önerisi; ACTIVE=1 ise
  // olgun kârda TP beklemeden reduce-only market çıkışı.
  const r486Harvest = r486AutonomousProfitBrain({sym,side,pnlPct,realProfitPct,entryPrice,curPrice,leverage,state,tickSnap,r91Brain});
  state.r486Harvest = r486Harvest;
  // R486.2: Mekanik giriş daha ilk 35-180sn içinde hiç kâr üretmeden, canlı akış/çıkış beyni birlikte ters döndüyse
  // tam SL'i bekleme. Tek sensörle çalışmaz: baskı + exitScore + continuation birlikte zorunludur.
  const r4862Mechanical = !!(state.mekanik || state.aiBrain?.mekanik === true || state.aiSnapshot?.mekanik === true);
  const r4862EntryTruth = state.aiSnapshot?.chartStory?.entryTruth || state.aiBrain?.story?.entryTruth || {};
  const r4862EarlyInvalid = !!(R486_EARLY_INVALIDATION_ACTIVE && R486_HARVEST_ACTIVE && !action && r4862Mechanical &&
    openMinutes >= 0.58 && openMinutes <= 3.0 && Number(state.peakPnl||0) < 2.5 && pnlPct <= R486_EARLY_INVALIDATION_MIN_ROI &&
    Number(r486Harvest?.continuation||0) <= 0.8 && Number(r486Harvest?.pressure||0) >= R486_EARLY_INVALIDATION_PRESSURE &&
    Number(r91Brain?.exitScore||0) >= R486_EARLY_INVALIDATION_EXIT_SCORE &&
    (r4862EntryTruth?.earlyRisk === true || r486Harvest?.flowAgainst === true));
  if (r4862EarlyInvalid) {
    action={type:'R486_2_EARLY_SETUP_INVALIDATION',urgency:'HIGH',
      reason:`R486.2 erken setup geçersizliği: ${openMinutes.toFixed(1)}dk · ROI %${pnlPct.toFixed(1)} · zirve %${Number(state.peakPnl||0).toFixed(1)} · devam ${r486Harvest.continuation} · baskı ${r486Harvest.pressure} · çıkış ${r91Brain.exitScore}/10 — SL sonu beklenmiyor`};
  }
  if (R486_HARVEST_ACTIVE && !action && inProfit && Number(r486Harvest?.lockRealPct||0) > 0) {
    const lockSL = isLong
      ? +(entryPrice*(1+Number(r486Harvest.lockRealPct)/100)).toFixed(8)
      : +(entryPrice*(1-Number(r486Harvest.lockRealPct)/100)).toFixed(8);
    const currentSLNum=Number(state.currentSL||0);
    const better=isLong?(!currentSLNum||lockSL>currentSLNum):(!currentSLNum||lockSL<currentSLNum);
    if (better) action={type:'R486_HARVEST_LOCK',urgency:'LOW',newSL:lockSL,
      reason:`R486 otonom kâr tabanı: zirve ROI %${Number(r486Harvest.peakRoi||0).toFixed(1)} · devam ${r486Harvest.continuation} · baskı ${r486Harvest.pressure} → %${Number(r486Harvest.lockRoi||0).toFixed(1)} ROI korunuyor`,
      stateUpdates:{r486HarvestLock:true,profitLockLevel:Math.max(Number(state.profitLockLevel||0),5)}};
  }
  if (!action && r486Harvest?.close) {
    if (R486_HARVEST_ACTIVE) {
      action={type:'R486_AUTONOMOUS_PROFIT_EXIT',urgency:'HIGH',
        reason:`R486 otonom hasat ${r486Harvest.reason}: ROI %${Number(pnlPct||0).toFixed(1)} · hedef ilerleme %${(Number(r486Harvest.targetProgress||0)*100).toFixed(0)} · devam ${r486Harvest.continuation} · çıkış baskısı ${r486Harvest.pressure}`};
    } else if (Date.now()-Number(state.r486ShadowLogTs||0)>60_000) {
      state.r486ShadowLogTs=Date.now();
      logAuto(`🧪 ${sym} R486 SHADOW hasat: ${r486Harvest.reason} · ROI %${Number(pnlPct||0).toFixed(1)} · devam ${r486Harvest.continuation} · baskı ${r486Harvest.pressure} — market çıkışı yapılmadı`);
    }
  }

  // R283: Kârı erken boğma yok. Normal trader küçük yeşili hemen cebine atmaz;
  // setup çalışıyorsa hedef/FVG/likidite yoluna nefes verir. Sadece fikir bozulursa hasar keser.
  if (!action) {
    const r282ExitScore = Number(r91Brain.exitScore || 0);
    const r282Peak = Number(state.peakPnl || 0);
    const r282Give = Math.max(0, r282Peak - Number(pnlPct || 0));
    const r282EarlyBEroi = Number(r282Plan.earlyBEroi || (r282ProtectMode ? 10.0 : 11.0));
    const r282ScratchMin = Number(r282Plan.scratchAfterMin || (r282ProtectMode ? 3.5 : 5));
    const r282MinHoldWin = Number(r282Plan.minHoldWinMin || (r282RunnerMode ? 6 : 4));
    if (!state.breakEvenSet && !r282RunnerMode && pnlPct >= r282EarlyBEroi && openMinutes >= r282MinHoldWin && realProfitPct > 0.10 && !r91Brain.devamGucu) {
      action = {
        type:'BREAK_EVEN', urgency:'LOW',
        reason:`R283 geç BE: ROI %${pnlPct.toFixed(1)} gördü ama devam gücü zayıfladı; küçük kârı hemen boğmadan komisyon üstü korunuyor`,
        newSL: +(entryPrice * (isLong ? (1 + beFeeSafePct/100) : (1 - beFeeSafePct/100))).toFixed(8),
        stateUpdates:{ breakEvenSet:true, beFeeSafePct, r283LateBE:true }
      };
    } else if (!r339AiManaged && !r282RunnerMode && openMinutes >= r282ScratchMin && r282Peak < 7 && pnlPct <= -4.8 && r282ExitScore >= (r282ProtectMode ? 2.4 : 3.0)) {  // R339: AI pozisyonunda SL kararı AI'ın
      action = {
        type:'R282_FIKIR_BOZULDU_KAPAT', urgency:'HIGH',
        reason:`R283 fikir bozuldu: ${openMinutes.toFixed(1)}dk içinde setup çalışmadı, ROI %${pnlPct.toFixed(1)}, çıkış puanı ${r282ExitScore}/10 — zararı büyütmeden çıkış`
      };
    } else if (!r282RunnerMode && r282Peak >= 12 && r282Give >= Math.max(7.0, r282Peak * 0.62) && pnlPct <= Math.max(2.0, r282Peak * 0.20) && !r91Brain.devamGucu) {
      action = {
        type:'R282_WINNER_SCRATCH_KAPAT', urgency:'HIGH',
        reason:`R283 kazanan bozuldu: zirve ROI %${r282Peak.toFixed(1)} → mevcut %${pnlPct.toFixed(1)}, devam gücü yok — kârı zarara döndürmeden çıkış`
      };
    } else if (!r282RunnerMode && pnlPct >= 18 && openMinutes >= r282MinHoldWin && r282ExitScore >= 4.5 && !r91Brain.devamGucu) {
      action = {
        type:'R282_PROFIT_TAKE_KAPAT', urgency:'MEDIUM',
        reason:`R283 hedefli kâr alma: ROI %${pnlPct.toFixed(1)} ve grafik/akış yoruldu; küçük kâr değil, olgunlaşmış kâr alınıyor`
      };
    }
  }

  // R192: Kaliteli yakıt varsa BE biraz nefes alır; yakıt bozulursa R165/R149 kilitleri aynen çalışır.
  const r192OpenFuel = !!(state.r190Edge?.r192FuelOk || state.r190Edge?.squeeze || state.r190Edge?.earlyContinuation);
  const r192LiveFoot = r192FootprintFromTickData(tickSnap || {}, side);
  const r192LiveFootAligned = !!(r192LiveFoot?.aligned && !r192LiveFoot?.against);
  const r192MomentumBreath = !!(r192OpenFuel && r91Brain.devamGucu && r192LiveFootAligned && !tickFlip && !exhaustExit && !trappedExit && Number(r91Brain.exitScore||0) < 2.5);
  const r192BreakEvenAt = r192MomentumBreath ? Math.max(breakEvenAt, Math.min(0.55, breakEvenAt + 0.20)) : breakEvenAt;
  if (r192MomentumBreath && !state.breakEvenSet && realProfitPct >= breakEvenAt && realProfitPct < r192BreakEvenAt) {
    state.r192BeBreath = Number(state.r192BeBreath||0) + 1;
    if (state.r192BeBreath <= 4) logAuto(`⏳ ${sym} R192 BE nefesi: yakıt devam ediyor (${r192LiveFoot.label}); BE %${breakEvenAt}→%${r192BreakEvenAt.toFixed(2)}`);
    trailingState.set(sym, state);
  }

  // ── R165 ROI KÂR KİLİDİ — R164'teki sessiz hata düzeltildi ─────────────
  // R164 bloğu action ve r91LockPriceFromPct tanımlanmadan çalışıyordu; ayrıca
  // PROFIT_LOCK_UPDATE aksiyonu uygulama listesinde yoktu. Sonuç: %40-%80 ROI
  // görülse bile SL gerçekten Binance'e taşınmayabiliyordu. Bu blok aksiyon
  // nesnesi hazırlandıktan sonra çalışır ve R165_KAR_KILIDI olarak gerçek SL yazar.
  const r165PeakRoi = Number(state.peakPnl || 0);
  const r165GivebackRoi = Math.max(0, r165PeakRoi - Number(pnlPct || 0));
  const r165LockTable = [
    { min: 90, lockReal: 3.20, level: 7 },
    { min: 70, lockReal: 2.40, level: 6 },
    { min: 50, lockReal: 1.70, level: 5 },
    { min: 35, lockReal: 1.10, level: 4 },
    { min: 25, lockReal: 0.75, level: 3 },
    { min: 16, lockReal: 0.45, level: 2 },
    { min: 9,  lockReal: 0.24, level: 1 },
  ];
  if (!action && inProfit && r165PeakRoi >= 9) {
    const lock = r165LockTable.find(x => r165PeakRoi >= x.min);
    if (lock) {
      // Geri verme arttıysa kilidi biraz daha yukarı al; ama mevcut fiyatı geçip
      // stop emrini geçersiz yapmasın diye updateStopLossWithProofJS ayrıca mark'a göre clamp eder.
      const givebackBoost = r165GivebackRoi >= 18 ? 0.35 : r165GivebackRoi >= 10 ? 0.20 : 0;
      const lockRealPct = lock.lockReal + givebackBoost;
      const lockSL = r91LockPriceFromPct(lockRealPct);
      const currentSLNum = Number(state.currentSL || 0);
      const betterLock = isLong ? (!currentSLNum || lockSL > currentSLNum) : (!currentSLNum || lockSL < currentSLNum);
      if (betterLock && !r339AiManaged) {  // R341: AI işleminde kilitler geo-ölçekli kâr taşıma + r91'e ait
        action = {
          type:'R165_KAR_KILIDI', urgency: r165PeakRoi >= 35 ? 'MEDIUM' : 'LOW', newSL:lockSL,
          reason:`R165 kâr kilidi: zirve ROI %${r165PeakRoi.toFixed(1)}, mevcut %${Number(pnlPct||0).toFixed(1)}, geri verme %${r165GivebackRoi.toFixed(1)} → SL entry +%${lockRealPct.toFixed(2)} gerçek kâr bölgesine`,
          stateUpdates:{ breakEvenSet:true, r165ProfitLock:true, profitLockLevel:Math.max(Number(state.profitLockLevel||0), lock.level) }
        };
      }
    }
  }

  // +ROI görmüş işlem tekrar zarara gömülmesin. Büyük zirveden sonra runner gücü yoksa
  // market reduce-only kapatır; bu WR garantisi değildir, fakat +80 ROI → eksi kapanış
  // tipindeki ana sapmayı kesmek için tasarlandı.
  const r165WinnerNeverLoserExit = !!(!action && !r339AiManaged && r165PeakRoi >= 20 && !r91Brain.devamGucu && (
    (r165PeakRoi >= 70 && pnlPct <= Math.max(12, r165PeakRoi * 0.30)) ||
    (r165PeakRoi >= 40 && pnlPct <= Math.max(8,  r165PeakRoi * 0.25)) ||
    (r165PeakRoi >= 20 && pnlPct <= Math.max(4,  r165PeakRoi * 0.18))
  ));
  if (r165WinnerNeverLoserExit) {
    action = {
      type:'R165_WINNER_NEVER_LOSER_KAPAT', urgency:'HIGH',
      reason:`R165 winner-never-loser: zirve ROI %${r165PeakRoi.toFixed(1)} → mevcut %${Number(pnlPct||0).toFixed(1)}; devam gücü yok, kâr zarara dönmeden market çıkış`
    };
  }

  // ── R149 ROI KÂR KASASI — işlem sayısını azaltmadan kârdaki pozisyonu daha iyi koru ──
  // Giriş kapısı değildir; sadece açık pozisyon yönetir. Amaç büyük bakiyede küçük ROI kârlarını
  // toplamaya uygun şekilde, +ROI görmüş işlemin tekrar zarara dönmesini azaltmaktır.
  const r149PeakRoi = Number(state.peakPnl || 0);
  const r149PeakReal = Number(state.peakRealPct || 0);
  const r149GivebackRoi = Math.max(0, r149PeakRoi - Number(pnlPct || 0));
  const r149EntryTxt = [state.openReason, state.brainMode, state.entryPermissionReason, state.entryReason?.reason].filter(Boolean).join(' ').toLowerCase();
  const r149ScalpLike = /mikro|scalp|vur-kaç|vurkac|flow|momentum|tuzak dönüşü|counter_trap|hızlı edge|fast edge/.test(r149EntryTxt);
  const r149ShouldLock = !!(!action && !r339AiManaged && r149PeakRoi >= 8 && pnlPct > 2 && realProfitPct > 0.10 && (r149GivebackRoi >= 4 || Number(r91Brain.exitScore||0) >= 2 || r149PeakRoi >= 16));
  if (r149ShouldLock) {
    let keepRealPct = r149PeakReal * (r149ScalpLike ? 0.58 : 0.48);
    if (r149PeakRoi >= 20) keepRealPct = Math.max(keepRealPct, r149PeakReal * 0.64);
    if (r149PeakRoi >= 35) keepRealPct = Math.max(keepRealPct, r149PeakReal * 0.72);
    // Aşırı sıkıştırma yok: current price üstüne/altına SL basıp pozisyonu anında boğma.
    keepRealPct = Math.max(0.18, Math.min(Math.max(0.20, r149PeakReal - 0.10), keepRealPct));
    const rawVaultSL = r91LockPriceFromPct(keepRealPct);
    const vaultSL = isLong ? Math.min(rawVaultSL, +(curPrice * 0.998).toFixed(8)) : Math.max(rawVaultSL, +(curPrice * 1.002).toFixed(8));
    const betterVault = isLong ? (!state.currentSL || vaultSL > state.currentSL) : (!state.currentSL || vaultSL < state.currentSL);
    if (betterVault) {
      action = {
        type:'R149_ROI_VAULT_LOCK', urgency:'LOW', newSL:vaultSL,
        reason:`R149 ROI kâr kasası: zirve ROI %${r149PeakRoi.toFixed(1)}, mevcut %${pnlPct.toFixed(1)}, geri verme %${r149GivebackRoi.toFixed(1)} → SL kâr kasasına alındı`,
        stateUpdates:{ r149VaultLock:true, profitLockLevel:Math.max(Number(state.profitLockLevel||0), 4) }
      };
    }
  }

  // +ROI görmüş işlem tekrar sıfıra/zarara gömülmesin. Devam gücü varsa dokunmaz;
  // sadece kârı ciddi geri verip akış zayıfladığında market reduce-only kapatır.
  const r149WinnerGivebackExit = !!(!action && !r339AiManaged && r149PeakRoi >= 12 && r149GivebackRoi >= Math.max(8, r149PeakRoi * 0.55) && pnlPct <= Math.max(1.5, r149PeakRoi * 0.18) && !r91Brain.devamGucu);
  if (r149WinnerGivebackExit) {
    action = {
      type:'R149_PROFIT_GIVEBACK_KAPAT', urgency:'HIGH',
      reason:`R149 kâr geri verme koruması: zirve ROI %${r149PeakRoi.toFixed(1)} → mevcut %${pnlPct.toFixed(1)}; runner gücü yok, kâr sıfıra dönmeden çıkış`
    };
  }

  // ── R430 AI KÂR-KORUMA RACHETİ (kullanıcı talebi 20.07) ──────────────────
  // R165/R149 kâr koruma motorları AI pozisyonlarında KAPALIYDI (!r339AiManaged şartı) →
  // AI işlemi zirveden TÜM kârı geri verebiliyordu. Bu blok sadece AI pozisyonlarında çalışır:
  // (a) KADEMELİ KİLİT: zirve ROI eşiği aşınca SL gerçek kâr bölgesine çekilir — kâr artık zarara dönemez.
  //     Runner'da kademeler gevşek (koşuya alan), NORMAL'de sıkı (vur-kaç karakteri).
  // (b) ACİL ÇIKIŞ: bariz kâr geri verişi (zirvenin yarısından fazlası) + devam gücü yok → market kapat.
  if (r339AiManaged) {
    const r430Peak = Number(state.peakPnl || 0);
    const r430Giveback = Math.max(0, r430Peak - Number(pnlPct || 0));
    const r430Run = !!state.aiRunner;
    const r430Table = r430Run
      ? [ {min:120, lock:4.0}, {min:80, lock:2.6}, {min:50, lock:1.5}, {min:30, lock:0.8} ]
      : [ {min:60, lock:2.2}, {min:40, lock:1.4}, {min:25, lock:0.8}, {min:14, lock:0.35} ];
    const r430L = r430Table.find(x => r430Peak >= x.min);
    if (!action && inProfit && r430L) {
      // R436 MEGA KILIT: zirve ROI 80+ runner'da kilit tabloda kalmaz — zirve GERCEK karin %40'i
      // kilitlenir (TAIKO dersi: +489 ROI zirvede tablo kilidi %4'tu, dev karin tamami riskteydi).
      const r436LockPct = (r430Run && r430Peak >= 80)
        ? Math.max(r430L.lock, Number(state.peakRealPct || 0) * 0.40)
        : r430L.lock;
      const r430SL = r91LockPriceFromPct(r436LockPct);
      const r430CurSL = Number(state.currentSL || 0);
      const r430Better = isLong ? (!r430CurSL || r430SL > r430CurSL) : (!r430CurSL || r430SL < r430CurSL);
      const r430Safe = isLong ? r430SL < curPrice * 0.997 : r430SL > curPrice * 1.003;  // SL fiyatın üstüne basıp anında boğmasın
      if (r430Better && r430Safe) {
        action = { type:'R165_KAR_KILIDI', urgency:'LOW', newSL:r430SL,
          reason:`R430/R436 AI kâr kilidi${r430Run?' (RUNNER)':''}: zirve ROI %${r430Peak.toFixed(1)} → SL gerçek kâr +%${r436LockPct.toFixed(2)} bölgesine — kâr artık zarara dönemez, koşu devam edebilir`,
          stateUpdates:{ breakEvenSet:true, r430Lock:true } };
      }
    }
    const r430GivebackExit = !!(!action && r430Peak >= (r430Run ? 25 : 12) &&
      r430Giveback >= Math.max(10, r430Peak * (r430Run ? 0.55 : 0.45)) &&
      Number(pnlPct||0) <= r430Peak * 0.5 && !r91Brain.devamGucu);
    if (r430GivebackExit) {
      action = { type:'R149_PROFIT_GIVEBACK_KAPAT', urgency:'HIGH',
        reason:`R430 AI kâr-koruma acil çıkış${r430Run?' (RUNNER)':''}: zirve ROI %${r430Peak.toFixed(1)} → mevcut %${Number(pnlPct||0).toFixed(1)} (geri veriş %${r430Giveback.toFixed(1)}); devam gücü yok — bariz kâr geri verişi, market kapatıldı` };
    }
  }

  // R349 (03.07 GUA dersi): r91 hızlı kâr kilitleri ROI tabanlı — 5x RUNNER'da +9 ROI = +%1.8 gerçek
  // hareket, kilit SL'i girişe çekip R344'ün "BE ancak SL yolunun %75'inde" kuralını deliyordu.
  // RUNNER'da bu kilitler TAMAMEN kapalı (BE/kâr-taşıma/trailing geo sistemi sahibi); NORMAL AI'da
  // eşikler geometriyle ölçekli (vur-kaç karakteri korunur ama 15m nefesine uyar).
  const r349LocksOff = r339AiManaged && !!state.aiRunner;
  const r349LockScale = r339AiManaged ? r339GeoScale : 1.0;
  if (!action && r91VurKacAktif && !r349LocksOff) {
    // 1) İlk kâr görünür görünmez BE'den önce küçük kâr kilidi.
    // R136: 5m kaldıraçlı TOP10'da çok erken SL sıkıştırmak, EPIC gibi işlemi
    // +0.06$ küçük kâra boğabiliyor. Akış hâlâ pozisyon yönündeyse ilk kilidi
    // birkaç döngü nefeslendir; ters teyit gelirse eski emniyet yine çalışır.
    const r136RunnerBreathOk = !!(r91Brain.devamGucu && Number(r91Brain.exitScore||0) < 2.5 && realProfitPct < 1.45);
    if (!action && pnlPct >= 9 * r349LockScale && realProfitPct >= 0.45 * r349LockScale && !state.r91FirstLock && r136RunnerBreathOk && Number(state.r136FirstLockBreath||0) < 4) {
      state.r136FirstLockBreath = Number(state.r136FirstLockBreath||0) + 1;
      trailingState.set(sym, state);
      logAuto(`⏳ ${sym} R136 kâr nefesi: erken ilk kâr kilidi bekletildi [${state.r136FirstLockBreath}/4] · kâr %${realProfitPct.toFixed(2)} · çıkış puanı ${r91Brain.exitScore}/10`);
    } else if (pnlPct >= 9 * r349LockScale && realProfitPct >= 0.45 * r349LockScale && !state.r91FirstLock) {
      // ═══ V622 ═══ tavan (%0,55) kaldirildi: kilit anlik karin orani, sabit kirinti degil.
      const lockPct = (String(process.env.V622_KAR_TASIMA ?? '1') !== '0')
        ? Math.max(0.22, realProfitPct * 0.45)
        : Math.max(0.22, Math.min(0.55, realProfitPct * 0.45));
      const lockSL = r91LockPriceFromPct(lockPct);
      const better = isLong ? (!state.currentSL || lockSL > state.currentSL) : (!state.currentSL || lockSL < state.currentSL);
      if (better) action = {
        type:'R97_KAR_KILIDI', urgency:'LOW', newSL:lockSL,
        reason:`5m Fırsat Beyni güvenli kâr kilidi: ROI %${pnlPct.toFixed(1)} → komisyon/kayma payı geçildi, SL kâr bölgesine alındı`,
        stateUpdates:{ r91FirstLock:true, profitLockLevel:1, breakEvenSet:true }
      };
    }

    // 2) Kâr büyüdüyse SL kâr bölgesine daha agresif taşınır.
    // R136: ikinci kilit de trend/flow sağlıklıysa %1.15 altında acele sıkışmasın.
    const r136SecondBreathOk = !!(r91Brain.devamGucu && Number(r91Brain.exitScore||0) < 3.0 && realProfitPct < 1.15);
    if (!action && pnlPct >= 14 * r349LockScale && realProfitPct >= 0.70 * r349LockScale && !state.r91SecondLock && r136SecondBreathOk && Number(state.r136SecondLockBreath||0) < 3) {
      state.r136SecondLockBreath = Number(state.r136SecondLockBreath||0) + 1;
      trailingState.set(sym, state);
      logAuto(`⏳ ${sym} R136 ikinci kâr kilidi nefesi [${state.r136SecondLockBreath}/3] · kâr %${realProfitPct.toFixed(2)} · çıkış puanı ${r91Brain.exitScore}/10`);
    } else if (!action && pnlPct >= 14 * r349LockScale && realProfitPct >= 0.70 * r349LockScale && !state.r91SecondLock) {
      // ═══ V622 ═══ tavan (%0,85) kaldirildi. Olculen zirve medyani %4,64; %0,85'lik
      // sabit kilit trailing'in devralmasini geciktiriyordu.
      const lockPct = (String(process.env.V622_KAR_TASIMA ?? '1') !== '0')
        ? Math.max(0.35, realProfitPct * 0.55)
        : Math.max(0.35, Math.min(0.85, realProfitPct * 0.55));
      const lockSL = r91LockPriceFromPct(lockPct);
      const better = isLong ? (!state.currentSL || lockSL > state.currentSL) : (!state.currentSL || lockSL < state.currentSL);
      if (better) action = {
        type:'R97_KAR_KILIDI', urgency:'LOW', newSL:lockSL,
        reason:`5m Fırsat Beyni ikinci kâr kilidi: ROI %${pnlPct.toFixed(1)}, net kâr korundu`,
        stateUpdates:{ r91SecondLock:true, profitLockLevel:2, breakEvenSet:true }
      };
    }

    // 3) Gerçek vur-kaç: kâr var + hareket bozulduysa TP beklenmez, reduce-only market çıkar.
    // R338: AI pozisyonu mu ve AI "RUNNER" mı dedi? Kullanıcı ilkesi: küçük fırsat → vur-kaç (NORMAL),
    // gerçek trend devamı → sonuna kadar taşı, kârı zirveden koruyarak (RUNNER). Bot AI'ın seçimine uyar.
    const r338AiManaged = !!((state.aiBrain && state.aiBrain.mekanik !== true && state.aiBrain.aiCallMade !== false) || state.brainMode === 'R308C_AI_LIVE');
    const r338Runner = !!state.aiRunner;
    const r91ExitNow = r338Runner
      ? (
        // RUNNER: erken kâr-alma kapıları geriye itilir; sadece BÜYÜK kâr + gerçekten bozulan tablo
        // ya da zirveden ciddi geri verme (kâr koruması) kapatır. 15m yapısı kırılana kadar taşınır.
        // R430 (kullanıcı dersi 20.07: +%250 koşu kaçtı): eski eşik (+40 ROI & puan 3.5) 5x'te +%8 coin
        // hareketinde tetikleniyordu — runner'ın erken çıkışının kök nedeni. Artık devam gücü VARKEN
        // runner puan çıkışıyla KAPANMAZ; çıkış ancak devam gücü yokken + tablo gerçekten bozukken.
        (!r91Brain.devamGucu && pnlPct >= 60 && r91Brain.exitScore >= 5.0) ||
        (!r91Brain.devamGucu && pnlPct >= 30 && r91Brain.exitScore >= 6.5) ||
        (!r91Brain.devamGucu && pnlPct >= 12 && r91Brain.givebackRoi >= Math.max(14, Number(state.peakPnl||0) * 0.50) && r91Brain.exitScore >= 4.0)
      )
      : (
      (pnlPct >= 25 && r91Brain.exitScore >= 2.5) ||
      (pnlPct >= 18 && r91Brain.exitScore >= 3.0) ||
      (pnlPct >= 12 && r91Brain.exitScore >= 4.0) ||
      (pnlPct >= 10 && r91Brain.givebackRoi >= 7 && r91Brain.exitScore >= 3.0) ||
      (pnlPct >= 8  && realProfitPct >= 0.55 && r91Brain.givebackRoi >= 9 && r91Brain.exitScore >= 4.0) ||
      // R309C ORTA KÂR BANDI (MITO dersi: +%6.57 zirve yapıp geri verdi, eski kapılar %8 altını kapsamıyordu).
      // %4-8 ROI arası kâr + zirveden ciddi geri verme + ters akış → kârı koru, kapat.
      (pnlPct >= 4 && Number(state.peakPnl||0) >= 5 && r91Brain.givebackRoi >= (Number(state.peakPnl||0) * 0.30) && r91Brain.exitScore >= 3.0)
      );
    if (!action && r91ExitNow) {
      action = {
        type:'R97_VUR_KAC_KAPAT', urgency:'HIGH',
        reason:`5m Fırsat Beyni çıkışı: ROI %${pnlPct.toFixed(1)}, zirve %${r91Brain.peakPnl.toFixed(1)}, çıkış puanı ${r91Brain.exitScore}/10 — ${r91Brain.reasons.join(' + ') || 'kâr geri verilmeden alındı'}`
      };
    }

    // 4) İşlem fikri erken bozulursa SL sonunu bekleme; ama tek zayıf veriyle de kapatma.
    // R305: eşik 6→4 (kaybı küçükken kes), -%6→-%5 (daha erken). Kayıpları -%13/-%23'e taşımayı durdurur.
    if (!action && !r338AiManaged && openMinutes >= 2 && pnlPct <= -5 && r91Brain.exitScore >= 4 && !r91Brain.devamGucu) {  // R338: AI pozisyonunda SL kararı AI'ın
      action = {
        type:'R97_FIKIR_BOZULDU_KAPAT', urgency:'HIGH',
        reason:`5m Fırsat Beyni fikir bozuldu: ROI %${pnlPct.toFixed(1)}, çıkış puanı ${r91Brain.exitScore}/10 — ${r91Brain.reasons.join(' + ')}`
      };
    }

    // R144: HMSTR tipi hızlı-edge girişlerde fiyat hemen eksiye döner ve canlı akış tersleşirse
    // tam SL'yi bekleme. 20x/10x 5m scalp'te ROI -6/-8 erken uyarıdır; amaç kaybı büyümeden kesmek,
    // kârlı runner'ı boğmak değildir. Devam gücü varsa çalışmaz.
    const r144DamageControlNow = !!(
      !action && !r338AiManaged && openMinutes >= 0.8 && pnlPct <= -4.5 && !r91Brain.devamGucu &&  // R338: AI pozisyonunda çalışmaz
      (Number(r91Brain.exitScore||0) >= 4 || tickFlip || cvdAgainst || cvdFlip?.flip || trappedExit || exhaustExit)
    );
    if (r144DamageControlNow) {
      action = {
        type:'R144_HASAR_KONTROL_KAPAT', urgency:'HIGH',
        reason:`R144 hasar kontrolü: ROI %${pnlPct.toFixed(1)} erken eksiye döndü, çıkış puanı ${r91Brain.exitScore}/10 — ${r91Brain.reasons.join(' + ') || 'canlı akış tersleşti'}`
      };
    }

    // R146: hızlı-edge mikro-scalp zarar büyütme freni.
    // Bu oyun runner değil, kısa tepki avıdır. İlk dakikalarda hiç kâr üretmeden ROI -7/-8 bölgesine inerse
    // exitScore düşük kalsa bile SL'nin tamamını beklemek küçük bakiyede gereksiz büyük ROI hasarı üretir.
    const r146EntryTxt = [state.openReason, state.brainMode, state.entryPermissionReason, state.entryReason?.reason].filter(Boolean).join(' ').toLowerCase();
    const r146FastEntry = /hızlı edge|fast edge|mikro-scalp|r135_fast|r144 hızlı/.test(r146EntryTxt);
    const r146NoProfitFastFail = !r338AiManaged && r146FastEntry && openMinutes >= 1.0 && openMinutes <= 12 && Number(state.peakPnl||0) < 6 && pnlPct <= -7.0;
    if (!action && r146NoProfitFastFail) {
      action = {
        type:'R144_HASAR_KONTROL_KAPAT', urgency:'HIGH',
        reason:`R146 hızlı scalp başarısız: ROI %${pnlPct.toFixed(1)}, ilk ${openMinutes.toFixed(1)}dk içinde kâr üretemedi; SL sonu beklenmiyor`
      };
    }

    // R147: ROBO tipi yanlış yön tuzak dönüşü açıldıysa hasarı bekletme.
    // Bu, kârlı runner'ı boğmaz; sadece 5m formasyon yok/live-opposite/mum tahmini ters gibi
    // giriş anında zaten kötü kokan pozisyon ilk dakikalarda ROI -8/-10'a düşerse çalışır.
    const r147BadEntryTxt = /tuzak dönüşü|counter_trap|live-opposite|formasyon yok|mumtahmin:short|mumtahmin:düşüş|mumtahmin:long|mumtahmin:yükseliş|zemin:bozuk|r147/.test(r146EntryTxt);
    const r147DirectionForecastAgainst = (isLong && /mumtahmin:short|mumtahmin:düşüş/.test(r146EntryTxt)) || (!isLong && /mumtahmin:long|mumtahmin:yükseliş/.test(r146EntryTxt));
    const r147NoProfitTrapFail = !r338AiManaged && r147BadEntryTxt && (r147DirectionForecastAgainst || /live-opposite|formasyon yok|zemin:bozuk/.test(r146EntryTxt)) &&
      openMinutes >= 0.8 && openMinutes <= 10 && Number(state.peakPnl||0) < 5 && pnlPct <= -7.5;
    if (!action && r147NoProfitTrapFail) {
      action = {
        type:'R147_TERS_AKIS_HASAR_KAPAT', urgency:'HIGH',
        reason:`R147 ters-akış hasar kontrolü: ROI %${pnlPct.toFixed(1)}, ilk ${openMinutes.toFixed(1)}dk içinde kâr üretemedi; girişteki canlı/mum akışı ters olduğu için SL sonu beklenmiyor`
      };
    }

    // R281: PROTECT girişlerde amaç pozisyonu boğmak değil; MM iğne/FVG/likidite hassassa
    // ilk dakikalarda hiç kâr üretmeyip veri terse dönerse SL sonunu beklememek.
    const r281ProtectFail = !!(!r338AiManaged && r281ProtectMode && !r281RunnerMode && openMinutes >= 1.2 && openMinutes <= 10 && Number(state.peakPnl||0) < 5 && pnlPct <= -5.5 && Number(r91Brain.exitScore||0) >= 3.2);
    if (!action && r281ProtectFail) {
      action = {
        type:'R281_PROTECT_HASAR_KAPAT', urgency:'HIGH',
        reason:`R281 PROTECT hasar kontrolü: ROI %${pnlPct.toFixed(1)}, zirve ROI %${Number(state.peakPnl||0).toFixed(1)}, grafik bölgesi hassas ve canlı veri desteklemedi — SL sonu beklenmiyor`
      };
    }

    // 5) 5m vur-kaçta hareket yoksa ve veri tersleşmişse pozisyonu yorma.
    if (!action && !r338Runner && openMinutes >= 12 && pnlPct > -5 && pnlPct < 4 && r91Brain.exitScore >= 5 && !r91Brain.devamGucu) {  // R338: RUNNER 12dk'da yorulmaz, 15m işi zaman ister
      action = {
        type:'R97_VUR_KAC_KAPAT', urgency:'MEDIUM',
        reason:`5m Fırsat Beyni süre yönetimi: ${openMinutes.toFixed(0)}dk geçti, hareket zayıf, veri tersleşti — pozisyon yormadan kapatılıyor`
      };
    }
  }

  // ── 3. DELTA DİVERGENCE — TP Genişletme İptal, SL Sıkıştır ─────────────
  const divergence = detectDeltaDivergence(sym, side, entryPrice, curPrice);
  if (!action && divergence.divergence) {
    // R340 FIX (02.07 TLM/BIRB dersi): bu blok +%0.3 "kâr"da SL'i fiyatın %1.25 altına çekiyordu.
    // %10 ATR'li gainer'da +%0.3-1 spike gürültüdür → giriş dakikalarında SL girişin dibine iniyor,
    // ilk salınım stopluyordu (TLM 1dk -%0.18, BIRB 3dk -%0.24 tam bu kalıptı). AI işleminde
    // divergence sıkıştırması ancak ANLAMLI yol alındıysa (SL mesafesinin yarısı, min %1) çalışır
    // ve sıkıştırma mesafesi işlem geometrisiyle ölçeklenir.
    // R341: R340 eşiği dar-SL işlemde yetersizdi (TLM 21:37 -%0.21'de yine kesildi).
    // AI pozisyonunda divergence sıkıştırması TAMAMEN kapalı — kâr koruması r91 RUNNER/NORMAL
    // kapıları + kâr taşıma + trailing'e aittir, 5m divergence gürültüsüne değil.
    const r340DivMinProfit = 0.3;
    const r340DivGapPct = trailPct * 0.5;
    if (!r339AiManaged && realProfitPct > r340DivMinProfit) {
      action = { type:'TIGHTEN_SL', reason:divergence.reason, urgency:'MEDIUM',
        newSL: isLong
          ? +(curPrice * (1 - r340DivGapPct/100)).toFixed(8)
          : +(curPrice * (1 + r340DivGapPct/100)).toFixed(8)
      };
    }
  }

  // ── 4. BREAK-EVEN ─────────────────────────────────────────────────────────
  // R283: BE küçük kârı boğmasın. Runner'da BE daha geç; normal/taktikte de sadece
  // yeterli yol alındıysa veya devam gücü zayıfladıysa çalışır.
  // R344: RUNNER'da BE GECİKTİRİLİR — 03.07 THE/MAGMA dersi: +%2.5 pop'ta BE'ye alınan runner,
  // normal geri çekilmede girişten atıldı (hedef +%21'di). RUNNER'da BE ancak SL mesafesinin
  // %75'i kadar yol alınınca kurulur; o zamana dek pozisyon AI'ın SL'iyle yaşar (runner'ın bedeli budur).
  const r344SlPctVal = Number(state.slPct || slPct || 1.7);
  // R370 BE FIX (kullanıcı şikayeti: BEL %1.22'de BE oldu, hedef %18'di — kâr erken kesildi).
  // RUNNER'da BE ÇOK daha geç kurulmalı ki kâr taşınabilsin. Eşik: SL mesafesinin %75'i AMA min %2.0
  // (eskiden %0.85'ti — çok erken). Böylece taze impuls koşarken BE erken devreye girip kesmez.
  const r283DynamicBE = r282RunnerMode
    ? Math.max(r192BreakEvenAt * r339GeoScale, 2.0 * r339GeoScale, (r339AiManaged ? r344SlPctVal * 0.75 : 0))
    : ((r282ProtectMode ? Math.max(r192BreakEvenAt, 0.55) : Math.max(r192BreakEvenAt, 0.65)) * r339GeoScale);  // R339: geometri ölçeği
  // R370: RUNNER'da 'devam gücü zayıf' erken BE tetiğini KALDIR — RUNNER zaten kârı koşturmak için var,
  // erken BE onu öldürür. RUNNER'da BE sadece eşiğe ulaşınca kurulur, 'devam gücü' bahanesiyle erken değil.
  const r283BEAllowed = r282RunnerMode
    ? !!(realProfitPct >= r283DynamicBE)  // RUNNER: sadece eşik (min %2.0), erken tetik yok
    : !!(realProfitPct >= r283DynamicBE && (!r91Brain.devamGucu || openMinutes >= Number(r282Plan.minHoldWinMin||4) || pnlPct >= Number(r282Plan.earlyBEroi||11)));
  if (!action && !state.breakEvenSet && r283BEAllowed) {
    action = {
      type:'BREAK_EVEN',
      reason:`R283 BE: fiyat %${realProfitPct.toFixed(2)} hareket etti; eşik %${r283DynamicBE.toFixed(2)}. Devam gücü ${r91Brain.devamGucu?'var ama süre/ROI yeterli':'zayıf'} → SL giriş + fee buffer %${beFeeSafePct.toFixed(2)}`,
      urgency:'LOW',
      newSL: +(entryPrice * (isLong ? (1 + beFeeSafePct/100) : (1 - beFeeSafePct/100))).toFixed(8),
      stateUpdates:{ breakEvenSet:true, beFeeSafePct, r283DynamicBE }
    };
    logAuto(`${sym} R283 Break-even: Gerçek hareket %${realProfitPct.toFixed(2)}, Kaldıraçlı PnL: %${pnlPct.toFixed(1)}, Lev:${leverage}x, eşik:${r283DynamicBE.toFixed(2)}`);
  }

  // ── 4b. KÂR TAŞIMA ADIMLARI ─────────────────────────────────────────────────
  if (!action && state.breakEvenSet) {
    let stepSL = null, stepReason = null, stepUpdate = null;
    // R310H: AI "RUNNER" dediyse (güçlü setup), kâr taşıma eşiklerini İLERİ it — kâr daha çok koşsun, geç kilitle.
    const _runnerMult = state.aiRunner ? 1.8 : 1.0;  // RUNNER: %1.5/3/5.5 → %2.7/5.4/9.9 (kâr çok koşar)
    const kT1 = karTasima1 * _runnerMult * r339GeoScale, kT2 = karTasima2 * _runnerMult * r339GeoScale, kT3 = karTasima3 * _runnerMult * r339GeoScale;  // R339 geometri ölçeği
    if (realProfitPct >= kT3 && !state.step3Set) {
      stepSL = isLong ? +(entryPrice*(1+0.015*r339GeoScale)).toFixed(8) : +(entryPrice*(1-0.015*r339GeoScale)).toFixed(8);
      stepReason = `Kâr taşıma 3${state.aiRunner?' (RUNNER)':''}: %${realProfitPct.toFixed(2)} → SL kâr +%1.5`;
      stepUpdate = { step3Set:true };
    } else if (realProfitPct >= kT2 && !state.step2Set) {
      stepSL = isLong ? +(entryPrice*(1+0.008*r339GeoScale)).toFixed(8) : +(entryPrice*(1-0.008*r339GeoScale)).toFixed(8);
      stepReason = `Kâr taşıma 2${state.aiRunner?' (RUNNER)':''}: %${realProfitPct.toFixed(2)} → SL kâr +%0.8`;
      stepUpdate = { step2Set:true };
    } else if (realProfitPct >= kT1 && !state.step1Set) {
      // R136: Kâr taşıma 1, erken çıkış gibi davranmasın.
      // Akış hâlâ pozisyon yönündeyse ve ters çıkış puanı düşükse ilk taşıma için
      // %1.60'a kadar veya en fazla 6 yönetim döngüsü nefes ver. BE emniyeti zaten aktif.
      const r136KarBreathOk = !!(r91Brain?.devamGucu && Number(r91Brain?.exitScore||0) < 2.5 && realProfitPct < 1.60 && Number(state.r136KarTasimaBreath||0) < 6);
      if (r136KarBreathOk) {
        state.r136KarTasimaBreath = Number(state.r136KarTasimaBreath||0) + 1;
        trailingState.set(sym, state);
        logAuto(`⏳ ${sym} R136 kâr taşıma nefesi: step1 bekletildi [${state.r136KarTasimaBreath}/6] · kâr %${realProfitPct.toFixed(2)} · trend/flow devam`);
      } else {
        stepSL = isLong ? +(entryPrice*(1+0.003*r339GeoScale)).toFixed(8) : +(entryPrice*(1-0.003*r339GeoScale)).toFixed(8);
        stepReason = `Kâr taşıma 1: %${realProfitPct.toFixed(2)} → SL giriş üstü +%0.3`;
        stepUpdate = { step1Set:true };
      }
    }
    if (stepSL) {
      const better = isLong ? (!state.currentSL||stepSL>state.currentSL) : (!state.currentSL||stepSL<state.currentSL);
      if (better) action = { type:'KAR_TASIMA', reason:stepReason, urgency:'LOW', newSL:stepSL, stateUpdates:stepUpdate };
    }
  }

  // ── 5. TRAILING SL (adım bazlı) + R39 trend sağlık bekletmesi ───────────
  if (!action && state.breakEvenSet) {
    const oldHW = state.highWater || curPrice;
    const newHW = isLong
      ? Math.max(oldHW, curPrice)
      : Math.min(oldHW, curPrice);
    // Min adım: fiyat trailStep% kadar ilerlemiş olmalı (sürekli güncellemeyi önler)
    const movedPct = oldHW
      ? Math.abs(newHW-oldHW)/oldHW*100 : 0;
    if (movedPct >= trailStep) {
      const trendHealthy = isCvdTrendHealthyForSide();
      const pullbackPct = calcPullbackFromHighWaterPct(newHW);
      // R339: AI işleminde trailing mesafesi işlemin SL geometrisine göre genişler (5m panel değeri 15m runner'ı boğmasın)
      let trailPctEff = Math.min(trailPct * r339GeoScale, Math.max(trailPct, Number(state.slPct || slPct) * 1.1));
      // R430: RUNNER'da trailing mesafesi geniş nefes alır (min %2.5) — gainer coinlerde %2-3'lük
      // sağlıklı konsolidasyon trailing'i tetikleyip +%250 tipi koşuları erken bitiriyordu.
      if (state.aiRunner) trailPctEff = Math.max(trailPctEff * 1.8, 2.5);
      const smallPullback = pullbackPct < (trailPctEff * 0.4);
      state.trendHoldCount = Number(state.trendHoldCount || 0);
      const r430HoldMax = state.aiRunner ? 8 : 3;  // R430: runner trend beklemesi 3→8 döngü

      // Trend hâlâ sağlıklıysa ve geri çekilme küçükse SL'yi hemen sıkıştırma.
      // Bu, BILL gibi devam edebilecek top mover trendlerinde BE/trailing avına düşmeyi azaltır.
      if (trendHealthy && smallPullback && state.trendHoldCount < r430HoldMax) {
        state.highWater = newHW;
        state.trendHoldCount += 1;
        stampManager('TREND_HOLD', `Trend devam görünüyor — trail bekleniyor [${state.trendHoldCount}/${r430HoldMax}] • HW=$${Number(newHW).toFixed(6)} • pullback %${pullbackPct.toFixed(2)}`, 'LOW');
        logAuto(`⏳ ${sym} Trend devam görünüyor — trail bekleniyor [${state.trendHoldCount}/${r430HoldMax}]`);
        return null;
      }

      let newSL = isLong
        ? +(newHW*(1-trailPctEff/100)).toFixed(8)
        : +(newHW*(1+trailPctEff/100)).toFixed(8);
      // R434 MEGA-KOSU: runner'da yapi-bazli trailing — sabit %2.5 yerine son 3 KAPANMIS 15m
      // mumun dibinin %0.4 alti (emniyet tavani: zirveden max %7 sarkma). Sim kaniti (5 coin-gun):
      // sabit trailing 50$->116$, yapi trailing + yeniden giris 50$->157$. 'better' kontrolu SL'i
      // asla gevsetmez — yapi dibi mevcut SL'in altindaysa guncelleme olmaz, pozisyon nefes alir.
      if (state.aiRunner && isLong) {
        try {
          const r434K = await cached(`k15m_${sym}`, 90*1000, ()=>bPub('/fapi/v1/klines',`symbol=${sym}&interval=15m&limit=200`));
          const r434Closed = Array.isArray(r434K) ? r434K.slice(0, -1) : [];
          if (r434Closed.length >= 3) {
            const r434Dip = Math.min(...r434Closed.slice(-3).map(k => Number(k[3]))) * 0.996;
            // R436: chandelier ATR-uyarli — sabit %7 dev kosularda erken atiyordu (TAIKO dersi:
            // +%496 gununde %7 tavan normal geri cekilmede stopladi). Sarkma = ATR15m*1.6, %7-14 bandi.
            let r436Atr = 3.0;
            try {
              const kk = r434Closed.slice(-15);
              let tr = 0;
              for (let z = 1; z < kk.length; z++) {
                const hh = Number(kk[z][2]), ll = Number(kk[z][3]), pc = Number(kk[z-1][4]);
                tr += Math.max(hh - ll, Math.abs(hh - pc), Math.abs(ll - pc)) / Number(kk[z][4]);
              }
              r436Atr = tr / Math.max(1, kk.length - 1) * 100;
            } catch(_e) {}
            const r436Sarkma = Math.max(0.07, Math.min(0.14, r436Atr * 0.016));
            const r434Chand = newHW * (1 - r436Sarkma);
            newSL = +Math.max(Math.min(r434Dip, newHW * 0.999), r434Chand).toFixed(8);
          }
        } catch(_e) {}
      }
      const better = isLong
        ? (!state.currentSL||newSL>state.currentSL)
        : (!state.currentSL||newSL<state.currentSL);
      if (better) action = {
        type:'TRAIL_SL',
        reason:`Trailing (%${trailStep} adım): HW=$${Number(newHW).toFixed(6)} → SL=$${newSL}`,
        urgency:'LOW', newSL,
        stateUpdates:{ highWater:newHW, trendHoldCount:0 }
      };
    }
  }

  // ── 6. TP GENİŞLETME — Momentum devam ediyorsa TP'yi yukarı taşı ────────
  // R39: TP genişletme artık hedefin %70'ini değil %50'sini geçince değerlendirir.
  // R430 (kullanıcı dersi 20.07: +%250 koşu TP'de kesildi, 5x %1250 ROI kaçtı): RUNNER'da TP
  // genişletme TEK SEFERLİK DEĞİL — trend sağlıklı kaldıkça TEKRAR TEKRAR ileri taşınır (max 10 kez).
  // Böylece Binance TP emri sağlıklı bir koşuyu asla kapatamaz; koşuyu ancak yapı bozulması /
  // kâr-koruma racheti bitirir. NORMAL işlemde eski tek seferlik davranış korunur (vur-kaç karakteri).
  const tpRealTarget = tpPct; // Kaldıraçsız hedef %
  const r430IsRunner = !!state.aiRunner;
  const r430ExtCount = Number(state.tpExtendCount || 0);
  const r430CurTargetPct = (Number(state.targetTP) > 0)
    ? Math.abs(Number(state.targetTP) - entryPrice) / entryPrice * 100 : tpRealTarget;
  const r430CanExtend = r430IsRunner ? (r430ExtCount < 10) : !state.tpExtended;
  const r430NearTarget = r430IsRunner
    ? (realProfitPct > r430CurTargetPct * 0.70)   // hedefin %70'ine gelindi → hedefi ileri taşımayı düşün
    // ═══ V625 ═══ esik PANEL tpPct'sine gore degil GERCEK emir TP'sine gore.
    // Panel %10 iken esik %5 fiyat = %35 ROI olur; olculen ort. zirve %11 ROI —
    // yani "TP'ye yaklasinca" hic tetiklenmiyordu. Gercek TP ~%5 -> esik ~%17 ROI.
    : (realProfitPct > (V625_KAR_TASIMA ? r430CurTargetPct : tpRealTarget) * 0.5);
  if (!action && r430CanExtend && r430NearTarget) {
    const cvd = getCVD(sym);
    const momentumStrong = isLong
      ? cvd?.momentum === 'ACCELERATING_BULL' || cvd?.ratio > 65
      : cvd?.momentum === 'ACCELERATING_BEAR' || cvd?.ratio < 35;
    // R430: runner'da momentum şartı esnetilir — devam gücü var ve çıkış puanı düşükse de taşı
    // (CVD anlık nötrken bile sağlıklı trend TP'ye çarparak kesilmesin).
    const r430RunnerTrendOk = r430IsRunner && (momentumStrong || (r91Brain?.devamGucu && Number(r91Brain?.exitScore||0) < 3.5));
    if (momentumStrong || r430RunnerTrendOk) {
      const extendedTP = r430IsRunner
        ? (isLong  // runner: TP her zaman mevcut fiyatın bir tam hedef adımı ötesinde tutulur
          ? +(curPrice * (1 + Math.max(tpPct, 2.0) / 100)).toFixed(8)
          : +(curPrice * (1 - Math.max(tpPct, 2.0) / 100)).toFixed(8))
        : (isLong
          ? +(entryPrice * (1 + (tpPct * 1.5) / 100)).toFixed(8)
          : +(entryPrice * (1 - (tpPct * 1.5) / 100)).toFixed(8));
      const fallbackSL = state.currentSL || (isLong
        ? +(entryPrice * (1 - slPct / 100)).toFixed(8)
        : +(entryPrice * (1 + slPct / 100)).toFixed(8));
      const betterTP = isLong ? extendedTP > Number(state.targetTP || 0) : (!state.targetTP || extendedTP < Number(state.targetTP));
      if (betterTP) {
        action = { type:'EXTEND_TP', urgency:'LOW', newSL:fallbackSL, newTP:extendedTP,
          reason: r430IsRunner
            ? `R430 RUNNER TP taşıma [${r430ExtCount+1}/10]: trend sağlıklı, TP mevcut fiyatın %${Math.max(tpPct,2.0).toFixed(1)} ötesine itildi — koşu TP'ye çarpıp kesilmez`
            : `Momentum güçlü — TP gerçek Binance emrine genişletiliyor: %${(tpPct*1.5).toFixed(1)}`,
          stateUpdates:{ tpExtended:true, tpExtendCount:r430ExtCount+1 } };
      }
    }
  }

  // ── AKSİYON UYGULA ────────────────────────────────────────────────────────
  if (!action) { stampManager('İZLEME', null, 'LOW'); return null; }

  stampManager(action.type, action.reason, action.urgency||'LOW');
  logAuto(`[${sym}] ${action.type} (${action.urgency}): ${action.reason}`);

  // ══ V4.7.4.19-AC1: KOK NEDEN — J2 (min tutus) ve Y (mum kapanisi) BURAYA BAGLI DEGILDI ══
  // 06.08 olcumu: minHoldBlocks=0 · exitCandleAllowed=0 · exitCandleDeferred=0 · nonBacktestExits=5
  // v592MinHoldGuard TEK bir yerden cagriliyordu: emergencyCloseIfBracketMissing.
  // Yoneticinin ASIL cikis yolu (asagidaki blok) hic guard gormuyordu.
  // AKE 60.847 ms'de kapandi — J2 esigi 60.000; 847 ms fark tesadufi degildi.
  // Artik yoneticinin TAKDIR YETKISINDEKI her cikisi once bu kapidan gecer.
  // ══ V4.7.4.43-BH1: OPERATOR ONCELIGI ════════════════════════════════
  // `&&` , `||` dan SIKI baglar. Yazilan sart soyle ayrisiyordu:
  //   (EXACT && type==='EMERGENCY_EXIT') || type==='MAX_SURE_KAPAT' || ...
  // Yani EXACT bayragi YALNIZ ilk sarti koruyordu; diger 13 cikis tipi
  // exact moddan BAGIMSIZ guard blogua giriyordu.
  // EXACT=1 iken zararsiz (hepsi zaten girmeli). EXACT=0 iken EMERGENCY_EXIT
  // guard'i ATLIYOR, digerleri gereksiz giriyor.
  // ChatGPT denetiminde bildirilmisti; ben ucunu dogrulayip dorduncuyu
  // KONTROL ETMEDIM ve "3 iddia 3'u dogru" dedim. Bu benim atlamam.
  if (V592_EXACT_BACKTEST_AUTHORITY && (action.type === 'EMERGENCY_EXIT' || action.type === 'MAX_SURE_KAPAT' || action.type === 'R97_VUR_KAC_KAPAT' || action.type === 'R97_FIKIR_BOZULDU_KAPAT' || action.type === 'R144_HASAR_KONTROL_KAPAT' || action.type === 'R147_TERS_AKIS_HASAR_KAPAT' || action.type === 'R281_PROTECT_HASAR_KAPAT' || action.type === 'R282_ROI_HASAR_KAPAT' || action.type === 'R282_FIKIR_BOZULDU_KAPAT' || action.type === 'R282_WINNER_SCRATCH_KAPAT' || action.type === 'R282_PROFIT_TAKE_KAPAT' || action.type === 'R149_PROFIT_GIVEBACK_KAPAT' || action.type === 'R165_WINNER_NEVER_LOSER_KAPAT' || action.type === 'R486_AUTONOMOUS_PROFIT_EXIT')) {
    // V4.7.4.20-AG2: once TIP kontrolu — backtestte karsiligi olmayan cikis GOLGEYE.
    // V4.7.4.21-AH2: koruma YOKSA golge uygulanmaz — backtestte korumasiz pozisyon yok.
    const _pp = v592PositionProtection(sym);
    // ══ V4.7.4.43-BH2: SONDA KORUMASIZ ISTISNASINI KULLANAMAZ ═════════
    // AH istisnasi "backtestte korumasiz pozisyon yok" diye kondu; amaci
    // stratejinin korumasiz kalmis pozisyonunu kilitlememekti.
    // SONDA pozisyonlari TASARIM GEREGI korumasiz (5 dk zamanli cikis,
    // SL/TP yok). Bu yuzden istisnayi otomatik tetikliyor ve cikis beyaz
    // listesini BYPASS ediyorlardi. 11.08'de R282_ROI_HASAR_KAPAT 3 kez
    // BU YOLDAN calisti — backtestte karsiligi olmayan bir cikis.
    // Sonda zaten kendi zamanlayicisiyla kapaniyor; yoneticinin ona
    // dokunmasina gerek yok.
    const _isProbe = (typeof v592IsProbeSymbol==='function') && v592IsProbeSymbol(sym);
    if (_isProbe) {
      v592ParityStats.probeManagerExitBlocked = (v592ParityStats.probeManagerExitBlocked||0)+1;
      try{r501OrderLifeMark(sym,'PROBE_MANAGER_EXIT_BLOCKED',
        {actionType:action.type,note:'sonda pozisyonu; yonetici cikisi uygulanmaz'});}catch(_){}
      return null;
    }
    const _unprotected = (_pp.protected === false);
    if (_unprotected) {
      v592ParityStats.unprotectedExitAllowed++;
      try{r501OrderLifeMark(sym,'UNPROTECTED_EXIT_ALLOWED',{actionType:action.type,
        hasSL:_pp.hasSL,hasTP:_pp.hasTP,verified:_pp.verified,
        note:'backtestte korumasiz pozisyon yok; cikis golgeye alinmadi'});}catch(_){}
      logAuto(`[${sym}] ${action.type} SERBEST — pozisyon KORUMASIZ (SL:${_pp.hasSL?'var':'YOK'} TP:${_pp.hasTP?'var':'YOK'})`);
    }
    if (!_unprotected && !v592ExitTypeAllowed(action.type)) {
      v592ParityStats.exitTypeShadowed++;
      v592ShadowNonBacktestExit(sym, `EXIT_TYPE_${action.type}`, {
        actionType:action.type, urgency:action.urgency||null,
        reason:String(action.reason||'').slice(0,200),
        allowed:V592_BACKTEST_EXIT_TYPES});
      logAuto(`[${sym}] ${action.type} GOLGEYE ALINDI — backtestte karsiligi yok; SL/TP bekleniyor`);
      stampManager('IZLEME', `${action.type} golge: backtest cikisi degil`, 'LOW');
      return null;
    }
    if (!_unprotected) v592ParityStats.exitTypeAllowed++;
    const _mg = _unprotected ? {blocked:false} : v592MinHoldGuard(sym, `MANAGER_${action.type}`);
    if (_mg.blocked) {
      v592ParityStats.managerExitDeferred++;
      const _nd = _mg.candleDeferred ? `mum kapanisi ${Math.round((_mg.waitMs||0)/1000)}sn`
                                     : `min tutus ${Math.round((_mg.ageMs||0)/1000)}/${Math.round(V592_MIN_HOLD_MS/1000)}sn`;
      logAuto(`[${sym}] ${action.type} ERTELENDI — backtest sozlesmesi: ${_nd}`);
      stampManager('BEKLET', `${action.type} ertelendi: ${_nd}`, 'LOW');
      return null;
    }
    v592ParityStats.managerExitGuarded++;
  }
  if (action.type === 'EMERGENCY_EXIT' || action.type === 'MAX_SURE_KAPAT' || action.type === 'R97_VUR_KAC_KAPAT' || action.type === 'R97_FIKIR_BOZULDU_KAPAT' || action.type === 'R144_HASAR_KONTROL_KAPAT' || action.type === 'R147_TERS_AKIS_HASAR_KAPAT' || action.type === 'R281_PROTECT_HASAR_KAPAT' || action.type === 'R282_ROI_HASAR_KAPAT' || action.type === 'R282_FIKIR_BOZULDU_KAPAT' || action.type === 'R282_WINNER_SCRATCH_KAPAT' || action.type === 'R282_PROFIT_TAKE_KAPAT' || action.type === 'R149_PROFIT_GIVEBACK_KAPAT' || action.type === 'R165_WINNER_NEVER_LOSER_KAPAT' || action.type === 'R486_AUTONOMOUS_PROFIT_EXIT') {
    // Hem normal hem algo emirleri iptal et (2025-12-09 sonrası)
    try {
      await cancelAlgoOrders(apiKey, apiSecret, sym, true);
      const qty = Math.abs(parseFloat(pos.positionAmt || 0)).toString();
      const closeClientOrderId=lazarusCloseClientOrderId(sym,String(action.type||'MANAGER_EXIT'),'MANAGER');
      try{r501OrderLifeMark(sym,'REDUCE_ONLY_CLOSE_SENT',{reason:String(action.type||'MANAGER_EXIT'),clientOrderId:closeClientOrderId,quantity:qty,side:isLong?'SELL':'BUY',source:'POSITION_MANAGER'});}catch(_){}
      // MARKET emri eski endpoint'te çalışmaya devam eder
      const r = await bReq(apiKey, apiSecret, 'POST', '/fapi/v1/order', {
        symbol:sym, side:isLong?'SELL':'BUY',
        type:'MARKET', quantity:qty,
        reduceOnly:'true', positionSide:'BOTH', newClientOrderId:closeClientOrderId, __emergency:true
      });
      try{r501OrderLifeMark(sym,'REDUCE_ONLY_CLOSE_ACK',{reason:String(action.type||'MANAGER_EXIT'),clientOrderId:closeClientOrderId,orderId:r?.orderId||null,exchangeStatus:r?.status||null,source:'POSITION_MANAGER'});}catch(_){}
      logAuto(`✅ ${sym} ${action.type==='R97_VUR_KAC_KAPAT'?'TEK BEYİN ÇIKIŞI':action.type==='R97_FIKIR_BOZULDU_KAPAT'?'TEK BEYİN FİKİR BOZULDU':action.type==='R147_TERS_AKIS_HASAR_KAPAT'?'R147 TERS AKIŞ ÇIKIŞI':action.type==='R281_PROTECT_HASAR_KAPAT'?'R281 PROTECT ÇIKIŞI':String(action.type||'').startsWith('R282_')?'R282 TECRÜBELİ TRADER ÇIKIŞI':action.type==='R149_PROFIT_GIVEBACK_KAPAT'?'R149 KÂR KORUMA ÇIKIŞI':action.type==='R165_WINNER_NEVER_LOSER_KAPAT'?'R165 KÂR ZARARA DÖNMESİN ÇIKIŞI':action.type==='R486_AUTONOMOUS_PROFIT_EXIT'?'R486 OTONOM KÂR HASADI':'ACİL ÇIKIŞ'}: PnL %${pnlPct.toFixed(2)} — ${r.orderId}`);
      // V4.7.4.28-AS2: defter kaydi olmadan trailingState silinmiyor.
      await v592FinalizeClose(sym,(()=>{try{return trailingState.get(sym)||null;}catch(_){return null;}})(),
        {code:String(action?.type||'MANAGER_EXIT'),label:String(action?.reason||'Yonetici cikisi'),
         emoji:'🚪',closePrice:null,realizedPnl:null},String(action?.type||'MANAGER_EXIT'));
      return { action:'CLOSED', pnl:pnlPct, reason:action.reason };
    } catch(e) {
      logAuto(`❌ ${sym} Acil çıkış hatası: ${e.message}`);
    }
  }

  if (action.type === 'BREAK_EVEN' || action.type === 'TRAIL_SL' || action.type === 'TIGHTEN_SL'
      || action.type === 'KAR_TASIMA' || action.type === 'R97_KAR_KILIDI' || action.type === 'R149_ROI_VAULT_LOCK' || action.type === 'R165_KAR_KILIDI' || action.type === 'R486_HARVEST_LOCK') {
    const newSL = action.newSL;
    if (!newSL) return null;
    // ═══ V625 ═══ KILIT ve TASIMA AYRI ANAHTARLAR.
    //   V607_KAR_KILIDI -> merdiven KILITLERI (sabit kademeli SL sicramalari)
    //   V625_KAR_TASIMA -> BE + trailing + kar tasima (zirveyi takip eden SL)
    const _v625Kilitler = new Set(['R97_KAR_KILIDI','R149_ROI_VAULT_LOCK','R165_KAR_KILIDI','R486_HARVEST_LOCK']);
    const _v625Tasimalar = new Set(['BREAK_EVEN','TRAIL_SL','KAR_TASIMA']);
    const profitRewriteTypes = new Set([..._v625Tasimalar, ..._v625Kilitler]);
    const _v625Engelli = _v625Kilitler.has(action.type) ? !_v607KarKilidi
                       : _v625Tasimalar.has(action.type) ? !V625_KAR_TASIMA
                       : false;
    if (_v625Engelli && profitRewriteTypes.has(action.type)) {
      try{r501OrderLifeMark(sym,'PROFIT_LOCK_DISABLED_V607',{actionType:action.type,requestedSL:Number(newSL),currentSL:Number(state.currentSL||0)||null});}catch(_){ }
      stampManager('İZLEME', `${action.type} uygulanmadı: V607 kâr kilidi kapalı`, 'LOW');
      return null;
    }
    // İlk SL/TP kurulumu bu kapının dışındadır. Yalnız manager'ın sonradan
    // bracket iptal edip yeniden yazması ilk kapalı 1m dolmadan engellenir.
    const rewriteOpenedAt = Number(state.openedAt||state.openTs||0);
    const rewriteAgeMs = rewriteOpenedAt > 0 ? Date.now()-rewriteOpenedAt : null;
    if (V592_MIN_HOLD_MS > 0 && rewriteAgeMs !== null && rewriteAgeMs < V592_MIN_HOLD_MS) {
      try{r501OrderLifeMark(sym,'PROTECTION_REWRITE_MIN_HOLD_BLOCKED',{actionType:action.type,requestedSL:Number(newSL),ageMs:rewriteAgeMs,minHoldMs:V592_MIN_HOLD_MS,currentSL:Number(state.currentSL||0)||null});}catch(_){ }
      logAuto(`🛡️ ${sym} ${action.type} SL değişimi ertelendi — ilk ${Math.ceil(V592_MIN_HOLD_MS/1000)}sn mevcut SL/TP korunur (${Math.floor(rewriteAgeMs/1000)}sn)`);
      stampManager('BEKLET', `${action.type} ertelendi: ilk koruma ${Math.ceil(V592_MIN_HOLD_MS/1000)}sn yeniden yazılmaz`, 'LOW');
      return null;
    }
    const upd = await updateStopLossWithProofJS(apiKey, apiSecret, pos, newSL, action.type);
    if (upd.ok) {
      Object.assign(state, action.stateUpdates || {});
      if (action.type === 'BREAK_EVEN') state.breakEvenInstalled = true;
      state.currentSL = upd.safeSL;
      state.targetTP = upd.tpPrice;
      state.sltpVerified = true;
      trailingState.set(sym, state);
      logAuto(`✅ ${sym} ${action.type} uygulandı: SL ${upd.safeSL} / TP ${upd.tpPrice}`);
    } else {
      // Çalışan python çekirdeği gibi: doğrulanmadıysa yerel state'i başarılı sayma.
      if (!upd.keptExisting) state.sltpVerified = false;
      trailingState.set(sym, state);
      return null;
    }
  }

  if (action.type === 'EXTEND_TP') {
    const rewriteOpenedAt = Number(state.openedAt||state.openTs||0);
    const rewriteAgeMs = rewriteOpenedAt > 0 ? Date.now()-rewriteOpenedAt : null;
    if (V592_MIN_HOLD_MS > 0 && rewriteAgeMs !== null && rewriteAgeMs < V592_MIN_HOLD_MS) {
      try{r501OrderLifeMark(sym,'PROTECTION_REWRITE_MIN_HOLD_BLOCKED',{actionType:action.type,requestedSL:Number(action.newSL),requestedTP:Number(action.newTP),ageMs:rewriteAgeMs,minHoldMs:V592_MIN_HOLD_MS});}catch(_){ }
      stampManager('BEKLET', `EXTEND_TP ertelendi: ilk koruma ${Math.ceil(V592_MIN_HOLD_MS/1000)}sn yeniden yazılmaz`, 'LOW');
      return null;
    }
    const upd = await updateBracketWithProofJS(apiKey, apiSecret, pos, action.newSL, action.newTP, action.type);
    if (upd.ok) {
      Object.assign(state, action.stateUpdates || {});
      state.currentSL = upd.safeSL;
      state.targetTP = upd.tpPrice;
      state.sltpVerified = true;
      trailingState.set(sym, state);
      logAuto(`📈 ${sym} TP genişletme gerçek Binance emrine yazıldı: TP ${upd.tpPrice}`);
    }
  }

  // ═══ V635 ═══ KAR TAKIBI RONTGENI (yalnizca gozlem — hicbir davranisi degistirmez)
  // Olculdu 26.08: backtestin karinin %97'si DYNAMIC_STOP'tan (trailing) geliyor
  // (+498,3R / +513,8R). Canlida ise tek bir PROTECTION_REWRITE kaydi YOK.
  // "Hic atesnlenmedi" ile "henuz firsat olmadi" ayrimini tahminle degil KAYITLA yapalim:
  // her pozisyon icin zincirin nerede durdugu 60sn'de bir, degisince hemen yazilir.
  try {
    const _v635St = trailingState.get(sym) || {};
    const _v635Kar = Number(realProfitPct);
    const _v635Yas = Number(_v635St.openedAt || _v635St.openTs || 0) > 0
      ? Date.now() - Number(_v635St.openedAt || _v635St.openTs) : null;
    const _v635Nerede =
      action ? `AKSIYON:${action.type}`
      : !V625_KAR_TASIMA ? "KAPALI: V625_KAR_TASIMA=0"
      : (_v635Yas !== null && _v635Yas < V592_MIN_HOLD_MS) ? `MIN_HOLD: ${Math.floor(_v635Yas/1000)}sn/${Math.floor(V592_MIN_HOLD_MS/1000)}sn`
      : !_v635St.breakEvenSet ? `BE_BEKLIYOR: kar %${_v635Kar.toFixed(2)} / esik %${Number(breakEvenAt||0).toFixed(2)}`
      : 'TRAIL_AKTIF: adim/trend sarti bekleniyor';
    const _v635Onceki = _v635St._v635Son || '';
    const _v635Gecen = Date.now() - Number(_v635St._v635SonTs || 0);
    if (_v635Nerede !== _v635Onceki || _v635Gecen > 60000) {
      _v635St._v635Son = _v635Nerede; _v635St._v635SonTs = Date.now();
      trailingState.set(sym, _v635St);
      logAuto(`🔍 ${sym} KAR TAKIBI: ${_v635Nerede} · kar %${_v635Kar.toFixed(2)} · HW ${Number(_v635St.highWater||0)>0?Number(_v635St.highWater).toFixed(6):'—'} · SL ${Number(_v635St.currentSL||0)>0?Number(_v635St.currentSL).toFixed(6):'kurulmadi'}`);
      try{r501OrderLifeMark(sym,'V635_KAR_TAKIBI',{asama:_v635Nerede,karPct:+_v635Kar.toFixed(3),breakEvenSet:!!_v635St.breakEvenSet,highWater:Number(_v635St.highWater)||null,currentSL:Number(_v635St.currentSL)||null});}catch(_){}
    }
  } catch(_v635e) {}

  return action;
}

// Tüm pozisyonları yönet
async function checkTrailingSL(apiKey, apiSecret, positions) {
  for (const pos of positions) {
    await managePosition(apiKey, apiSecret, pos).catch(e =>
      logAuto(`${pos.symbol} yönetim hatası: ${e.message}`)
    );
  }
}

function mapRiskRowsToManagerPositions(rows=[]) {
  return (Array.isArray(rows) ? rows : [])
    .filter(p => Math.abs(parseFloat(p.positionAmt || 0)) > 0)
    .map(p => {
      const amt = parseFloat(p.positionAmt || 0);
      const ep  = parseFloat(p.entryPrice || 0);
      const mp  = positionMarkPrice(p);
      const lev = parseInt(p.leverage) || 1;
      const side = amt > 0 ? 'LONG' : 'SHORT';
      if(!(ep>0&&mp>0)){
        try{pushCritical('POSITION_MARK_PRICE_MISSING',`${p.symbol||'?'} yöneticiye verilmedi; geçerli entry/mark fiyatı yok`,{symbol:p.symbol,entryPrice:ep,rawMarkPrice:p.markPrice??null,unrealizedProfit:p.unRealizedProfit??p.unrealizedProfit??null},'WARNING');}catch(_){}
        return null;
      }
      const pnlPct = ep > 0 ? ((mp - ep) / ep * 100 * lev * (side === 'SHORT' ? -1 : 1)) : 0;
      return {
        symbol:p.symbol, side, positionAmt:Math.abs(amt), entryPrice:ep, markPrice:mp,
        unrealizedProfit:parseFloat(p.unRealizedProfit ?? p.unrealizedProfit ?? 0),
        leverage:lev, pnlPct
      };
    }).filter(Boolean);
}

let fastManagerRunning = false;
let fastManagerTimer = null;
let r395BosTikAtla = false; // R395: pozisyon yokken her 2. positionRisk tiki atlanır (429 diyeti)
async function fastManageOpenPositions() {
  if (fastManagerRunning || !autoConfig?.enabled || !autoConfig?.apiKey || !autoConfig?.apiSecret) return;
  if (isPositionRiskCooldownActive()) return;
  // R395 WEIGHT DİYETİ: son bakışta pozisyon 0 ise bir tik atla (kadans 10sn→20sn). Pozisyon
  // varken kadans 10sn AYNEN kalır. 10.07 429 fırtınası: mum kapanış saniyelerinde tarama+koklama+
  // yönetici üst üste binip merkezi freni tetikliyordu; frende emir yolu VE yönetici kör kalıyordu.
  if (r395BosTikAtla && Number(autoScanState?.livePositions || 0) === 0) { r395BosTikAtla = false; return; }
  fastManagerRunning = true;
  try {
    const rows = await getPositionRiskCached(autoConfig.apiKey, autoConfig.apiSecret);
    const mapped = mapRiskRowsToManagerPositions(rows);
    autoScanState.livePositions = mapped.length;
    v644SetPositionFocus(mapped.map(x=>x.symbol),'FAST_POSITION_MANAGER');
    r395BosTikAtla = mapped.length === 0; // boşsa sıradaki tik atlanır; pozisyon açılınca tam kadans
    if (mapped.length > 0) {
      await checkTrailingSL(autoConfig.apiKey, autoConfig.apiSecret, mapped);
    }
  } catch(e) {
    logAuto(`Hızlı pozisyon yöneticisi hata: ${String(e.message||e).slice(0,100)}`);
  } finally {
    fastManagerRunning = false;
  }
}

// ── KAPAT ─────────────────────────────────────────────────────────────────────
app.post('/api/close', async (req, res) => {
  const{symbol}=req.body;
  const{apiKey,apiSecret}=r486391BinanceCreds();
  if(!apiKey||!apiSecret||!symbol)return res.status(400).json({error:'Eksik parametre'});
  const sym=symbol.toUpperCase().includes('USDT')?symbol.toUpperCase():symbol.toUpperCase()+'USDT';
  try{
    const state=(()=>{try{return trailingState.get(sym)||lastKnownPositions?.[sym]||{};}catch(_){return {};}})();
    const close=await safeMarketClosePosition(apiKey,apiSecret,sym,{reason:'PANEL_API_CLOSE',guarded:true});
    if(!close.ok)throw new Error(close.error||'Panel kapatma başarısız');
    if(!close.alreadyClosed){
      await v592FinalizeClose(sym,state,{code:'PANEL_API_CLOSE',label:'Panel kapatma isteği',emoji:'🖐️',closePrice:null,realizedPnl:null},'PANEL_API_CLOSE');
    }
    res.json({ok:true,message:close.alreadyClosed?'Açık pozisyon yok':`${sym} kapatıldı`,orderId:close.order?.orderId||null,clientOrderId:close.clientOrderId||null,source:'PANEL_API_CLOSE'});
  }catch(e){res.status(400).json({error:e.message});}
});

// ── OTOMATİK İŞLEM MOTORU ────────────────────────────────────────────────────
// Kullanıcı ayarları:
// autoTrade: { enabled, apiKey, apiSecret, usdtAmount, leverage, marginType,
//   maxPositions, minScore, allowLong, allowShort,
//   trailingPct, breakEvenPct, symbols:[] }

let autoConfig = null;
// R486.3.9.1: Karne/ledger senkronu dashboard açılmadan da çalışır.
