// ═══ V6.4.4 — TEK ACIK POZISYON ODAĞI ═══════════════════════════════════════
// Pozisyon varken yeni aday arayan bütün yollar susar. Imzali pozisyon yöneticisi,
// SL/TP kurtarma ve kapanis senkronu çalışmaya devam eder. Böylece REST bütçesi ve
// karar motoru açık pozisyona ayrılır; kapanış gerçeği gelince tarama yeniden uyanır.
const V644_POSITION_FOCUS_ACTIVE = String(process.env.V644_POSITION_FOCUS_ACTIVE ?? '1') !== '0';
const v644PositionFocusState = {
  active:false, symbols:[], since:0, lastChangeAt:0, source:'BOOT',
  pauseCount:0, resumeCount:0, workerSkips:{}, resumeScheduledAt:0
};
let v644ResumeTimer=null;
function v644FocusSymbols(input=[]){
  const rows=Array.isArray(input)?input:[input];
  return [...new Set(rows.map(x=>normalizeSymbol(typeof x==='string'?x:(x?.symbol||''))).filter(Boolean))];
}
function v644PositionFocusActive(){ return !!(V644_POSITION_FOCUS_ACTIVE&&v644PositionFocusState.active); }
function v644ScheduleResume(source='POSITION_CLOSED'){
  if(v644ResumeTimer||!autoConfig?.enabled)return;
  const gap=Math.max(0,R150_MIN_SCAN_GAP_MS-(Date.now()-Number(r150LastScanBeginTs||0)));
  const waitMs=Math.max(1200,gap+500);
  v644PositionFocusState.resumeScheduledAt=Date.now()+waitMs;
  v644ResumeTimer=setTimeout(()=>{
    v644ResumeTimer=null;v644PositionFocusState.resumeScheduledAt=0;
    if(!autoConfig?.enabled||v644PositionFocusActive()||autoRunning)return;
    autoScanState.phase='POZİSYON_KAPANDI_TARAMA_YENİDEN';
    autoScanState.lastAction=`${source}: açık pozisyon kapandı, TOP24 + worker taraması yeniden başlıyor`;
    runAutoScan().catch(e=>logAuto(`V644 tarama yeniden başlatma hata: ${String(e?.message||e).slice(0,100)}`));
  },waitMs);
  try{v644ResumeTimer.unref?.();}catch(_){}
}
function v644SetPositionFocus(input=[],source='POSITION_TRUTH'){
  if(!V644_POSITION_FOCUS_ACTIVE)return false;
  const symbols=v644FocusSymbols(input),active=symbols.length>0,was=v644PositionFocusState.active;
  v644PositionFocusState.symbols=symbols;
  v644PositionFocusState.active=active;
  v644PositionFocusState.source=String(source||'POSITION_TRUTH');
  if(active&&!was){
    v644PositionFocusState.since=Date.now();v644PositionFocusState.lastChangeAt=Date.now();v644PositionFocusState.pauseCount++;
    if(v644ResumeTimer){clearTimeout(v644ResumeTimer);v644ResumeTimer=null;v644PositionFocusState.resumeScheduledAt=0;}
    autoScanState.phase='POZİSYON_ODAK';
    autoScanState.lastAction=`🎯 ${symbols.map(x=>x.replace('USDT','')).join(', ')} açık — yeni aday taraması/workerlar durdu; yalnız pozisyon yönetiliyor`;
    try{logAuto(autoScanState.lastAction);}catch(_){}
  }else if(!active&&was){
    v644PositionFocusState.since=0;v644PositionFocusState.lastChangeAt=Date.now();v644PositionFocusState.resumeCount++;
    autoScanState.livePositions=0;autoScanState.positionCount=0;
    v644ScheduleResume(source);
  }
  return active;
}
function v644ReleasePositionFocus(symbol,source='POSITION_CLOSED'){
  const S=normalizeSymbol(symbol),left=v644PositionFocusState.symbols.filter(x=>x!==S);
  return v644SetPositionFocus(left,source);
}
function v644PauseCandidateWorker(name='WORKER'){
  if(!v644PositionFocusActive())return false;
  const k=String(name||'WORKER').toUpperCase();
  v644PositionFocusState.workerSkips[k]=Number(v644PositionFocusState.workerSkips[k]||0)+1;
  return true;
}
function markAutoOpened(symbol, side) {
  autoPersistentStats.totalOpenedAllTime = Number(autoPersistentStats.totalOpenedAllTime || 0) + 1;
  autoPersistentStats.sessionOpened = Number(autoPersistentStats.sessionOpened || 0) + 1;
  autoPersistentStats.lastOpenedAt = Date.now();
  autoPersistentStats.lastOpenedSymbol = String(symbol || '').replace(/USDT$/,'');
  autoPersistentStats.lastOpenedSide = String(side || '').toUpperCase();
  saveAutoStats(autoPersistentStats);
  autoScanState.opened = Number(autoScanState.opened || 0) + 1;
  autoScanState.sessionOpened = autoPersistentStats.sessionOpened;
  autoScanState.totalOpenedAllTime = autoPersistentStats.totalOpenedAllTime;
  autoScanState.lastOpenedAt = autoPersistentStats.lastOpenedAt;
  autoScanState.lastOpenedSymbol = autoPersistentStats.lastOpenedSymbol;
  autoScanState.lastOpenedSide = autoPersistentStats.lastOpenedSide;
  // V680-F: acilan emir de beyne yazilir; boylece kart "gordu -> ne yapti" zincirini tamamlar.
  try { v679SonKarar(symbol, 'EMIR', `${String(side||'').toUpperCase()} emri acildi`); } catch(_v680e) {}
}

// R119: Auto panel tanı taşıyıcıları. R118 karar zinciri çalışsa bile markAutoSkip
// eski R97 satırıyla adayı güncellediğinde HTF/R115/R116/R117/R118 bilgileri panelden düşüyordu.
// Bu yardımcılar son kararın likidite haritası + mum playbook bilgisini sembol bazında korur.
const autoDiagBySymbol = new Map();
function r119FmtLevel(l) {
  try {
    if (!l) return '';
    const tf = String(l.label || l.tf || l.timeframe || '-');
    const px = Number(l.price || l.level || 0);
    const distRaw = l.dist ?? l.distancePct ?? l.distPct;
    const dist = Number.isFinite(Number(distRaw)) ? ` u:%${Number(distRaw).toFixed(2)}` : '';
    const strRaw = l.strength ?? l.guc ?? l.score;
    const str = Number.isFinite(Number(strRaw)) ? ` g:${Number(strRaw).toFixed(0)}` : '';
    return `${tf}${px ? ` ${px}` : ''}${dist}${str}`.trim();
  } catch { return ''; }
}
function r119BuildAutoDiag(dc={}) {
  try {
    const parts = [];
    if (dc.r110Phase) parts.push(`HTF faz:${dc.r110Phase}`);
    if (dc.r116HtfGuardBlock && !dc.r117HtfReverseOk) parts.push('HTF amir blok');
    if (dc.r117NearTrapHTF) parts.push(`ters-bölge ${r119FmtLevel(dc.r117TrapLevel)}`.trim());
    if (dc.r117HtfReverseOk) parts.push('ters-hedef HAZIR');
    if (dc.r118CandleOk) parts.push(`mum:${dc.r118CandleOzet||'OK'}`);
    else if (dc.r118CandleOzet) parts.push(`mum-izle:${dc.r118CandleOzet}`);
    if (dc.r111KoprusuOk) parts.push('sıkışma HAZIR');
    if (dc.r111SiksmaBreakout) parts.push(`patlama:${dc.r111SqueezeSkor||0}/4`);
    if (dc.r140Phase?.phase) parts.push(`R140 faz:${dc.r140Phase.phase}`);
    if (dc.r140OiVel?.fakePump) parts.push('R140 sahte-pump');
    if (dc.r140BtcDiv?.score) parts.push(`R140 BTC-div:+${dc.r140BtcDiv.score}`);

    const htf = [];
    if (dc.r110NearSSL) htf.push(`SSL ${r119FmtLevel(dc.r110NearSSL)}`);
    if (dc.r110NearBSL) htf.push(`BSL ${r119FmtLevel(dc.r110NearBSL)}`);
    if (dc.r116CounterLevel) htf.push(`Karşı ${r119FmtLevel(dc.r116CounterLevel)}`);
    if (dc.r117TrapLevel) htf.push(`Ters ${r119FmtLevel(dc.r117TrapLevel)}`);

    const ictDashboard = String(dc.ictDashboard || dc.r88VurKac?.ictDashboard || htf.join(' | ') || '').slice(0,240);
    const siksmaOzet = String(dc.siksmaOzet || dc.r88VurKac?.siksmaOzet || dc.r111Siksma?.ozet || '').slice(0,220);
    const r119HtfDiag = parts.join(' · ').slice(0,260);
    return {
      r111KoprusuOk: !!(dc.r111KoprusuOk || dc.r88VurKac?.r111KoprusuOk),
      siksmaOzet,
      ictDashboard,
      r119HtfDiag,
      r116HtfGuardBlock: !!dc.r116HtfGuardBlock,
      r116HtfGuardReason: String(dc.r116HtfGuardReason || '').slice(0,260),
      r117HtfReverseOk: !!dc.r117HtfReverseOk,
      r117HtfReverseReason: String(dc.r117HtfReverseReason || '').slice(0,260),
      r117NearTrapHTF: !!dc.r117NearTrapHTF,
      r117PrecisionCandleOk: !!dc.r117PrecisionCandleOk,
      r118CandleOk: !!dc.r118CandleOk,
      r118CandleStrong: !!dc.r118CandleStrong,
      r118CandleOzet: String(dc.r118CandleOzet || '').slice(0,220),
      r140Summary: String([
        dc.r140Phase?.phase ? `faz:${dc.r140Phase.phase}` : '',
        dc.r140OiVel?.summary ? dc.r140OiVel.summary : '',
        dc.r140BtcDiv?.label ? dc.r140BtcDiv.label : '',
        dc.r140EqHL?.summary ? dc.r140EqHL.summary : '',
        dc.r140Rvol?.signal ? `RVOL:${dc.r140Rvol.signal}×${dc.r140Rvol.rvol}` : ''
      ].filter(Boolean).join(' · ')).slice(0,260)
    };
  } catch {
    return {};
  }
}

function pushAutoCandidate(row) {
  const symKey = String(row.symbol||'').replace('USDT','');
  const recKey = row.rec || 'WAIT';
  const prevDiag = autoDiagBySymbol.get(`${symKey}_${recKey}`) || autoDiagBySymbol.get(symKey) || {};
  const r = {
    ts:Date.now(),
    symbol:symKey,
    rec:recKey, recTR:trSideLabel(row.rec), tier:row.tier||'WAIT', tierTR:trTierLabel(row.tier||'WAIT'), score:Number(row.score||0),
    longScore:Number(row.longScore||0), shortScore:Number(row.shortScore||0),
    priorityScore:Number(row.priorityScore||0),
    reason:toTurkishText(String(row.reason||row.block||'—')).slice(0,220),
    reasonTR:toTurkishText(String(row.reason||row.block||'—')).slice(0,220),
    action:toTurkishText(String(row.action||'İzle')).slice(0,120),
    actionTR:toTurkishText(String(row.action||'İzle')).slice(0,120),
    sweepRequired: row.sweepRequired,
    entryPermissionReason: row.entryPermissionReason || '',
    entryPermissionReasonTR: toTurkishText(row.entryPermissionReason || ''),
    cvdMissing: !!row.cvdMissing,
    r45RvolStatus: row.r45RvolStatus || '',
    sikismaAktif: !!(row.r111KoprusuOk ?? row.sikismaAktif ?? prevDiag.sikismaAktif),
    siksmaOzet: String(row.siksmaOzet || prevDiag.siksmaOzet || '').slice(0,180),
    ictDashboard: String(row.ictDashboard || prevDiag.ictDashboard || '').slice(0,180),
    htfTani: String(row.r119HtfDiag || row.htfTani || prevDiag.htfTani || '').slice(0,260),
    htfBlok: !!((row.r117HtfReverseOk ? false : row.r116HtfGuardBlock) ?? row.htfBlok ?? prevDiag.htfBlok),
    htfBlokSebep: row.r117HtfReverseOk ? '' : String(row.r116HtfGuardReason || row.htfBlokSebep || prevDiag.htfBlokSebep || '').slice(0,260),
    tersHedef: !!(row.r117HtfReverseOk ?? row.tersHedef ?? prevDiag.tersHedef),
    tersHedefSebep: String(row.r117HtfReverseReason || row.tersHedefSebep || prevDiag.tersHedefSebep || '').slice(0,260),
    tersBolge: !!(row.r117NearTrapHTF ?? row.tersBolge ?? prevDiag.tersBolge),
    hassasMumOk: !!(row.r117PrecisionCandleOk ?? row.hassasMumOk ?? prevDiag.hassasMumOk),
    mumOnay: !!(row.r118CandleOk ?? row.mumOnay ?? prevDiag.mumOnay),
    mumGuclu: !!(row.r118CandleStrong ?? row.mumGuclu ?? prevDiag.mumGuclu),
    mumOzet: String(row.r118CandleOzet || row.mumOzet || prevDiag.mumOzet || '').slice(0,220),
    brainMode: row.brainMode || row.brain?.mode || '',
    brainAction: row.brainAction || row.brain?.action || (row.autoOk ? 'TRADE' : 'WAIT'),
    brainConfidence: Number(row.brainConfidence || row.brain?.confidence || 0),
    brainSummary: String(row.brainSummary || row.brain?.summary || '').slice(0,500),
    r125OrderflowSummary: String(row.r125OrderflowSummary || row.r125Flow?.summary || '').slice(0,300),
    r126FlowSummary: String(row.r126FlowSummary || row.r125Flow?.r126?.summary || '').slice(0,260),
    r140Summary: String(row.r140Summary || prevDiag.r140Summary || '').slice(0,260),
    r126PlaybookAdj: Number(row.r126PlaybookAdj || (row.brainMode ? r126PlaybookAdj(row.brainMode) : 0)),
    r125BestSide: row.r125BestSide || row.r125Flow?.bestSide || '',
    r125LiveDeltaPct: Number(row.r125LiveDeltaPct || row.r125Flow?.deltaPct || 0),
    autoOk: !!row.autoOk,
    decisionStage: (String(row.action||'').toLowerCase().includes('atlandı') || String(row.rec||'').toUpperCase()==='WAIT' || /MEKANİK BEKLE|giriş-hikâye sözleşmesi/i.test(String(row.reason||''))) ? 'FINAL' : 'PRE_ANALYSIS',
    preAnalysis: row.preAnalysis || null
  };
  const diagKeep = {
    sikismaAktif:r.sikismaAktif, siksmaOzet:r.siksmaOzet, ictDashboard:r.ictDashboard,
    htfTani:r.htfTani, htfBlok:r.htfBlok, htfBlokSebep:r.htfBlokSebep,
    tersHedef:r.tersHedef, tersHedefSebep:r.tersHedefSebep, tersBolge:r.tersBolge,
    hassasMumOk:r.hassasMumOk, mumOnay:r.mumOnay, mumGuclu:r.mumGuclu, mumOzet:r.mumOzet,
    r125OrderflowSummary:r.r125OrderflowSummary, r126FlowSummary:r.r126FlowSummary, r140Summary:r.r140Summary, r126PlaybookAdj:r.r126PlaybookAdj, r125BestSide:r.r125BestSide, r125LiveDeltaPct:r.r125LiveDeltaPct
  };
  autoDiagBySymbol.set(`${r.symbol}_${r.rec}`, diagKeep);
  autoDiagBySymbol.set(r.symbol, diagKeep);
  // R486.3.2: Aynı sembol için ön analiz TRADE ve nihai sözleşme WAIT iki ayrı satır olmasın.
  // Nihai kayıt kazanır; önceki fiziksel setup özeti preAnalysis altında korunur.
  const prevRow=(autoScanState.topCandidates||[]).find(x=>x.symbol===r.symbol);
  if(prevRow && r.decisionStage==='FINAL' && (prevRow.autoOk || prevRow.brainAction==='TRADE' || prevRow.decisionStage==='PRE_ANALYSIS')){
    r.preAnalysis={rec:prevRow.rec,tier:prevRow.tier,score:prevRow.score,brainAction:prevRow.brainAction,autoOk:prevRow.autoOk,reason:prevRow.reason};
  }
  if(prevRow && r.decisionStage==='PRE_ANALYSIS' && prevRow.decisionStage==='FINAL'){
    prevRow.preAnalysis={rec:r.rec,tier:r.tier,score:r.score,brainAction:r.brainAction,autoOk:r.autoOk,reason:r.reason};
    return;
  }
  autoScanState.topCandidates=(autoScanState.topCandidates||[]).filter(x=>x.symbol!==r.symbol);
  autoScanState.topCandidates.push(r);
  const tierRank = t => t==='A'?3:t==='B+'?2:t==='B'?1:0;
  autoScanState.topCandidates = autoScanState.topCandidates
    .sort((a,b)=>tierRank(b.tier)-tierRank(a.tier) || b.score-a.score || (b.priorityScore||0)-(a.priorityScore||0) || b.ts-a.ts)
    .slice(0,12);
}
function markAutoSkip(symbol, reason, row={}) {
  // V4.7.4.12-N1: panel anahtari 90 karakterle sinirli kalir (dedup icin),
  // ama KANITA tam metin yazilir. Eskiden funnel de 90'da kesiliyordu ve
  // WAIT'i kimin verdigi (V4.5 selektor / R495 / mekanik) gorunmez oluyordu.
  const _fullReason = toTurkishText(String(reason||'Bilinmeyen'));
  const key = _fullReason.slice(0,90);
  autoScanState.skipped = (autoScanState.skipped||0) + 1;
  autoScanState.skipReasons[key] = (autoScanState.skipReasons[key]||0) + 1;
  if (symbol) pushAutoCandidate({symbol, reason:key, action:'Atlandı', ...row});
  try { r501EvidenceFunnel({type:'SKIP',symbol:normalizeSymbol(symbol||''),action:'SKIP',authority:row?.authority||row?.gate||'AUTO_PIPELINE',reason:key,reasonFull:_fullReason.slice(0,600),waitSource:row?.waitSource||null,score:row?.score??null,tier:row?.tier??null,rec:row?.rec??null,decisionImpact:false}); } catch(_r501e) {}
  // V680-D: her atlama sebebi beyne de yazilir. decisionImpact YOK.
  try { v679SonKarar(symbol, 'ATLANDI', _fullReason); } catch(_v680e) {}
}

// R308B: AI B-modu için analiz sırasında dolan zengin context havuzu.
// Amaç: Eski kapılar adayı elese bile scan sonunda en iyi 1-2 adayı AI'ya göstermek.
const autoAiContextBySymbol = new Map();

function r308AiDayKey() { return new Date().toISOString().slice(0,10); }
function r308ReserveAiSpend(symbol, source='R308', fingerprint='') {
  const day = r308AiDayKey();
  if (r308AiSpendDay !== day) {
    r308AiSpendDay = day;
    r308AiSpendCount = 0;
    r308AiLastBySymbol.clear();
  }
  if (r308AiSpendCount >= AI_BRAIN_MAX_DAILY_CALLS) {
    return { ok:false, reason:`günlük AI limit dolu ${r308AiSpendCount}/${AI_BRAIN_MAX_DAILY_CALLS}` };
  }
  const sym = String(symbol||'').replace('USDT','').toUpperCase();
  const now = Date.now();
  const prev = r308AiLastBySymbol.get(sym);
  // R311B: tekrar freni SADECE coin durumu AYNIYSA uygulanır. Durum değiştiyse (yeni setup, farklı fingerprint)
  // AI'ya gitsin — EIGEN R285 q:99.8 gibi mükemmel YENİ setup'lar "tekrar freni" yüzünden kaçmasın. reviewGap'in
  // amacı aynı değişmemiş duruma tekrar para harcamamak; yeni fırsatı engellemek DEĞİL. fingerprint zaten setup'ın
  // özeti (yön+kademe+seviye). Farklıysa = yeni durum = AI'ya değer.
  const curFp = String(fingerprint||'').slice(0,120);
  const sameState = prev && curFp && String(prev.fingerprint||'') === curFp;
  // R440: patlama bayrağı TAZE olan coinde tekrar freni YARIYA iner — dikey koşuda 7 dk beklemek
  // koşunun kendisini kaçırtıyordu (ZAMA 20.07 dersi: skor 90+ ile 1 saat slot aldı, işlem doğmadı).
  let r440Gap = AI_BRAIN_REVIEW_GAP_MS;
  try {
    const _pf = (typeof __r328PatlamaFlags === 'object' && __r328PatlamaFlags) ? __r328PatlamaFlags[sym] : null;
    if (_pf && _pf.detected && (now - _pf.ts < 10*60*1000)) r440Gap = Math.round(AI_BRAIN_REVIEW_GAP_MS / 2);
  } catch(_e) {}
  // R442: pusu tetiklendiyse tekrar freni TEK SEFERLİK atlanır — fiyat AI'ın kendi istediği yere geldi
  const r442Force = r442ForceAi.get(sym);
  if (r442Force && (now - r442Force < 5*60*1000)) {
    r442ForceAi.delete(sym);
    logAuto(`🎯 ${sym} R442: pusu tetiği — tekrar freni atlandı, ${r451Merci()} taze veriyle karar veriyor`);
  } else if (prev && sameState && r440Gap > 0 && now - prev.ts < r440Gap) {
    return { ok:false, reason:`${sym} tekrar freni ${Math.ceil((r440Gap - (now-prev.ts))/1000)}sn (durum aynı)` };
  }
  r308AiSpendCount += 1;
  r308AiLastBySymbol.set(sym, { ts:now, source, fingerprint:curFp });
  return { ok:true, count:r308AiSpendCount };
}

function r308RememberAiContext(symbol, coin, analysis, decisionChain, recommendation, score, skipReason='') {
  try {
    const sym = String(symbol || coin?.symbol || coin?.fullSymbol || '').replace('USDT','').toUpperCase();
    if (!sym || !analysis) return;
    const r300Rsi5m = Number(analysis?.timeframes?.['5m']?.rsi);
    const r300Rsi4h = Number(analysis?.timeframes?.['4h']?.rsi);
    const rangePos = Number.isFinite(decisionChain?._r276RangePos) ? decisionChain._r276RangePos
      : (decisionChain?.r281ProMap && Number.isFinite(decisionChain.r281ProMap.rangePos) ? decisionChain.r281ProMap.rangePos : 0.5);
    autoAiContextBySymbol.set(sym, {
      aiSource: 'R308D_TOP1_SCAN',
      recommendation, score, skipReason,
      lastPrice: Number(coin?.lastPrice || analysis?.price || analysis?.lastPrice || analysis?.ticker?.lastPrice || 0),
      rsi5m: Number.isFinite(r300Rsi5m) ? r300Rsi5m : undefined,
      rsi15m: analysis?.timeframes?.['15m']?.rsi,
      rsi1h: analysis?.timeframes?.['1h']?.rsi,
      rsi4h: Number.isFinite(r300Rsi4h) ? r300Rsi4h : analysis?.timeframes?.['4h']?.rsi,
      trend5m: analysis?.timeframes?.['5m']?.trend, trend15m: analysis?.timeframes?.['15m']?.trend,
      trend1h: analysis?.timeframes?.['1h']?.trend, trend4h: analysis?.timeframes?.['4h']?.trend,
      structure: decisionChain?.htfTani || decisionChain?.mumOzet || decisionChain?.r119HtfDiag || '',
      liquidity: decisionChain?.ictDashboard || '',
      fvg: decisionChain?.r274Signal?.summary || analysis?.fvg || '',
      ote: decisionChain?.r110ICT?.summary || '',
      sweepInfo: decisionChain?.r289Summary || String(decisionChain?.brainSummary||decisionChain?.reason||'').slice(0,260),
      flow: decisionChain?.r125OrderflowSummary || '',
      funding: analysis?.funding?.current,
      oiChange: decisionChain?.r140Summary || '',
      // ═══ V632 ═══ `decisionChain.r111Sonuc` HIC YAZILMIYOR (5 okuma, 0 yazma) —
      // bu alan her zaman 'yok' donuyordu. Calisan kaynaklara baglandi:
      // story.oi.state (SHORT_SQUEEZE/LONG_BUILD) ve r190Edge.squeeze.
      squeeze: (() => {
        const _oi = String(decisionChain?.r483Story?.oi?.state || '').toUpperCase();
        if (decisionChain?.r111Sonuc?.shortSqueeze || _oi === 'SHORT_SQUEEZE') return 'shortSqueeze';
        if (decisionChain?.r111Sonuc?.longSqueeze) return 'longSqueeze';
        if (decisionChain?.r190Edge?.squeeze) return 'edgeSqueeze';
        return 'yok';
      })(),
      atrPct: analysis?.leverage?.atrPct || decisionChain?.coinAtrPct,
      rangePos,
      candleSummary: decisionChain?.mumOzet || decisionChain?.r118CandleOzet || '',
      // R311X: KABA fingerprint — mikro oynamalar (skor 67→68, reason'da sayı değişimi) "yeni durum" sayılıp
      // AI'ya boşa tekrar sordurmasın. Sadece GERÇEK değişiklik yeni çağrı tetikler: yön / skor-dilimi(10luk) /
      // sweep var-yok / tier. Sweep geldiğinde ya da yön döndüğünde fingerprint zaten değişir → fırsat kaçmaz.
      fingerprint: [
        recommendation,
        Math.floor(Number(score||0)/10)*10,                                  // 67 ve 68 → ikisi de 60 dilimi
        (/sweep|süpür|reclaim|geri kazan|✅/i.test(String(decisionChain?.r289Summary||decisionChain?.ictDashboard||decisionChain?.reason||'')) ? 'SW1' : 'SW0'), // sweep durumu değişti mi
        String(decisionChain?.tier||decisionChain?.tierTR||'').slice(0,3)
      ].join('|')
    });
  } catch(_) {}
}

function r308BuildAiDataFromCandidate(c) {
  const sym = String(c?.symbol||'').replace('USDT','').toUpperCase();
  const ctx = autoAiContextBySymbol.get(sym) || {};
  return {
    ...ctx,
    aiSource: 'R308D_TOP1_SCAN',
    recommendation: c?.rec || ctx.recommendation || null,
    score: Number(c?.score || ctx.score || 0),
    skipReason: c?.reason || ctx.skipReason || '',
    structure: ctx.structure || c?.htfTani || c?.mumOzet || '',
    liquidity: ctx.liquidity || c?.ictDashboard || '',
    flow: ctx.flow || c?.r125OrderflowSummary || c?.r126FlowSummary || '',
    oiChange: ctx.oiChange || c?.r140Summary || '',
    candleSummary: ctx.candleSummary || c?.mumOzet || '',
    fingerprint: ctx.fingerprint || [c?.rec, Math.floor(Number(c?.score||0)/10)*10, (/sweep|süpür|reclaim|geri kazan|✅/i.test(String(c?.reason||'')) ? 'SW1':'SW0'), String(c?.tier||'').slice(0,3)].join('|')
  };
}

function r308AiPlanQuality(ai) {
  try {
    const side = String(ai?.side || '').toUpperCase();
    const entry = Number(ai?.entry);
    const tp = Number(ai?.tp);
    const sl = Number(ai?.sl);
    const conf = Number(ai?.confidence || 0);
    // R308Y: GÜVEN TABANI 64. AI 64 altı güvenle açamaz (zayıf işlem = kayıp kaynağı). 64+ ise karar AI'ya bırakılır.
    // Sadece plan GEÇERLİLİĞİ + aşırı-geniş-SL güvenliği + güven tabanı kontrol edilir.
    if (!['LONG','SHORT'].includes(side)) return { ok:false, reason: ai?.mekanik ? `MEKANİK GİRİŞ SÖZLEŞMESİ ${side||'WAIT'} dedi` : `AI ${side||'WAIT'} dedi` };
    if (conf < AI_BRAIN_CONF_FLOOR) return { ok:false, reason: ai?.mekanik ? `Mekanik güven ${conf}% < ${AI_BRAIN_CONF_FLOOR} taban — işlem açılmadı` : `AI güven ${conf}% < ${AI_BRAIN_CONF_FLOOR} taban — zayıf işlem açılmadı (AI yeterince emin değil)` };
    if (![entry,tp,sl].every(x => Number.isFinite(x) && x > 0)) return { ok:false, reason:'AI giriş/TP/SL sayısal değil' };
    const isLong = side === 'LONG';
    if (isLong && !(tp > entry && sl < entry)) return { ok:false, reason:'AI LONG TP/SL yönü hatalı' };
    if (!isLong && !(tp < entry && sl > entry)) return { ok:false, reason:'AI SHORT TP/SL yönü hatalı' };
    const risk = Math.abs(entry - sl);
    const reward = Math.abs(tp - entry);
    if (!(risk > 0 && reward > 0)) return { ok:false, reason:'AI risk/ödül sıfır' };
    const rr = reward / risk;
    const slPct = risk / entry * 100;
    // R334: SL LİMİTİ KALDIRILDI (kullanıcı kararı) — AI ne derse o. Volatil gainer coinlerde sweep dibi doğal olarak
    // geniş SL gerektirir (%9 gibi); dar limit iyi işlemleri reddediyordu (TLM tipi kaçan işlemler). AI kendi SL'ini seçer.
    // GÜVENLİK: geniş SL'de likidasyon riskini kaldıraç dengeler — executeLeverage SL%'ye göre otomatik düşürülür (aşağıda).
    // (Eski %3/%6 red kaldırıldı; AI'ın yargısı esas.)
    if (!(slPct > 0)) return { ok:false, reason:'AI SL geçersiz (0 ya da negatif)' };
    // NOT (R310O): R310N min R/R zorlaması KALDIRILDI — AI bazen düşük R/R'lı ama yüksek-olasılıklı scalp
    // setup görür (yakın TP, kesin kâr). Katı R/R dayatmak AI'nın yargısını ezer = boğma. R/R bilgi olarak
    // hesaplanıp gösterilir; AI kendi değerlendirir. Sadece SL aşırı genişliği (güvenlik) ve güven tabanı kalır.
    return { ok:true, rr, slPct, confidence:conf };
  } catch(e) {
    return { ok:false, reason:String(e?.message || e).slice(0,120) };
  }
}

