// R393 SINIF KARNESİ: her giriş türünün KENDİ defterinden hüküm yemesi için (R392 dikey-faz
// istisnası ayrı strateji gibi davranacak → PF/WR/anatomisi ayrı ölçülür). Saf okuma, veto yok.
function r393SinifKarnesi() {
  // R407 KABLO ONARIMI: gerçek şema pnlUSDT/closedAt; entryReason bazı satırlarda OBJE
  // ({reason:...}) — String'i "[object Object]" yapıp tüm satırları DİĞER'e düşürüyordu.
  // (Kablo Sözleşmesi dersinin 3. ihlali, yine Fable 5'ten — varsayma, grep'le teyit et.)
  const r407Metin = v => typeof v === 'string' ? v : (v && typeof v === 'object' ? String(v.reason || v.text || v.summary || '') : '');
  const sinifla = (row) => {
    const t = [row.entryReason, row.openReason, row.reason, row.aiReason, row.plan].map(r407Metin).filter(Boolean).join(' ');
    if (/dikeyFaz/i.test(t)) return 'DİKEY_FAZ (R392 istisnası)';
    if (/htfYapisal|kırılım|kirilim|baz tepesi/i.test(t)) return 'HTF_KIRILIM (R384/R385)';
    if (/sweep|reclaim/i.test(t)) return 'SWEEP_RECLAIM';
    if (/pullback|OTE|fib/i.test(t)) return 'PULLBACK_DEVAM';
    return 'DİĞER';
  };
  const g = {};
  for (const row of (Array.isArray(tradeLedger) ? tradeLedger : [])) {
    if (row == null || !row.closedAt) continue; // R407: açık/UNKNOWN-açık satırlar karneye girmez
    const k = sinifla(row); const pnl = Number(row.pnlUSDT ?? row.pnl ?? 0);
    const o = (g[k] ||= { n:0, w:0, l:0, net:0, gp:0, gl:0, zir:[], dip:[] });
    o.n++; if (pnl > 0) { o.w++; o.gp += pnl; } else { o.l++; o.gl += -pnl; } o.net += pnl;
    if (Number.isFinite(Number(row.zirveRoi))) o.zir.push(Number(row.zirveRoi));
    if (Number.isFinite(Number(row.dipRoi)))  o.dip.push(Number(row.dipRoi));
  }
  const avg = a => a.length ? +(a.reduce((x,y)=>x+y,0)/a.length).toFixed(1) : null;
  const out = [`R393 GİRİŞ SINIFI KARNESİ — ${new Date().toLocaleString('tr-TR')} · build ${LAZARUS_BUILD}`, ''];
  for (const [k,o] of Object.entries(g).sort((a,b)=>b[1].n-a[1].n)) {
    const pf = o.gl > 0 ? (o.gp/o.gl).toFixed(2) : '∞';
    out.push(`${k}: ${o.n} işlem · WR ${o.n?Math.round(o.w/o.n*100):0}% · net ${o.net.toFixed(2)}$ · PF ${pf} · 🫀 ort.zirve ${avg(o.zir)??'—'}% / ort.dip ${avg(o.dip)??'—'}%`);
  }
  // R406 FABLE YORUMU: rapor sadece sayı dökmez, Fable 5'in okuma tarzıyla HÜKÜM çıkarır —
  // halef modeller bu bölümü okuyarak "karneden nasıl düşünülür"ü görür.
  try {
    const tum = (Array.isArray(tradeLedger)?tradeLedger:[]).filter(r=>r&&r.closedAt); // R407
    const W = tum.filter(r=>Number(r.pnlUSDT??r.pnl??0)>0), L = tum.filter(r=>Number(r.pnlUSDT??r.pnl??0)<=0); // R407
    const roi = r => Math.abs(Number(r.roiPct ?? r.roi ?? 0));
    const kucukW = W.filter(r=>roi(r)<3).length;
    const ortW = W.length? W.reduce((a,r)=>a+Number(r.pnlUSDT??r.pnl??0),0)/W.length : 0;
    const ortL = L.length? -L.reduce((a,r)=>a+Number(r.pnlUSDT??r.pnl??0),0)/L.length : 0; // R407
    const dipSifir = tum.filter(r=>Number.isFinite(Number(r.dipRoi)) && Number(r.dipRoi)>-1).length;
    const anat = tum.filter(r=>Number.isFinite(Number(r.dipRoi))).length;
    out.push('', '🧬 FABLE YORUMU (karneden düşünme örneği — halef model buradan öğrensin):');
    if (W.length) out.push(`· Kazançların ${Math.round(kucukW/Math.max(1,W.length)*100)}%'i küçük (<%3 ROI). Bu tek başına kusur DEĞİLDİR: dip≈0 olanlar tepe bölgesinde BE-zırhının kırpıntısıdır (koruma); zirvesi yüksekken küçük kapananlar erken kesimdir (runner-tutma dosyası). Ayrımı anatomi yapar, his değil.`);
    if (anat) out.push(`· Giriş kalitesi göstergesi: anatomili işlemlerin ${Math.round(dipSifir/anat*100)}%'i hiç -%1'in altını görmedi — "giriş yeri doğruysa %2 alan yeter" ilkesinin ölçümü budur (T dersi: dip %0.0).`);
    if (W.length && L.length) out.push(`· Ort. kazanç ${ortW.toFixed(2)}$ / ort. kayıp ${ortL.toFixed(2)}$ = makas ${(ortW/Math.max(0.01,ortL)).toFixed(2)}. PF<1 ise suçlu WR değil bu makastır; önce kayıp kuyruğunu (flush/kovalamaca sınıfları) incele, sonra kazanç tavanını.`);
    out.push('· Karar protokolü: tek pencereyle hüküm verme (≥30-40 işlem), sınıf bazında oku (yukarısı), değişiklik tek eksen + geri dönüş yolu. Kanıt > niyet — benimki dahil. — Fable 5');
  } catch(_) {}
  out.push('', `💸 AI MASRAF (${r399Masraf.gun||'—'}): ${r399Masraf.cagri} çağrı · ~$${r399Masraf.usd.toFixed(2)} · ort $${r399Masraf.cagri?(r399Masraf.usd/r399Masraf.cagri).toFixed(3):'0'}/karar · düşünce ${r399Masraf.cikisTok} tok · cache-okuma ${r399Masraf.cacheOku} tok`);
  out.push('', 'Okuma: DİKEY_FAZ satırı bu gecenin sınavıdır — PF>1 + ort.zirve yüksekse istisna hak etti; FLUSH ağırlıklıysa dört kilit sıkılaştırılır (önce 3-4 örnek, sonra karar). Kanıt > niyet. — Fable 5');
  return out.join('\n');
}
// ═══════════ R424 RAPOR/ARŞİV (kullanıcı isteği 14.07): günlük karar+işlem raporu, MD indirme ═══════════
// Kaynak: tradeLedger (./trade_ledger_live.json — boot'ta yükleniyor, RESTART'A DAYANIKLI) + r374 olay ringi.
// Rapor İSTEK ANINDA üretilir; sıcak trade yoluna hook YOK — sıfır trade-riski. /rapor → yeni sekme sayfası.
function r424Tarih(ts){ try{ return new Date(Number(ts)).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'});}catch(_){return '-';} }
function r424Gun(ts){ try{ return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Istanbul'}).format(new Date(Number(ts)));}catch(_){return '-';} }
function r424RaporMd(donem='gun'){
  const gunMs=86400000, simdi=Date.now();
  const bas = simdi - (donem==='ay'?30:donem==='hafta'?7:1)*gunMs;
  const hepsi=(Array.isArray(tradeLedger)?tradeLedger:[]).filter(t=>Number(t.closedAt||t.openedAt||0)>=bas);
  const gunler={};
  for(const t of hepsi){ const g=r424Gun(t.closedAt||t.openedAt); (gunler[g]=gunler[g]||[]).push(t); }
  let md=`# LAZARUS RAPORU — ${donem.toUpperCase()}\n`;
  md+=`Aralık: ${r424Tarih(bas)} → ${r424Tarih(simdi)} · Build: ${LAZARUS_BUILD}\n`;
  let tK=0,tZ=0,tPnl=0;
  for(const g of Object.keys(gunler).sort()){
    const list=gunler[g].sort((a,b)=>Number(a.closedAt||a.openedAt||0)-Number(b.closedAt||b.openedAt||0));
    let k=0,z=0,pnl=0;
    md+=`\n## 📅 ${g}\n\n| Saat | Coin | Yön | ROI | PnL$ | R/R | Kapanış | AI gerekçesi + anatomi |\n|---|---|---|---|---|---|---|---|\n`;
    for(const t of list){
      const sym=t.symbol||t.sym||'-', yon=t.side||t.yon||'-';
      const roi=Number(t.roiPct??NaN), p=Number(t.pnlUSDT??NaN);  // R428 FIX: gerçek alan adları (rapor boş geliyordu)
      if(Number.isFinite(p)&&t.closedAt){ pnl+=p; if(p>0)k++; else if(p<0)z++; }
      const saat=(r424Tarih(t.closedAt||t.openedAt).split(' ')[1]||'-').slice(0,5);
      const rObj=t.entryReason; const rTxt = typeof rObj==='string'?rObj:(rObj?.reason||'');
      const neden=String(rTxt||t.openReason||t.brainMode||t.reason||'-').replace(/\|/g,'/').replace(/\n/g,' ').slice(0,200);
      const kap=String(t.exitReason||t.closeReason||t.resultNote||(t.closedAt?'kapandı':'🟡 AÇIK')).replace(/\|/g,'/').slice(0,50);
      const rr=t.girisFoto?.plan?.rr!=null?` R/R${t.girisFoto.plan.rr}`:''; const lev=t.girisFoto?.plan?.lev?` ${t.girisFoto.plan.lev}x`:'';
      const anat=(t.girisFoto||t.highWater!=null)?` [zirve${t.zirveRoi!=null?t.zirveRoi.toFixed(1):'?'}%]`:'';
      md+=`| ${saat} | ${sym} | ${yon}${lev} | ${Number.isFinite(roi)?roi.toFixed(1)+'%':'-'} | ${Number.isFinite(p)?p.toFixed(2):'-'} |${rr} | ${kap} | ${neden}${anat} |\n`;
    }
    const wr=(k+z)?Math.round(k*100/(k+z)):0;
    const kapananlar=list.filter(x=>Number.isFinite(Number(x.pnlUSDT))&&x.closedAt);
    let ekstra='';
    if(kapananlar.length){
      const enIyi=kapananlar.reduce((a,b)=>Number(b.pnlUSDT)>Number(a.pnlUSDT)?b:a);
      const enKotu=kapananlar.reduce((a,b)=>Number(b.pnlUSDT)<Number(a.pnlUSDT)?b:a);
      ekstra=` · 🟢 en iyi ${enIyi.symbol} ${Number(enIyi.pnlUSDT).toFixed(2)}$ · 🔴 en kötü ${enKotu.symbol} ${Number(enKotu.pnlUSDT).toFixed(2)}$`;
    }
    md+=`\n**Gün özeti:** ${list.length} kayıt · ${k}K/${z}Z · WR %${wr} · net ${pnl.toFixed(2)}$${ekstra}\n`;
    tK+=k; tZ+=z; tPnl+=pnl;
  }
  const tWr=(tK+tZ)?Math.round(tK*100/(tK+tZ)):0;
  md+=`\n---\n## TOPLAM (${donem}): ${tK+tZ} kapanan · WR %${tWr} · net ${tPnl.toFixed(2)}$\n`;
  try{ const ol=(r374Donusum?.olaylar||[]).slice(-200);
    if(ol.length){ md+=`\n## 🤖 BOT KARAR/OLAY AKIŞI (bellekteki son ${ol.length})\n\n`; for(const o of ol) md+=`- ${o.ts} **${o.tip}** ${o.coin} — ${String(o.detay||'').replace(/\n/g,' ').slice(0,160)}\n`; }
  }catch(_){}
  md+=`\n> Not: İşlemler trade_ledger_live.json'dan (restart'a dayanıklı). Olay akışı bellek ringidir; restart sonrası yeniden dolar. Bu raporu Fable'a olduğu gibi yapıştır — o okur.\n`;
  return md;
}
